import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth } from '../../firebase';
import { sendPasswordResetEmail } from 'firebase/auth';
import LoadingScreen from '../../components/LoadingScreen';
import '../ForgotPassword.css';

const ForgotPassword = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isPageLoading, setIsPageLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsPageLoading(false);
    }, 300);
    return () => clearTimeout(timer);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setIsLoading(true);

    try {
      if (!email.trim()) {
        setError('Please enter your email address');
        setIsLoading(false);
        return;
      }

      // Basic email validation
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(email)) {
        setError('Please enter a valid email address');
        setIsLoading(false);
        return;
      }

      // Send password reset email
      await sendPasswordResetEmail(auth, email);

      setSuccess('Password reset link has been sent to your email. Please check your inbox and spam folder.');
      setEmail('');

      // Redirect to login after 3 seconds
      setTimeout(() => {
        navigate('/');
      }, 3000);
    } catch (err) {
      console.error('Password reset error:', err);

      if (err.code === 'auth/user-not-found') {
        setError('No account found with this email address.');
      } else if (err.code === 'auth/invalid-email') {
        setError('Invalid email address. Please try again.');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Too many reset attempts. Please try again later.');
      } else {
        setError(`Error: ${err.message}`);
      }
      setIsLoading(false);
    }
  };

  if (isPageLoading) {
    return <LoadingScreen message="Loading Aksyon Agad..." />;
  }

  return (
    <div className="reset-page">
      <header className="reset-header">
        <div className="header-logo">
          <span className="brand-text">
            <span className="brand-green">AKSYON</span>
            <span className="brand-red">AGAD</span>
          </span>
        </div>
      </header>

      <main className="reset-main">
        <div className="reset-card">
          <div className="reset-card-header">
            <div className="card-logo">
              <span className="brand-text large">
                <span className="brand-green">AKSYON</span>
                <span className="brand-red">AGAD</span>
              </span>
            </div>
            <h1 className="reset-title">Reset Password</h1>
            <p className="reset-subtitle">Enter your email address and we'll send you a link to reset your password.</p>
          </div>

          <form onSubmit={handleSubmit} className="reset-form">
            {error && <div className="error-message">{error}</div>}
            {success && <div className="success-message">{success}</div>}

            <div className="form-group">
              <label htmlFor="email">Email Address</label>
              <div className="input-wrapper">
                <span className="input-icon" aria-hidden>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <path d="m22 6-10 7L2 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </span>
                <input
                  type="email"
                  id="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="name@example.com"
                  required
                  disabled={isLoading}
                />
              </div>
            </div>

            <button type="submit" className="reset-submit" disabled={isLoading}>
              <span className="button-text">
                {isLoading ? 'Sending...' : 'Send Reset Link'}
              </span>
            </button>

            <div className="reset-footer">
              <button
                type="button"
                onClick={() => navigate('/')}
                className="back-link"
                disabled={isLoading}
              >
                <span className="icon" aria-hidden>
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M19 12H5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <path d="M12 19l-7-7 7-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </span>
                Back to Login
              </button>
            </div>

            <div className="secure-ssl-footer">
              <span className="ssl-icon" aria-hidden>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M9 12l2 2 4-4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              </span>
              <span className="ssl-text">Secure SSL Encrypted Connection</span>
            </div>
          </form>
        </div>
      </main>

      <footer className="reset-page-footer">
        © 2026 Aksyon Agad. All rights reserved.
      </footer>
    </div>
  );
};

export default ForgotPassword;
