// src/pages/admin/AdminTask.jsx
import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  MenuItem,
  Select,
  InputLabel,
  FormControl,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  useMediaQuery,
  useTheme,
  Checkbox
} from "@mui/material";
import * as XLSX from "xlsx";
import { saveAs } from "file-saver";
import AssignmentIcon from "@mui/icons-material/Assignment";
import CloudDoneIcon from "@mui/icons-material/CloudDone";
import CloudOffIcon from "@mui/icons-material/CloudOff";
import SearchIcon from "@mui/icons-material/Search";
import AccessTimeIcon from "@mui/icons-material/AccessTime";
import { Add } from "@mui/icons-material";
import EncodingSidebar from "../../components/EncodingSidebar";
import io from "socket.io-client";

const SERVER_URL = "http://192.168.0.149:4000";; // LAN server IP


const AdminTask = () => {

  const [importedFiles, setImportedFiles] = useState([]);
  const [selectedFile, setSelectedFile] = useState("");
  const [fileData, setFileData] = useState([]);
  const [search, setSearch] = useState("");
  const [connected, setConnected] = useState(false);
  const [openAddColumn, setOpenAddColumn] = useState(false);
  const [newColumnName, setNewColumnName] = useState("");
  const [newColumnType, setNewColumnType] = useState("Text Field");
  const [dropdownOptions, setDropdownOptions] = useState("");
  const [openCreateTable, setOpenCreateTable] = useState(false);
  const [newTableName, setNewTableName] = useState("");
  const [collapsed, setCollapsed] = useState(false);
  const [serverTime, setServerTime] = useState(new Date());
  // PAGINATION
  const [page, setPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(50);
  const [selectedRows, setSelectedRows] = useState([]);

  const [openPermission, setOpenPermission] = useState(false);
  const [openEdit, setOpenEdit] = useState(false);
  const [openChecker, setOpenChecker] = useState(false);

  const [selectedRowIndex, setSelectedRowIndex] = useState(null);
  const [editRowData, setEditRowData] = useState([]);
  const [checkerName, setCheckerName] = useState("");

  const handleRowClick = (index) => {
  setSelectedRowIndex(index);
  setOpenPermission(true);
};

  const toggleRowSelection = (idx) => {
  setSelectedRows((prev) =>
    prev.includes(idx)
      ? prev.filter((i) => i !== idx)
      : [...prev, idx]
  );
};

const handleFinalSave = () => {
  if (!checkerName.trim()) {
    alert("Please enter checker name.");
    return;
  }

  const newData = [...fileData];

  // Ensure CHECKER column exists
  let checkerIndex = newData[0].indexOf("CHECKER");
  if (checkerIndex === -1) {
    newData[0].push("CHECKER");
    checkerIndex = newData[0].length - 1;

    for (let i = 1; i < newData.length; i++) newData[i].push("");
  }

  // Update edited row
  newData[selectedRowIndex + 1] = [...editRowData];
  newData[selectedRowIndex + 1][checkerIndex] = checkerName;

  setFileData(newData);

  const updatedFiles = importedFiles.map((file) =>
    file.name === selectedFile ? { ...file, data: newData } : file
  );

  // SAVE TO SERVER
  fetch(`${SERVER_URL}/updateData`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(updatedFiles),
  });

  setCheckerName("");
  setOpenChecker(false);
};
   
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down("sm"));
  const isTablet = useMediaQuery(theme.breakpoints.between("sm", "md"));

  const encoderUsername =
    localStorage.getItem("uid")?.replace("offline-", "") || "Unknown";

  // Update server time every second
  useEffect(() => {
    const interval = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(interval);
  }, []);

  // SOCKET CONNECTION
  useEffect(() => {
    const socket = io(SERVER_URL);

    socket.on("connect", () => setConnected(true));
    socket.on("disconnect", () => setConnected(false));

    fetch(`${SERVER_URL}/getData`)
      .then((res) => res.json())
      .then((data) => setImportedFiles(data || []))
      .catch(() =>
        alert("⚠️ Cannot connect to shared server. Ensure admin PC is running.")
      );

    socket.on("dataUpdated", (newData) => {
      setImportedFiles(newData);
      if (selectedFile) {
        const fileEntry = newData.find((f) => f.name === selectedFile);
        setFileData(fileEntry?.data || []);
      }
    });

    return () => socket.disconnect();
  }, [selectedFile]);

  // FILE SELECT HANDLER
  const handleFileSelect = (e) => {
    const fileName = e.target.value;
    setSelectedFile(fileName);

    const fileEntry = importedFiles.find((f) => f.name === fileName);
    let table = fileEntry?.data || [];

    if (table.length > 0) {
      const headers = table[0];
      let encoderIndex = headers.indexOf("Encoder");

      if (encoderIndex === -1) {
        headers.push("Encoder");
        encoderIndex = headers.length - 1;
        for (let i = 1; i < table.length; i++) table[i].push("");
      }
    }

    setFileData([...table]);
  };

  // EXPORT TO EXCEL
  const handleExportExcel = () => {
  if (!fileData.length) return;

  const encoderIdx = fileData[0].indexOf("Encoder");
  const exportData = fileData.map((row) =>
    row.filter((_, idx) => idx !== encoderIdx)
  );

  const ws = XLSX.utils.aoa_to_sheet(exportData);
  const wb = XLSX.utils.book_new();

  // --- FIX: Safe sheet name ---
  let sheetName = selectedFile.replace(/\.xlsx$/i, "") || "Sheet1";
  sheetName = sheetName.substring(0, 31); // Excel max 31 chars
  // Remove invalid Excel sheet name characters: : \ / ? * [ ]
  sheetName = sheetName.replace(/[:\\/?*[\]]/g, "");
  if (!sheetName.trim()) sheetName = "Sheet1";
  // ----------------------------

  XLSX.utils.book_append_sheet(wb, ws, sheetName);

  const wbout = XLSX.write(wb, { bookType: "xlsx", type: "array" });
  const blob = new Blob([wbout], { type: "application/octet-stream" });
  saveAs(blob, `${sheetName}.xlsx`);
};

  // ADD COLUMN
  const handleAddColumn = () => {
    if (!newColumnName.trim()) {
      alert("Please enter a column name.");
      return;
    }

    const updatedData = [...fileData];
    updatedData[0].push(newColumnName);

    let defaultValue = "";
    let options = [];

    if (newColumnType === "Checkbox") defaultValue = false;
    if (newColumnType === "Dropdown") {
      options = dropdownOptions.split(",").map((opt) => opt.trim());
      defaultValue = options[0] || "";
    }

    for (let i = 1; i < updatedData.length; i++) {
      updatedData[i].push(defaultValue);
    }

    if (!updatedData._dropdownOptions) updatedData._dropdownOptions = {};
    if (newColumnType === "Dropdown") {
      updatedData._dropdownOptions[newColumnName] = options;
    }

    const updatedFiles = importedFiles.map((file) =>
      file.name === selectedFile ? { ...file, data: updatedData } : file
    );

    setFileData(updatedData);
    setImportedFiles(updatedFiles);

    fetch(`${SERVER_URL}/updateData`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updatedFiles),
    });

    setOpenAddColumn(false);
    setNewColumnName("");
    setDropdownOptions("");
    setNewColumnType("Text Field");
  };

  // CREATE NEW TABLE
  const handleCreateTable = () => {
    if (!newTableName.trim()) {
      alert("Enter a table name.");
      return;
    }

    const newTable = {
      name: newTableName,
      data: [[]],
    };

    const updatedFiles = [...importedFiles, newTable];
    setImportedFiles(updatedFiles);
    setSelectedFile(newTableName);
    setFileData(newTable.data);

    fetch(`${SERVER_URL}/updateData`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updatedFiles),
    });

    setOpenCreateTable(false);
    setNewTableName("");
  };

  // FILTER ROWS
 const filteredRows = fileData.slice(1).filter((row) =>
  Array.isArray(row) &&
  row.some((cell) =>
    cell?.toString().toLowerCase().includes(search.toLowerCase())
  )
);

  // PAGINATED ROWS
const totalRows = filteredRows.length;
const totalPages = Math.max(1, Math.ceil(totalRows / rowsPerPage));

const paginatedRows = filteredRows.slice(
  (page - 1) * rowsPerPage,
  page * rowsPerPage
);

// Reset page when searching
useEffect(() => {
  setPage(1);
}, [search]);

  const encoderIndex = fileData[0]?.indexOf("Encoder") ?? -1;

  // BULK DELETE //
  const handleBulkDelete = () => {
  if (selectedRows.length === 0) {
    alert("No rows selected.");
    return;
  }

  if (!window.confirm("Are you sure you want to delete selected rows?"))
    return;

  // Filter out selected rows
  const newData = fileData.filter((_, index) => {
    const isHeader = index === 0;
    const isSelected = selectedRows.includes(index - 1); 
    return isHeader || !isSelected;
  });

  // Update state
  setFileData(newData);
  setSelectedRows([]);

  // Save back to server
  const updatedFiles = importedFiles.map((file) =>
    file.name === selectedFile ? { ...file, data: newData } : file
  );

  fetch(`${SERVER_URL}/updateData`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(updatedFiles),
  });

  alert("Selected rows deleted.");
};

// handle Select All //
const handleSelectAll = () => {
  if (selectedRows.length === paginatedRows.length) {
    // unselect all
    setSelectedRows([]);
  } else {
    // select all visible rows
    const allIndices = paginatedRows.map((_, idx) => idx);
    setSelectedRows(allIndices);
  }
};

  return (
    <Box display="flex" flexDirection={isMobile ? "column" : "row"}>
      {!isMobile && (
        <EncodingSidebar collapsed={collapsed} onToggle={setCollapsed} />
      )}

      <Box
        sx={{
          flex: "1 1 auto",
          p: isMobile ? 2 : 3,
          width: isMobile ? "100%" : `calc(100% - ${collapsed ? 60 : 265}px)`,
          transition: "width 0.3s",
          overflowX: "hidden",
        }}
      >
        {/* HEADER */}
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2} flexWrap="wrap">
          <Box display="flex" alignItems="center" gap={1}>
            <AssignmentIcon color="primary" />
            <Typography variant={isMobile ? "h5" : "h4"}>Tasks</Typography>
          </Box>

          <Box display="flex" flexDirection="column" alignItems={isMobile ? "flex-start" : "flex-end"} gap={0.5}>
            <Box display="flex" alignItems="center" gap={1}>
              {connected ? (
                <CloudDoneIcon sx={{ color: "green" }} />
              ) : (
                <CloudOffIcon sx={{ color: "red" }} />
              )}
              <Typography sx={{ fontWeight: "bold", fontSize: isMobile ? "0.9rem" : "1rem" }}>
                {connected ? "Live Sync Connected" : "Offline"}
              </Typography>
            </Box>

            <Box display="flex" alignItems="center" gap={1}>
              <AccessTimeIcon sx={{ fontSize: "1rem", color: "gray" }} />
              <Typography variant="body2">
                Server Time: {serverTime.toLocaleString()}
              </Typography>
            </Box>
          </Box>
        </Box>

        {/* FILE SELECT */}
        <Box display="flex" flexDirection={isMobile || isTablet ? "column" : "row"} gap={2} mb={3}>
          <FormControl fullWidth={isMobile || isTablet} sx={{ minWidth: 250 }}>
            <InputLabel>Select Imported Task</InputLabel>
            <Select
              value={selectedFile}
              label="Select Imported Task"
              onChange={handleFileSelect}
            >
              {importedFiles.map((file) => (
                <MenuItem key={file.name} value={file.name}>
                  {file.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {selectedFile && (
            <Button
              variant="contained"
              color="success"
              sx={{ whiteSpace: "nowrap", mt: isMobile || isTablet ? 1 : 0 }}
              onClick={handleExportExcel}
            >
              Export to Excel
            </Button>
          )}

          {!selectedFile && (
            <Button
              variant="contained"
              onClick={() => setOpenCreateTable(true)}
            >
              Create Table
            </Button>
          )}
        </Box>

        {/* Total Encoded */}
        {selectedFile && (
          <Typography variant="h5" fontWeight="bold" sx={{ mb: 1 }}>
            Total Encoded: {fileData.length > 1 ? fileData.length - 1 : 0}
          </Typography>
        )}

        {selectedFile && (
          <Box mb={2}>
            <TextField
              fullWidth
              label="Search..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search all columns"
              size="small"
              InputProps={{
                startAdornment: <SearchIcon sx={{ mr: 1, color: "gray" }} />,
              }}
            />
          </Box>
        )}

        {/* TABLE */}
    {fileData.length > 0 && (
      <>

    {/* ⭐ BULK DELETE BUTTON – placed BEFORE the table */}
    <Box display="flex" justifyContent="flex-end" mb={1}>
      {selectedRows.length > 0 && (
        <Button
          variant="contained"
          color="error"
          onClick={handleBulkDelete}
        >
          Delete Selected ({selectedRows.length})
        </Button>
      )}
    </Box>

    <TableContainer component={Paper}>
      <Table size="small" sx={{ borderCollapse: "collapse" }}>
        <TableHead>
          <TableRow>
            {/* Select All Checkbox */}
            <TableCell>
              <Checkbox
                checked={selectedRows.length === paginatedRows.length && paginatedRows.length > 0}
                indeterminate={
                  selectedRows.length > 0 &&
                  selectedRows.length < paginatedRows.length
                }
                onChange={handleSelectAll}
              />
            </TableCell>
            {fileData[0].map((header, idx) => (
              <TableCell
                key={idx}
                sx={{
                  fontWeight: "bold",
                  backgroundColor: "#9cc2e5",
                  py: 0.5,
                  px: 3,
                  fontSize: "0.85rem",
                  whiteSpace: "nowrap",
                  border: "1px solid #181818b0",
                }}
              >
                {header}
              </TableCell>
            ))}

            <TableCell
              sx={{
                py: 0.5,
                px: 1,
                border: "1px solid #b0b0b0",
                whiteSpace: "nowrap",
              }}
            >
              <Button
                startIcon={<Add />}
                variant="outlined"
                size="small"
                onClick={() => setOpenAddColumn(true)}
              >
                Add Column
              </Button>
            </TableCell>
          </TableRow>
        </TableHead>

        <TableBody>
          {paginatedRows.map((row, rowIndex) => {
            const globalRowIndex = (page - 1) * rowsPerPage;
            const actualIndex = globalRowIndex + rowIndex;
            const statusIndex = fileData[0].indexOf("STATUS");
            const isReturn =
              statusIndex !== -1 &&
              row[statusIndex]?.toUpperCase() === "RETURN";

            return (
              <TableRow
              key={rowIndex}
              onClick={() => handleRowClick(actualIndex)}
              sx={{
                backgroundColor: isReturn ? "yellow" : "inherit",
                cursor: "pointer"
              }}
            >
                {/* Checkbox column */}
                <TableCell
                  sx={{
                    py: 0.5,
                    px: 1,
                    fontSize: "0.85rem",
                    whiteSpace: "nowrap",
                    border: "1px solid #b0b0b0",
                  }}
                >
                 <Checkbox
                  checked={selectedRows.includes(actualIndex)}
                  onChange={() => toggleRowSelection(actualIndex)}
                />
                </TableCell>

                {/* Other row cells */}
                {row.map((cell, cellIndex) => (
                  <TableCell
                    key={cellIndex}
                    sx={{
                      py: 0.5,
                      px: 1,
                      fontSize: "0.85rem",
                      whiteSpace: "nowrap",
                      border: "1px solid #b0b0b0",
                    }}
                  >
                    {cellIndex === encoderIndex
                      ? cell || encoderUsername
                      : String(cell)}
                  </TableCell>
                ))}
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </TableContainer>

    {/* PAGINATION CONTROLS */}
    <Box
      display="flex"
      justifyContent="space-between"
      alignItems="center"
      mt={2}
      p={1}
      component={Paper}
    >
      {/* Rows Per Page */}
      <Box display="flex" alignItems="center" gap={1}>
        <Typography>Rows per page:</Typography>
        <Select
          size="small"
          value={rowsPerPage}
          onChange={(e) => {
            setRowsPerPage(e.target.value);
            setPage(1);
          }}
        >
          {[25, 50, 100, 200, 500].map((n) => (
            <MenuItem key={n} value={n}>
              {n}
            </MenuItem>
          ))}
        </Select>
      </Box>

      {/* Page Indicator */}
      <Typography>
        Page {page} of {totalPages} — Showing {paginatedRows.length} of{" "}
        {totalRows}
      </Typography>

      {/* Page Buttons */}
      <Box display="flex" gap={1}>
        <Button
          variant="outlined"
          size="small"
          disabled={page === 1}
          onClick={() => setPage(1)}
        >
          First
        </Button>
        <Button
          variant="outlined"
          size="small"
          disabled={page === 1}
          onClick={() => setPage((p) => p - 1)}
        >
          Prev
        </Button>
        <Button
          variant="outlined"
          size="small"
          disabled={page === totalPages}
          onClick={() => setPage((p) => p + 1)}
        >
          Next
        </Button>
        <Button
          variant="outlined"
          size="small"
          disabled={page === totalPages}
          onClick={() => setPage(totalPages)}
        >
          Last
        </Button>
      </Box>
    </Box>
  </>
)}
{!selectedFile && (
  <Typography>Select a task or create one.</Typography>
)}
</Box>

      

      {/* ADD COLUMN DIALOG */}
      <Dialog open={openAddColumn} onClose={() => setOpenAddColumn(false)}>
        <DialogTitle>Add New Column</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            margin="normal"
            label="Column Header"
            value={newColumnName}
            onChange={(e) => setNewColumnName(e.target.value)}
          />
          <FormControl fullWidth margin="normal">
            <InputLabel>Column Type</InputLabel>
            <Select
              value={newColumnType}
              label="Column Type"
              onChange={(e) => setNewColumnType(e.target.value)}
            >
              <MenuItem value="Text Field">Text Field</MenuItem>
              <MenuItem value="Dropdown">Dropdown</MenuItem>
              <MenuItem value="Checkbox">Checkbox</MenuItem>
            </Select>
          </FormControl>

          {newColumnType === "Dropdown" && (
            <TextField
              fullWidth
              label="Dropdown Options (comma separated)"
              value={dropdownOptions}
              onChange={(e) => setDropdownOptions(e.target.value)}
            />
          )}
        </DialogContent>

        <DialogActions>
          <Button onClick={() => setOpenAddColumn(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleAddColumn}>
            Add
          </Button>
        </DialogActions>
      </Dialog>

      {/* CREATE TABLE DIALOG */}
      <Dialog open={openCreateTable} onClose={() => setOpenCreateTable(false)}>
        <DialogTitle>Create New Table</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Table Name"
            value={newTableName}
            onChange={(e) => setNewTableName(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenCreateTable(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleCreateTable}>
            Create
          </Button>
        </DialogActions>
      </Dialog>

          {/* EDIT DIALOG */}

          <Dialog open={openPermission} onClose={() => setOpenPermission(false)}>
      <DialogTitle>Edit Details</DialogTitle>
      <DialogContent>
        <Typography>Do you want to edit this row?</Typography>
      </DialogContent>
      <DialogActions>
        <Button onClick={() => setOpenPermission(false)}>No</Button>
        <Button
          variant="contained"
          onClick={() => {
            const row = fileData[selectedRowIndex + 1];
            setEditRowData([...row]);
            setOpenPermission(false);
            setOpenEdit(true);
          }}
        >
          Yes
        </Button>
      </DialogActions>
    </Dialog>

    <Dialog open={openEdit} onClose={() => setOpenEdit(false)} maxWidth="md" fullWidth>
  <DialogTitle>Edit Details</DialogTitle>

  <DialogContent>
    {fileData[0]?.map((header, i) => (
      <TextField
        key={i}
        margin="dense"
        label={header}
        fullWidth
        value={editRowData[i]}
        onChange={(e) => {
          const newData = [...editRowData];
          newData[i] = e.target.value;
          setEditRowData(newData);
        }}
      />
    ))}
  </DialogContent>

  <DialogActions>
    <Button onClick={() => setOpenEdit(false)}>Cancel</Button>
    <Button
      variant="contained"
      onClick={() => {
        setOpenEdit(false);
        setOpenChecker(true);
      }}
    >
      Save
    </Button>
  </DialogActions>
</Dialog>

<Dialog open={openChecker} onClose={() => setOpenChecker(false)}>
  <DialogTitle>Checker Verification</DialogTitle>
  <DialogContent>
    <TextField
      autoFocus
      fullWidth
      label="Enter Checker Name"
      value={checkerName}
      onChange={(e) => setCheckerName(e.target.value)}
    />
  </DialogContent>

  <DialogActions>
    <Button onClick={() => setOpenChecker(false)}>Cancel</Button>
    <Button
      variant="contained"
      onClick={() => handleFinalSave()}
    >
      Confirm Save
    </Button>
  </DialogActions>
</Dialog>
    </Box>
  );
};

export default AdminTask;