import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { signOut } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import UserManagement from './components/UserManagement';
import ManageServices from './components/ManageServices';
import MedicineManagement from './components/MedicineManagement';
import './SuperAdminDashboardEnhanced.css';

const SuperAdminDashboard = () => {
  const [superadminData, setSuperadminData] = useState(null);
  const [activeSection, setActiveSection] = useState('dashboard');
  const [loading, setLoading] = useState(true);
  const [darkMode, setDarkMode] = useState(false);
  const navigate = useNavigate();

  // Initialize dark mode from localStorage
  useEffect(() => {
    const savedDarkMode = localStorage.getItem('dashboardDarkMode');
    if (savedDarkMode !== null) {
      const isDark = JSON.parse(savedDarkMode);
      setDarkMode(isDark);
      applyDarkMode(isDark);
    } else {
      // Check system preference
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setDarkMode(prefersDark);
      applyDarkMode(prefersDark);
    }
  }, []);

  const applyDarkMode = (isDark) => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);
    applyDarkMode(newDarkMode);
    localStorage.setItem('dashboardDarkMode', JSON.stringify(newDarkMode));
  };

  useEffect(() => {
    // Check if user is authenticated as superadmin or admin
    const isSuperAdmin = localStorage.getItem('isSuperAdmin');
    const superadminEmail = localStorage.getItem('superadminEmail');
    const superadminUid = localStorage.getItem('superadminUid');

    if (!isSuperAdmin || !superadminEmail || !superadminUid) {
      setLoading(false);
      navigate('/superadmin');
      return;
    }

    // Verify role from users collection
    const verifyRole = async () => {
      try {
        const userDocRef = doc(db, 'users', superadminUid);
        const userDoc = await getDoc(userDocRef);
        
        if (userDoc.exists()) {
          const userData = userDoc.data();
          // Check if user has superadmin or admin role
          if (userData.role === 'superadmin' || userData.role === 'admin') {
            setSuperadminData({
              email: superadminEmail,
              uid: superadminUid,
              role: userData.role,
              name: userData.name || 'Administrator'
            });
          } else {
            // User doesn't have superadmin or admin role
            console.error('User does not have superadmin or admin role');
            localStorage.removeItem('superadminEmail');
            localStorage.removeItem('superadminUid');
            localStorage.removeItem('isSuperAdmin');
            navigate('/superadmin');
          }
        } else {
          // User document doesn't exist in users collection
          console.error('User document not found in users collection');
          localStorage.removeItem('superadminEmail');
          localStorage.removeItem('superadminUid');
          localStorage.removeItem('isSuperAdmin');
          navigate('/superadmin');
        }
      } catch (error) {
        console.error('Error verifying role:', error);
        navigate('/superadmin');
      } finally {
        setLoading(false);
      }
    };

    verifyRole();
  }, [navigate]);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      localStorage.removeItem('superadminEmail');
      localStorage.removeItem('superadminUid');
      localStorage.removeItem('isSuperAdmin');
      navigate('/superadmin');
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <p>Verifying credentials...</p>
      </div>
    );
  }

  if (!superadminData) {
    return (
      <div className="loading">
        <p>Access Denied</p>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      {/* Header */}
      <header className="dashboard-header">
        <div className="header-left">
          <svg className="header-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <rect x="3" y="3" width="18" height="18" rx="2" />
            <path d="M9 11h6M9 15h6M9 7h6" />
          </svg>
          <h1>Super Admin Dashboard</h1>
        </div>
        <div className="header-right">
          <div className="user-profile-header">
            <div className="user-avatar">SA</div>
            <div className="user-info-header">
              <span className="user-role">Super Administrator</span>
              <span className="user-email-header">{superadminData.email}</span>
            </div>
          </div>
          <button className="logout-button" onClick={handleLogout}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
              <polyline points="16 17 21 12 16 7" />
              <line x1="21" y1="12" x2="9" y2="12" />
            </svg>
            Logout
          </button>
        </div>
      </header>

      <div className="dashboard-layout">
        {/* Sidebar */}
        <aside className="dashboard-sidebar">
          <nav className="sidebar-menu">
            <button
              onClick={() => setActiveSection('dashboard')}
              className={`menu-item ${activeSection === 'dashboard' ? 'active' : ''}`}
              title="Dashboard"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <rect x="3" y="3" width="7" height="7" />
                <rect x="14" y="3" width="7" height="7" />
                <rect x="14" y="14" width="7" height="7" />
                <rect x="3" y="14" width="7" height="7" />
              </svg>
              Dashboard
            </button>
            <button
              onClick={() => setActiveSection('users')}
              className={`menu-item ${activeSection === 'users' ? 'active' : ''}`}
              title="User Management"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: '#0ea5e9' }}>
                <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
                <circle cx="9" cy="7" r="4" />
                <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
                <path d="M16 3.13a4 4 0 0 1 0 7.75" />
              </svg>
              User Management
            </button>
            <button
              onClick={() => setActiveSection('medicines')}
              className={`menu-item ${activeSection === 'medicines' ? 'active' : ''}`}
              title="Medicine Management"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: '#f43f5e' }}>
                <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z" />
                <path d="M15 12H9" />
                <path d="M12 15V9" />
              </svg>
              Medicine Management
            </button>
            <button
              onClick={() => setActiveSection('services')}
              className={`menu-item ${activeSection === 'services' ? 'active' : ''}`}
              title="Manage Services"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: '#14b8a6' }}>
                <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 1 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z" />
              </svg>
              Manage Services
            </button>
            <button
              onClick={() => setActiveSection('reports')}
              className={`menu-item ${activeSection === 'reports' ? 'active' : ''}`}
              title="Reports"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: '#a78bfa' }}>
                <line x1="12" y1="2" x2="12" y2="22" />
                <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" />
              </svg>
              Reports
            </button>
            <button
              onClick={() => setActiveSection('settings')}
              className={`menu-item ${activeSection === 'settings' ? 'active' : ''}`}
              title="Settings"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: '#9ca3af' }}>
                <circle cx="12" cy="12" r="3" />
                <path d="M12 1v6m0 6v6M4.22 4.22l4.24 4.24m0 5.08l-4.24 4.24M23 12h-6m-6 0H5M19.78 4.22l-4.24 4.24m0 5.08l4.24 4.24M19.78 19.78l-4.24-4.24m0-5.08l4.24-4.24" />
              </svg>
              Settings
            </button>
            <button
              onClick={() => setActiveSection('security')}
              className={`menu-item ${activeSection === 'security' ? 'active' : ''}`}
              title="Security"
            >
              <svg className="menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ color: '#10b981' }}>
                <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
              </svg>
              Security
            </button>
          </nav>

          {/* System Status */}
          <div className="system-status">
            <p className="status-label">System Health</p>
            <div className="status-indicator">
              <span className="status-dot"></span>
              <span className="status-text">All services stable</span>
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="dashboard-main">
          {activeSection === 'dashboard' && (
            <>
              {/* Welcome Section */}
              <div className="welcome-card">
                <div className="welcome-content">
                  <h2>Welcome back, <span className="highlight-text">Super Admin</span></h2>
                  <p>Manage system protocols, user access levels, and monitor global activity with the new AKSYON AGAD centralized control center.</p>
                </div>
                <div className="welcome-icon">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2z" opacity="0.1" />
                  </svg>
                </div>
              </div>

              {/* Feature Cards Grid */}
              <div className="features-grid">
                <div className="feature-card" onClick={() => setActiveSection('users')}>
                  <div className="card-icon-container sky">
                    <svg className="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
                      <circle cx="9" cy="7" r="4" />
                      <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
                      <path d="M16 3.13a4 4 0 0 1 0 7.75" />
                    </svg>
                  </div>
                  <h3>User Access</h3>
                  <p>Manage global user roles and credential permissions.</p>
                  <button className="card-button sky">View Console</button>
                </div>

                <div className="feature-card" onClick={() => setActiveSection('services')}>
                  <div className="card-icon-container teal">
                    <svg className="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 1 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z" />
                    </svg>
                  </div>
                  <h3>Manage Services</h3>
                  <p>Configure system integrations and feature availability.</p>
                  <button className="card-button teal">View Services</button>
                </div>

                <div className="feature-card" onClick={() => setActiveSection('reports')}>
                  <div className="card-icon-container indigo">
                    <svg className="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <line x1="12" y1="2" x2="12" y2="22" />
                      <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" />
                    </svg>
                  </div>
                  <h3>System Reports</h3>
                  <p>Review performance metrics and usage statistics.</p>
                  <button className="card-button indigo">View Reports</button>
                </div>

                <div className="feature-card" onClick={() => setActiveSection('settings')}>
                  <div className="card-icon-container slate">
                    <svg className="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <circle cx="12" cy="12" r="3" />
                      <path d="M12 1v6m0 6v6M4.22 4.22l4.24 4.24m0 5.08l-4.24 4.24M23 12h-6m-6 0H5M19.78 4.22l-4.24 4.24m0 5.08l4.24 4.24M19.78 19.78l-4.24-4.24m0-5.08l4.24-4.24" />
                    </svg>
                  </div>
                  <h3>Configuration</h3>
                  <p>Edit global environment and system-wide variables.</p>
                  <button className="card-button slate">View Settings</button>
                </div>

                <div className="feature-card" onClick={() => setActiveSection('security')}>
                  <div className="card-icon-container emerald">
                    <svg className="card-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
                    </svg>
                  </div>
                  <h3>Security Hub</h3>
                  <p>Monitor audit logs and manage firewall policies.</p>
                  <button className="card-button emerald">View Logs</button>
                </div>
              </div>

              {/* Bottom Stats */}
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-header">
                    <h4>System Activity Overview</h4>
                    <select className="stat-select">
                      <option>Last 7 Days</option>
                      <option>Last 30 Days</option>
                    </select>
                  </div>
                  <div className="stat-placeholder">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <polyline points="12 3 20 7.5 20 16.5 12 21 4 16.5 4 7.5 12 3" />
                      <polyline points="12 12 20 7.5" />
                      <polyline points="12 12 12 21" />
                      <polyline points="12 12 4 7.5" />
                    </svg>
                    <span>Activity visualization loading...</span>
                  </div>
                </div>

                <div className="stat-card">
                  <h4>Recent Audit Logs</h4>
                  <div className="audit-logs">
                    <div className="log-item">
                      <span className="log-dot blue"></span>
                      <div className="log-content">
                        <p className="log-title">Session Initialized</p>
                        <p className="log-desc">Admin-2 login from HK-Region-Node</p>
                      </div>
                      <span className="log-time">2m ago</span>
                    </div>
                    <div className="log-item">
                      <span className="log-dot teal"></span>
                      <div className="log-content">
                        <p className="log-title">Database Synchronized</p>
                        <p className="log-desc">Pharmacy inventory module updated</p>
                      </div>
                      <span className="log-time">1h ago</span>
                    </div>
                    <div className="log-item">
                      <span className="log-dot rose"></span>
                      <div className="log-content">
                        <p className="log-title">Access Denied</p>
                        <p className="log-desc">Multiple login failures from 192.14.2.1</p>
                      </div>
                      <span className="log-time">3h ago</span>
                    </div>
                  </div>
                </div>
              </div>
            </>
          )}

          {activeSection === 'users' && <UserManagement onBack={() => setActiveSection('dashboard')} />}
          {activeSection === 'medicines' && <MedicineManagement onBack={() => setActiveSection('dashboard')} />}
          {activeSection === 'services' && <ManageServices onBack={() => setActiveSection('dashboard')} />}
          {activeSection === 'reports' && <div className="placeholder-section"><h2>📈 Reports</h2><p>Reports feature coming soon...</p></div>}
          {activeSection === 'settings' && <div className="placeholder-section"><h2>⚙️ Settings</h2><p>Settings feature coming soon...</p></div>}
          {activeSection === 'security' && <div className="placeholder-section"><h2>🔐 Security</h2><p>Security settings coming soon...</p></div>}
        </main>
      </div>

      {/* Dark Mode Toggle */}
      <button className="dark-mode-toggle" onClick={toggleDarkMode} title="Toggle dark mode">
        {darkMode ? (
          <svg viewBox="0 0 24 24" fill="currentColor">
            <path d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
          </svg>
        ) : (
          <svg viewBox="0 0 24 24" fill="currentColor">
            <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
          </svg>
        )}
      </button>
    </div>
  );
};

export default SuperAdminDashboard;
