import React, { useState, useEffect } from 'react';
import AksyonAgadLogin from './AksyonAgadLogin';
import LoadingScreen from '../components/LoadingScreen';
import './LandingPage.css';

const LandingPage = () => {
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simulate content loading - adjust timing as needed
    const loadTimer = setTimeout(() => {
      setIsLoading(false);
    }, 500);

    return () => clearTimeout(loadTimer);
  }, []);

  if (isLoading) {
    return <LoadingScreen message="Loading landing page..." />;
  }

  return isLoading ? <LoadingScreen message="Loading landing page..." /> : <AksyonAgadLogin />;
};

export default LandingPage;
