import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../firebase';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { doc, getDoc, getDocs, collection, query, where } from 'firebase/firestore';
import LoadingScreen from '../components/LoadingScreen';
import './AksyonAgadLogin.css';

const AksyonAgadLogin = () => {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isPageLoading, setIsPageLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsPageLoading(false);
    }, 300);

    // Load remembered username if it exists
    const remembered = localStorage.getItem('rememberMe');
    if (remembered) {
      setUsername(remembered);
      setRememberMe(true);
    }

    return () => clearTimeout(timer);
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (!username.trim()) {
        setError('Please enter your username or email');
        setIsLoading(false);
        return;
      }

      if (!password.trim()) {
        setError('Please enter your password');
        setIsLoading(false);
        return;
      }

      if (password.length < 6) {
        setError('Password must be at least 6 characters long');
        setIsLoading(false);
        return;
      }

      let userEmail = null;
      let userId = null;
      const inputValue = username.trim();

      if (inputValue.includes('@')) {
        userEmail = inputValue;
      } else {
        try {
          const usersCollection = collection(db, 'users');
          const usersQuery = query(usersCollection, where('username', '==', inputValue));
          const querySnapshot = await getDocs(usersQuery);

          if (querySnapshot.empty) {
            setError('Username not found. Please check and try again.');
            setIsLoading(false);
            return;
          }

          const userDoc = querySnapshot.docs[0];
          userId = userDoc.id;
          const userData = userDoc.data();
          userEmail = userData.email;

          if (!userEmail) {
            setError('User email not found in system. Please contact administrator.');
            setIsLoading(false);
            return;
          }
        } catch (searchErr) {
          console.error('Error searching for username:', searchErr);
          setError('Error validating username. Please try again.');
          setIsLoading(false);
          return;
        }
      }

      const userCredential = await signInWithEmailAndPassword(auth, userEmail, password);
      const user = userCredential.user;

      if (!userId) {
        userId = user.uid;
      }

      const userDocRef = doc(db, 'users', userId);
      const userDoc = await getDoc(userDocRef);

      if (userDoc.exists()) {
        const userData = userDoc.data();
        const allowedRoles = ['user', 'admin', 'encoder', 'superadmin'];

        if (!allowedRoles.includes(userData.role)) {
          setError('Your account does not have access to this system');
          setIsLoading(false);
          return;
        }

        // Handle Remember Me
        if (rememberMe) {
          localStorage.setItem('rememberMe', username);
        } else {
          localStorage.removeItem('rememberMe');
        }

        // Check email verification first
        if (!user.emailVerified) {
          setError('Please verify your email before logging in');
          setIsLoading(false);
          setTimeout(() => {
            navigate('/verify-email', { replace: true });
          }, 500);
          return;
        }

        // Check if user is superadmin or admin - route to superadmin dashboard
        if (userData.role === 'superadmin' || userData.role === 'admin') {
          localStorage.setItem('superadminEmail', userEmail);
          localStorage.setItem('superadminUid', userId);
          localStorage.setItem('isSuperAdmin', 'true');

          setUsername('');
          setPassword('');
          setIsLoading(false);

          setTimeout(() => {
            navigate('/superadmin/dashboard');
          }, 500);
        } else {
          // Regular user or encoder - route to services dashboard
          sessionStorage.setItem('servicesUsername', userData.name || userData.username || inputValue);
          sessionStorage.setItem('servicesUid', userId);
          sessionStorage.setItem('servicesEmail', userEmail);
          localStorage.setItem('servicesUsername', userData.name || userData.username || inputValue);
          localStorage.setItem('servicesUid', userId);
          localStorage.setItem('role', userData.role);
          localStorage.setItem('serviceAccess', JSON.stringify(userData.serviceAccess || []));

          setUsername('');
          setPassword('');
          setIsLoading(false);

          setTimeout(() => {
            navigate('/services/dashboard');
          }, 500);
        }
      } else {
        setError('User profile not found. Please contact administrator.');
        setIsLoading(false);
      }
    } catch (err) {
      console.error('Login error:', err);

      if (err.code === 'auth/user-not-found') {
        setError('Email not found. Please check your credentials.');
      } else if (err.code === 'auth/wrong-password') {
        setError('Invalid password. Please try again.');
      } else if (err.code === 'auth/invalid-email') {
        setError('Invalid email format. Please use a valid email or username.');
      } else if (err.code === 'auth/user-disabled') {
        setError('This account has been disabled. Please contact administrator.');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Too many login attempts. Please try again later.');
      } else {
        setError(`Login failed: ${err.message}`);
      }
      setIsLoading(false);
    }
  };

  if (isPageLoading) {
    return <LoadingScreen message="Loading Aksyon Agad Login..." />;
  }

  return (
    <div className="login-page">
      <header className="login-header">
        <div className="header-logo">
          <span className="brand-text">
            <span className="brand-green">AKSYON</span>
            <span className="brand-red">AGAD</span>
          </span>
        </div>
      </header>

      <main className="login-main">
        <div className="login-card">
          <div className="login-card-header">
            <div className="card-logo">
              <span className="brand-text large">
                <span className="brand-green">AKSYON</span>
                <span className="brand-red">AGAD</span>
              </span>
            </div>
            <p className="login-subtitle">Sign in to access Aksyon Agad services</p>
          </div>

          <form onSubmit={handleSubmit} className="login-form">
            {error && <div className="error-message">{error}</div>}

            <div className="form-group">
              <label htmlFor="username">Email or Username</label>
              <div className="input-wrapper">
                <span className="input-icon" aria-hidden>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <circle cx="12" cy="7" r="4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </span>
                <input
                  type="text"
                  id="username"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="Enter your email or username"
                  required
                  disabled={isLoading}
                />
              </div>
            </div>

            <div className="form-group">
              <label htmlFor="password">Password</label>
              <div className="input-wrapper password-wrapper">
                <span className="input-icon" aria-hidden>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <rect x="3" y="11" width="18" height="11" rx="2" ry="2" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    <path d="M7 11V7a5 5 0 0 1 10 0v4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </span>
                <input
                  type={showPassword ? 'text' : 'password'}
                  id="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Enter your password"
                  required
                  disabled={isLoading}
                />
                <button
                  type="button"
                  className="password-toggle-btn"
                  onClick={() => setShowPassword(!showPassword)}
                  disabled={isLoading}
                  title={showPassword ? 'Hide password' : 'Show password'}
                  aria-pressed={showPassword}
                >
                  {showPassword ? (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M1 1l22 22M6.5 6.5a9 9 0 0 1 12.23.154M9.88 9.88a3 3 0 1 1 4.24 4.24" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <path d="M9.88 5.88A9 9 0 0 1 21 12a9 9 0 0 1-15 7.07" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  ) : (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      <circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  )}
                </button>
              </div>
            </div>

            <div className="form-options">
              <label className="remember-me-label">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                  className="remember-checkbox"
                />
                <span className="remember-text">Remember me</span>
              </label>
              <button
                type="button"
                onClick={() => navigate('/forgot-password')}
                className="forgot-link-inline"
                style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}
              >
                Forgot your password?
              </button>
            </div>

            <button type="submit" className="login-submit" disabled={isLoading}>
              <span className="button-icon" aria-hidden>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M5 12h14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M12 5l7 7-7 7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              </span>
              {isLoading ? 'Signing in...' : 'Sign In'}
            </button>

            <div className="secure-ssl-footer">
              <span className="ssl-icon" aria-hidden>
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  <path d="M9 12l2 2 4-4" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                </svg>
              </span>
              <span className="ssl-text">Secure SSL Encrypted Connection</span>
            </div>
          </form>
        </div>
      </main>

      <footer className="login-page-footer">
        © 2026 Aksyon Agad. All rights reserved.
      </footer>
    </div>
  );
};

export default AksyonAgadLogin;
