import React from "react";
import { Box, Typography, Grid } from "@mui/material";

const VotersStatsCard = ({ totalVoters, statusCounts }) => {
  return (
    <Grid container spacing={2}>
      <Grid item xs={12} md={2.4} sx={{ flex: 1 }}>
        <Box sx={{ textAlign: "center", p: 2, bgcolor: "#e3f2fd", borderRadius: 1.5 }}>
          <Typography variant="caption" sx={{ color: "#1976d2", fontWeight: 600, display: "block", mb: 0.5 }}>
            Total Registered
          </Typography>
          <Typography variant="h5" sx={{ color: "#1f8ef1", fontWeight: 700 }}>
            {totalVoters.toLocaleString()}
          </Typography>
        </Box>
      </Grid>
      <Grid item xs={12} md={2.4} sx={{ flex: 1 }}>
        <Box sx={{ textAlign: "center", p: 2, bgcolor: "#f3e5f5", borderRadius: 1.5 }}>
          <Typography variant="caption" sx={{ color: "#7b1fa2", fontWeight: 600, display: "block", mb: 0.5 }}>
            ADMIN
          </Typography>
          <Typography variant="h5" sx={{ color: "#7b1fa2", fontWeight: 700 }}>
            {statusCounts.ADMIN.toLocaleString()}
          </Typography>
        </Box>
      </Grid>
      <Grid item xs={12} md={2.4} sx={{ flex: 1 }}>
        <Box sx={{ textAlign: "center", p: 2, bgcolor: "#fce4ec", borderRadius: 1.5 }}>
          <Typography variant="caption" sx={{ color: "#c2185b", fontWeight: 600, display: "block", mb: 0.5 }}>
            OPPOSITION
          </Typography>
          <Typography variant="h5" sx={{ color: "#c2185b", fontWeight: 700 }}>
            {statusCounts.OPPOSITION.toLocaleString()}
          </Typography>
        </Box>
      </Grid>
      <Grid item xs={12} md={2.4} sx={{ flex: 1 }}>
        <Box sx={{ textAlign: "center", p: 2, bgcolor: "#fff3e0", borderRadius: 1.5 }}>
          <Typography variant="caption" sx={{ color: "#e65100", fontWeight: 600, display: "block", mb: 0.5 }}>
            UNTAGGED
          </Typography>
          <Typography variant="h5" sx={{ color: "#e65100", fontWeight: 700 }}>
            {statusCounts.UNTAGGED.toLocaleString()}
          </Typography>
        </Box>
      </Grid>
      <Grid item xs={12} md={2.4} sx={{ flex: 1 }}>
        <Box sx={{ textAlign: "center", p: 2, bgcolor: "#f1f8e9", borderRadius: 1.5 }}>
          <Typography variant="caption" sx={{ color: "#558b2f", fontWeight: 600, display: "block", mb: 0.5 }}>
            NO STATUS
          </Typography>
          <Typography variant="h5" sx={{ color: "#558b2f", fontWeight: 700 }}>
            {statusCounts["NO STATUS"].toLocaleString()}
          </Typography>
        </Box>
      </Grid>
    </Grid>
  );
};

export default VotersStatsCard;
