import React from 'react';
import { useNavigate } from 'react-router-dom';
import { auth } from '../firebase';
import './VerificationSent.css';

const VerificationSent = () => {
  const navigate = useNavigate();

  const handleOpenInbox = () => {
    window.open('https://mail.google.com', '_blank');
  };

  const handleBackToLogin = async () => {
    try {
      await auth.signOut();
    } catch (error) {
      console.error('Error signing out:', error);
    } finally {
      navigate('/superadmin');
    }
  };

  return (
    <div className="sent-page">
      <div className="sent-ambient sent-ambient-blue" aria-hidden="true" />
      <div className="sent-ambient sent-ambient-green" aria-hidden="true" />

      <div className="sent-card" role="dialog" aria-labelledby="sent-title" aria-describedby="sent-description">
        <div className="sent-hero">
          <div className="sent-icon-wrapper">
            <div className="sent-icon-circle">
              <span className="material-symbols-outlined">mark_email_read</span>
            </div>
            <div className="sent-badge">
              <span className="material-symbols-outlined filled">check_circle</span>
            </div>
          </div>
        </div>

        <div className="sent-body">
          <h1 id="sent-title" className="sent-title">Verification Email Sent!</h1>
          <p id="sent-description" className="sent-text">
            We have successfully resent the verification link to your registered email address. Please check your inbox and spam folder.
          </p>

          <div className="sent-actions">
            <button className="sent-primary" onClick={handleOpenInbox}>
              <span className="material-symbols-outlined">mail</span>
              <span>Check Your Inbox</span>
            </button>
            <button className="sent-secondary" onClick={handleBackToLogin}>
              <span className="material-symbols-outlined">arrow_back</span>
              <span>Back to Login</span>
            </button>
          </div>

          <div className="sent-footer">
            <span className="sent-footer-text">AKSYON AGAD PORTAL</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VerificationSent;
