import React from "react";
import {
  Card,
  CardContent,
  TextField,
  InputAdornment,
} from "@mui/material";
import { Search } from "@mui/icons-material";

const VotersSearchBar = ({ search, setSearch, setPage, setPageCursors }) => {
  return (
    <Card sx={{ mb: 3, bgcolor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)" }}>
      <CardContent sx={{ p: 2.5 }}>
        <TextField
          fullWidth
          variant="outlined"
          size="small"
          placeholder="Search voter name, address, barangay..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setPage(0);
            setPageCursors([]);
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search sx={{ color: "#1f8ef1", mr: 1 }} />
              </InputAdornment>
            ),
          }}
          sx={{
            "& .MuiOutlinedInput-root": {
              borderRadius: 1.5,
              "&:hover fieldset": {
                borderColor: "#1f8ef1",
              },
            },
          }}
        />
      </CardContent>
    </Card>
  );
};

export default VotersSearchBar;
