import React from "react";
import {
  Box,
  Typography,
  Card,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
} from "@mui/material";
import { PersonSearch } from "@mui/icons-material";

const VotersTable = ({
  headers,
  headerLabels,
  paginatedVoters,
  setSelectedVoter,
  page,
  rowsPerPage,
  handleChangePage,
  handleChangeRowsPerPage,
}) => {
  return (
    <Card sx={{ bgcolor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)", mb: 3, position: "relative" }}>
      <TableContainer sx={{ maxHeight: 600, position: "relative" }}>
        <Table stickyHeader>
          <TableHead>
            <TableRow sx={{ bgcolor: "#1a237e" }}>
              {headers.map((header, i) => (
                <TableCell
                  key={i}
                  sx={{
                    color: "#fff",
                    fontWeight: 700,
                    backgroundColor: "#1a237e",
                    position: "sticky",
                    top: 0,
                    zIndex: 10,
                    fontSize: 13,
                    py: 1.5,
                    px: 2,
                    whiteSpace: "nowrap",
                    minWidth: 130,
                    maxWidth: 200,
                    transition: "background-color 0.2s",
                  }}
                >
                  {headerLabels[header]}
                </TableCell>
              ))}
            </TableRow>
          </TableHead>

          <TableBody>
            {paginatedVoters.length === 0 ? (
              <TableRow>
                <TableCell align="center" colSpan={headers.length}>
                  <Box sx={{ py: 4, textAlign: "center" }}>
                    <PersonSearch sx={{ fontSize: 48, color: "#ccc", mb: 1 }} />
                    <Typography variant="body2" sx={{ color: "#999" }}>
                      No voter records found. Try adjusting your search filters.
                    </Typography>
                  </Box>
                </TableCell>
              </TableRow>
            ) : (
              paginatedVoters.map((voter, index) => (
                <TableRow
                  key={index}
                  hover
                  onClick={() => setSelectedVoter(voter)}
                  sx={{
                    cursor: "pointer",
                    "&:hover": {
                      bgcolor: "#f0f4ff",
                    },
                    animation: `fadeIn 0.4s ease-in-out ${index * 0.05}s both`,
                    "@keyframes fadeIn": {
                      from: {
                        opacity: 0,
                        transform: "translateY(-5px)",
                      },
                      to: {
                        opacity: 1,
                        transform: "translateY(0)",
                      },
                    },
                  }}
                >
                  {headers.map((header, i) => (
                    <TableCell
                      key={i}
                      sx={{
                        fontSize: 13,
                        py: 1.25,
                        px: 2,
                        whiteSpace: "nowrap",
                        maxWidth: 200,
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        color: "#333",
                      }}
                    >
                      {voter[header] || "—"}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>
      <TablePagination
        component="div"
        count={-1}
        page={page}
        onPageChange={handleChangePage}
        rowsPerPage={rowsPerPage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        rowsPerPageOptions={[5, 10, 20, 50, 100]}
        labelDisplayedRows={() => `Page ${page + 1}`}
        sx={{
          bgcolor: "#fafbfc",
          borderTop: "1px solid #e0e0e0",
          ".MuiTablePagination-toolbar": {
            px: 2,
            py: 1,
          },
        }}
      />
    </Card>
  );
};

export default VotersTable;
