import React, { useState, useEffect } from 'react';
import { db } from '../../firebase';
import { collection, getDocs, addDoc, deleteDoc, doc, updateDoc } from 'firebase/firestore';
import './MedicineManagement.css';

const MedicineManagement = ({ onBack }) => {
  const [medicines, setMedicines] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [addFormData, setAddFormData] = useState({
    medicineName: '',
    dosage: '',
    description: ''
  });
  const [editingMedicine, setEditingMedicine] = useState(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editFormData, setEditFormData] = useState({});
  const [addLoading, setAddLoading] = useState(false);

  // Fetch medicines from Firestore
  useEffect(() => {
    fetchMedicines();
  }, []);

  const fetchMedicines = async () => {
    try {
      setLoading(true);
      const medicinesCollection = collection(db, 'medicines');
      const medicinesSnapshot = await getDocs(medicinesCollection);
      const medicinesList = medicinesSnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setMedicines(medicinesList);
      setError('');
    } catch (err) {
      console.error('Error fetching medicines:', err);
      setError('Failed to load medicines');
    } finally {
      setLoading(false);
    }
  };

  const handleAddMedicine = async () => {
    try {
      if (!addFormData.medicineName.trim()) {
        setError('Medicine name is required');
        setTimeout(() => setError(''), 3000);
        return;
      }

      if (!addFormData.dosage.trim()) {
        setError('Dosage is required');
        setTimeout(() => setError(''), 3000);
        return;
      }

      setAddLoading(true);

      const medicinesCollection = collection(db, 'medicines');
      const newMedicine = await addDoc(medicinesCollection, {
        medicineName: addFormData.medicineName.trim().toLowerCase(),
        dosage: addFormData.dosage.trim(),
        description: addFormData.description.trim(),
        createdAt: new Date(),
        updatedAt: new Date()
      });

      setMedicines([
        ...medicines,
        {
          id: newMedicine.id,
          medicineName: addFormData.medicineName.trim().toLowerCase(),
          dosage: addFormData.dosage,
          description: addFormData.description,
          createdAt: new Date(),
          updatedAt: new Date()
        }
      ]);

      setSuccess('✓ Medicine added successfully!');
      setShowAddModal(false);
      setAddFormData({ medicineName: '', dosage: '', description: '' });
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Error adding medicine:', err);
      setError('Failed to add medicine');
      setTimeout(() => setError(''), 3000);
    } finally {
      setAddLoading(false);
    }
  };

  const handleDeleteMedicine = async (medicineId) => {
    if (!window.confirm('Are you sure you want to delete this medicine?')) {
      return;
    }

    try {
      const medicineDocRef = doc(db, 'medicines', medicineId);
      await deleteDoc(medicineDocRef);

      setMedicines(medicines.filter(m => m.id !== medicineId));
      setSuccess('✓ Medicine deleted successfully!');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Error deleting medicine:', err);
      setError('Failed to delete medicine');
      setTimeout(() => setError(''), 3000);
    }
  };

  const handleEditMedicine = (medicine) => {
    setEditingMedicine(medicine);
    setEditFormData({
      medicineName: medicine.medicineName,
      dosage: medicine.dosage,
      description: medicine.description
    });
    setShowEditModal(true);
  };

  const handleUpdateMedicine = async () => {
    try {
      if (!editFormData.medicineName.trim()) {
        setError('Medicine name is required');
        setTimeout(() => setError(''), 3000);
        return;
      }

      if (!editFormData.dosage.trim()) {
        setError('Dosage is required');
        setTimeout(() => setError(''), 3000);
        return;
      }

      const medicineDocRef = doc(db, 'medicines', editingMedicine.id);
      await updateDoc(medicineDocRef, {
        medicineName: editFormData.medicineName.trim().toLowerCase(),
        dosage: editFormData.dosage.trim(),
        description: editFormData.description.trim(),
        updatedAt: new Date()
      });

      setMedicines(medicines.map(m =>
        m.id === editingMedicine.id
          ? {
              ...m,
              medicineName: editFormData.medicineName.trim().toLowerCase(),
              dosage: editFormData.dosage,
              description: editFormData.description,
              updatedAt: new Date()
            }
          : m
      ));

      setSuccess('✓ Medicine updated successfully!');
      setShowEditModal(false);
      setEditingMedicine(null);
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Error updating medicine:', err);
      setError('Failed to update medicine');
      setTimeout(() => setError(''), 3000);
    }
  };

  const filteredMedicines = medicines.filter(medicine =>
    medicine.medicineName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    medicine.dosage.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="medicine-management">
        <p>Loading medicines...</p>
      </div>
    );
  }

  return (
    <div className="medicine-management">
      <div className="medicine-header">
        <div className="header-content">
          <h2>💊 Medicine Management</h2>
          <p>Register and manage medicines in the system</p>
        </div>
        <button className="btn-back" onClick={onBack}>
          ← Back to Dashboard
        </button>
      </div>

      {error && <div className="error-message">{error}</div>}
      {success && <div className="success-message">{success}</div>}

      <div className="medicine-controls">
        <div className="search-box">
          <input
            type="text"
            placeholder="🔍 Search medicines..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
          <span className="search-count">Found {filteredMedicines.length}</span>
        </div>
        <button className="btn-add-medicine" onClick={() => setShowAddModal(true)}>
          ➕ Add Medicine
        </button>
      </div>

      <div className="medicines-table-container">
        {filteredMedicines.length === 0 ? (
          <div className="no-medicines">
            <p>📭 No medicines found</p>
            <p className="subtitle">Add your first medicine to get started</p>
          </div>
        ) : (
          <table className="medicines-table">
            <thead>
              <tr>
                <th>Medicine Name</th>
                <th>Dosage</th>
                <th>Description</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredMedicines.map((medicine) => (
                <tr key={medicine.id}>
                  <td className="medicine-name">💊 {medicine.medicineName}</td>
                  <td className="medicine-dosage">{medicine.dosage}</td>
                  <td className="medicine-description">{medicine.description || '-'}</td>
                  <td className="medicine-actions">
                    <button
                      className="btn-edit"
                      onClick={() => handleEditMedicine(medicine)}
                      title="Edit medicine"
                    >
                      ✏️
                    </button>
                    <button
                      className="btn-delete"
                      onClick={() => handleDeleteMedicine(medicine.id)}
                      title="Delete medicine"
                    >
                      🗑️
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* Add Medicine Modal */}
      {showAddModal && (
        <div className="modal-overlay" onClick={() => setShowAddModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>➕ Add New Medicine</h3>
              <button className="modal-close" onClick={() => setShowAddModal(false)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>Medicine Name *</label>
                <input
                  type="text"
                  placeholder="e.g., Paracetamol"
                  value={addFormData.medicineName}
                  onChange={(e) => setAddFormData({ ...addFormData, medicineName: e.target.value })}
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Dosage *</label>
                <input
                  type="text"
                  placeholder="e.g., 500mg"
                  value={addFormData.dosage}
                  onChange={(e) => setAddFormData({ ...addFormData, dosage: e.target.value })}
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Description</label>
                <textarea
                  placeholder="Optional: Add description or notes"
                  value={addFormData.description}
                  onChange={(e) => setAddFormData({ ...addFormData, description: e.target.value })}
                  className="form-textarea"
                  rows="3"
                />
              </div>
            </div>
            <div className="modal-footer">
              <button
                className="btn-cancel"
                onClick={() => setShowAddModal(false)}
                disabled={addLoading}
              >
                Cancel
              </button>
              <button
                className="btn-submit"
                onClick={handleAddMedicine}
                disabled={addLoading}
              >
                {addLoading ? '⏳ Adding...' : '✓ Add Medicine'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Medicine Modal */}
      {showEditModal && editingMedicine && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>✏️ Edit Medicine</h3>
              <button className="modal-close" onClick={() => setShowEditModal(false)}>✕</button>
            </div>
            <div className="modal-body">
              <div className="form-group">
                <label>Medicine Name *</label>
                <input
                  type="text"
                  placeholder="e.g., Paracetamol"
                  value={editFormData.medicineName}
                  onChange={(e) => setEditFormData({ ...editFormData, medicineName: e.target.value })}
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Dosage *</label>
                <input
                  type="text"
                  placeholder="e.g., 500mg"
                  value={editFormData.dosage}
                  onChange={(e) => setEditFormData({ ...editFormData, dosage: e.target.value })}
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Description</label>
                <textarea
                  placeholder="Optional: Add description or notes"
                  value={editFormData.description}
                  onChange={(e) => setEditFormData({ ...editFormData, description: e.target.value })}
                  className="form-textarea"
                  rows="3"
                />
              </div>
            </div>
            <div className="modal-footer">
              <button
                className="btn-cancel"
                onClick={() => setShowEditModal(false)}
                disabled={addLoading}
              >
                Cancel
              </button>
              <button
                className="btn-submit"
                onClick={handleUpdateMedicine}
                disabled={addLoading}
              >
                {addLoading ? '⏳ Updating...' : '✓ Update Medicine'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MedicineManagement;
