import React, { useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  MenuItem,
  Stack,
  LinearProgress,
  Typography,
  useMediaQuery,
  useTheme,
  Slide,
} from "@mui/material";
import UploadFileIcon from "@mui/icons-material/UploadFile";

// Slide transition for smooth opening/closing
const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const AddNewPayoutDialog = ({ open, onClose, onSubmit }) => {
  const theme = useTheme();
  const fullScreen = useMediaQuery(theme.breakpoints.down("sm"));

  const [file, setFile] = useState(null);
  const [title, setTitle] = useState("");
  const [venue, setVenue] = useState("");
  const [amount, setAmount] = useState("");
  const [beneficiaryCount, setBeneficiaryCount] = useState("");
  const [date, setDate] = useState("");
  const [category, setCategory] = useState("");
  const [sector, setSector] = useState("");
  const [importing, setImporting] = useState(false);

  // Confirm dialogs state
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [cancelConfirmOpen, setCancelConfirmOpen] = useState(false);

  // Hardcoded dropdown options
  const categories = ["AKAP", "AICS", "ECT", "TUPAD","KBPL&KBBL"];
  const sectors = [
    "SENIOR",
    "PWD",
    "SOLO PARENT",
    "YOUTH",
    "SINGLE MOTOR DRIVER",
    "TRICYCLY DRIVER",
    "VENDOR",
    "LGBTQ",
    "TEACHER",
    "LEADERS"
  ];

  const handleFileChange = (e) => setFile(e.target.files[0] || null);

  const handleConfirm = () => {
    if (!file) return alert("Please select a file first.");
    if (!category || !sector) return alert("Please select category and sector.");
    setConfirmOpen(true); // open MUI confirm dialog
  };

 const handleImport = async () => {
  if (!file) {
    alert("Please select a file to upload.");
    return;
  }

  setConfirmOpen(false);
  setImporting(true);

  try {
    const formData = new FormData();
    formData.append("file", file);
    formData.append("title", title || "");
    formData.append("venue", venue || "");
    formData.append("amount", amount || "");
    formData.append("beneficiaryCount", beneficiaryCount || "");
    formData.append("date", date || "");
    formData.append("category", category || "");
    formData.append("sector", sector || "");

    // Debug: log all FormData entries
    for (let [key, value] of formData.entries()) {
      console.log(key, value);
    }

    const res = await onSubmit(formData);

    // Optional: check server response
    if (res && res.error) {
      throw new Error(res.error || "Upload failed");
    }

    // Reset form
    setTitle("");
    setVenue("");
    setAmount("");
    setBeneficiaryCount("");
    setDate("");
    setCategory("");
    setSector("");
    setFile(null);
    onClose();
  } catch (err) {
    console.error(err);
    alert(err.message || "Upload failed");
  } finally {
    setImporting(false);
  }
};

  const handleCancel = () => {
    setCancelConfirmOpen(true); // open MUI cancel confirm dialog
  };

  const handleConfirmCancel = () => {
    setCancelConfirmOpen(false);
    setTitle("");
    setVenue("");
    setAmount("");
    setBeneficiaryCount("");
    setDate("");
    setCategory("");
    setSector("");
    setFile(null);
    onClose();
  };

  return (
    <>
      <Dialog
        open={open}
        onClose={handleCancel}
        maxWidth="sm"
        fullWidth
        fullScreen={fullScreen}
        TransitionComponent={Transition}
      >
        <DialogTitle>Add New Payout</DialogTitle>
        <DialogContent>
          <Stack spacing={2} mt={1}>
            <TextField
              label="Title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              fullWidth
            />
            <TextField
              label="Venue"
              value={venue}
              onChange={(e) => setVenue(e.target.value)}
              fullWidth
            />
            <TextField
              label="Amount"
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              fullWidth
            />
            <TextField
              label="Beneficiaries"
              type="number"
              value={beneficiaryCount}
              onChange={(e) => setBeneficiaryCount(e.target.value)}
              fullWidth
            />
            <TextField
              label="Date"
              type="date"
              InputLabelProps={{ shrink: true }}
              value={date}
              onChange={(e) => setDate(e.target.value)}
              fullWidth
            />

            <Stack direction={{ xs: "column", sm: "row" }} spacing={2}>
              <TextField
                select
                label="Category"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                fullWidth
              >
                {categories.map((c, i) => (
                  <MenuItem key={i} value={c}>
                    {c}
                  </MenuItem>
                ))}
              </TextField>

              <TextField
                select
                label="Sector"
                value={sector}
                onChange={(e) => setSector(e.target.value)}
                fullWidth
              >
                {sectors.map((s, i) => (
                  <MenuItem key={i} value={s}>
                    {s}
                  </MenuItem>
                ))}
              </TextField>
            </Stack>

            <Button
              variant="contained"
              component="label"
              startIcon={<UploadFileIcon />}
            >
              Choose File
              <input
                type="file"
                hidden
                accept=".xlsx,.xls"
                onChange={handleFileChange}
              />
            </Button>

            {file && (
              <Typography sx={{ fontSize: 14, fontWeight: 500 }}>
                Selected: {file.name}
              </Typography>
            )}
            {importing && <LinearProgress />}
          </Stack>
        </DialogContent>

        <DialogActions>
          <Button onClick={handleCancel}>Cancel</Button>
          <Button
            onClick={handleConfirm}
            variant="contained"
            color="primary"
            disabled={importing}
          >
            Import
          </Button>
        </DialogActions>
      </Dialog>

      {/* Confirm Import Dialog */}
      <Dialog open={confirmOpen} onClose={() => setConfirmOpen(false)}>
        <DialogTitle>Confirm Import</DialogTitle>
        <DialogContent>
          Are you sure you want to import this payout?
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmOpen(false)}>Cancel</Button>
          <Button color="primary" variant="contained" onClick={handleImport}>
            Yes, Import
          </Button>
        </DialogActions>
      </Dialog>

      {/* Confirm Cancel Dialog */}
      <Dialog open={cancelConfirmOpen} onClose={() => setCancelConfirmOpen(false)}>
        <DialogTitle>Confirm Cancel</DialogTitle>
        <DialogContent>
          Are you sure you want to cancel? All inputs will be cleared.
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCancelConfirmOpen(false)}>No</Button>
          <Button color="error" variant="contained" onClick={handleConfirmCancel}>
            Yes, Cancel
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default AddNewPayoutDialog;