import React, { useState, useEffect, useMemo } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import AdvancedSettings from "./components/AdvancedSettings";
import VotersAddressTable from "./components/VotersAddressTable";
import {
  Box,
  Typography,
  Button,
} from "@mui/material";
import { FileDownload, Print } from "@mui/icons-material";
import { Refresh } from "@mui/icons-material";
import { db } from "../../firebase";
import { collection, getDocs, query, limit, startAfter, orderBy } from "firebase/firestore";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import * as XLSX from "xlsx";

const VotersAddress = () => {
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [allVotersAddresses, setAllVotersAddresses] = useState([]);
  const [selectedVotersAddresses, setSelectedVotersAddresses] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [allTableData, setAllTableData] = useState([]);
  const [selectedColumns, setSelectedColumns] = useState({
    VOTER: true,
    ADMIN: true,
    OPPOSITION: true,
    "NO STATUS": true,
    UNTAGGED: true,
  });

  // Fetch barangays and table data in single pass for better performance
  useEffect(() => {
    const fetchAllData = async () => {
      // Check if data exists in localStorage
      const cachedData = localStorage.getItem("votersAddressData");
      if (cachedData) {
        try {
          const parsedData = JSON.parse(cachedData);
          setAllVotersAddresses(parsedData.barangays);
          setSelectedVotersAddresses(parsedData.barangays);
          setAllTableData(parsedData.tableData);
          setLoadingProgress(100);
          return; // Skip fetching if cached data exists
        } catch (err) {
          console.warn("Failed to load cached data:", err);
        }
      }

      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const barangaysSet = new Set();
        const barangayDataMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        let totalProcessedDocs = 0;
        const BATCH_SIZE = 10000; // Firestore max limit is 10000

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          totalProcessedDocs += snapshot.docs.length;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const votingStatus = (voter.VotingStatus || "").toUpperCase().trim();
            
            if (votingStatus !== "VOTER") {
              return;
            }

            let barangay = voter.VotersBarangay || voter.Barangay || voter.Address || "Unknown";
            barangay = String(barangay).trim();

            if (barangay && barangay !== "Unknown" && barangay !== "") {
              // Add to barangays set
              barangaysSet.add(barangay);

              // Initialize barangay data if not exists
              if (!barangayDataMap.has(barangay)) {
                barangayDataMap.set(barangay, {
                  barangay: barangay,
                  VOTER: 0,
                  ADMIN: 0,
                  OPPOSITION: 0,
                  "NO STATUS": 0,
                  UNTAGGED: 0,
                });
              }

              // Count political status
              const status = (voter.PoliticalStatus || "UNTAGGED").toUpperCase().trim();
              const currentData = barangayDataMap.get(barangay);

              switch (status) {
                case "ADMIN":
                  currentData.ADMIN += 1;
                  break;
                case "OPPOSITION":
                  currentData.OPPOSITION += 1;
                  break;
                case "NO STATUS":
                case "NO_STATUS":
                case "":
                  currentData["NO STATUS"] += 1;
                  break;
                default:
                  currentData.UNTAGGED += 1;
              }
            }
          });

          // Update progress: 0-80% for fetching phase
          const fetchProgress = Math.min(80, Math.floor((totalProcessedDocs / 1000) * 5));
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        // Aggregation phase: 80-90%
        setLoadingProgress(85);
        
        // Process aggregated data
        const aggregatedData = Array.from(barangayDataMap.values()).map(row => ({
          ...row,
          VOTER: row.ADMIN + row.OPPOSITION + row["NO STATUS"] + row.UNTAGGED,
          TOTAL: row.ADMIN + row.OPPOSITION + row["NO STATUS"] + row.UNTAGGED
        }));

        aggregatedData.sort((a, b) => a.barangay.localeCompare(b.barangay));

        // Preparation phase: 90-99%
        setLoadingProgress(95);

        // Set both barangays and table data
        const barangays = Array.from(barangaysSet).sort();
        setAllVotersAddresses(barangays);
        setSelectedVotersAddresses(barangays);
        setAllTableData(aggregatedData);
        
        // Cache data to localStorage
        try {
          localStorage.setItem("votersAddressData", JSON.stringify({
            barangays: barangays,
            tableData: aggregatedData
          }));
        } catch (err) {
          console.warn("Failed to cache data:", err);
        }
        
        // Data ready to display: 100%
        setLoadingProgress(100);
      } catch (err) {
        console.error("Error fetching data:", err);
        setAllVotersAddresses([]);
        setAllTableData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchAllData();
  }, []);

  const handleVotersAddressChange = (value) => {
    // Handle "Select All" option
    if (value.includes("SELECT_ALL_ADDRESS")) {
      if (selectedVotersAddresses.length === allVotersAddresses.length) {
        // All selected, so deselect all
        setSelectedVotersAddresses([]);
      } else {
        // Not all selected, so select all
        setSelectedVotersAddresses(allVotersAddresses);
      }
    } else {
      setSelectedVotersAddresses(value);
    }
  };

  const handleColumnToggle = (column) => {
    setSelectedColumns((prev) => ({
      ...prev,
      [column]: !prev[column],
    }));
  };

  const handleRefreshData = () => {
    // Clear cache and refetch data without reloading page
    localStorage.removeItem("votersAddressData");
    
    const fetchFreshData = async () => {
      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const barangaysSet = new Set();
        const barangayDataMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        let totalProcessedDocs = 0;
        const BATCH_SIZE = 10000;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          totalProcessedDocs += snapshot.docs.length;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const barangay = (voter.VotersBarangay || "").trim();

            if (!barangay) {
              return;
            }

            barangaysSet.add(barangay);

            if (!barangayDataMap.has(barangay)) {
              barangayDataMap.set(barangay, {
                barangay: barangay,
                ADMIN: 0,
                OPPOSITION: 0,
                "NO STATUS": 0,
                UNTAGGED: 0,
              });
            }

            const status = (voter.PoliticalStatus || "UNTAGGED").toUpperCase().trim();
            const currentData = barangayDataMap.get(barangay);

            switch (status) {
              case "ADMIN":
                currentData.ADMIN += 1;
                break;
              case "OPPOSITION":
                currentData.OPPOSITION += 1;
                break;
              case "NO STATUS":
              case "NO_STATUS":
              case "":
                currentData["NO STATUS"] += 1;
                break;
              default:
                currentData.UNTAGGED += 1;
            }
          });

          const fetchProgress = Math.min(80, Math.floor((totalProcessedDocs / 1000) * 5));
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        setLoadingProgress(85);
        
        const aggregatedData = Array.from(barangayDataMap.values()).map(row => ({
          ...row,
          VOTER: row.ADMIN + row.OPPOSITION + row["NO STATUS"] + row.UNTAGGED,
          TOTAL: row.ADMIN + row.OPPOSITION + row["NO STATUS"] + row.UNTAGGED
        }));

        aggregatedData.sort((a, b) => a.barangay.localeCompare(b.barangay));

        setLoadingProgress(95);

        const barangays = Array.from(barangaysSet).sort();
        setAllVotersAddresses(barangays);
        setSelectedVotersAddresses(barangays);
        setAllTableData(aggregatedData);
        
        try {
          localStorage.setItem("votersAddressData", JSON.stringify({
            barangays: barangays,
            tableData: aggregatedData
          }));
        } catch (err) {
          console.warn("Failed to cache data:", err);
        }
        
        setLoadingProgress(100);
      } catch (err) {
        console.error("Error fetching data:", err);
        setAllVotersAddresses([]);
        setAllTableData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchFreshData();
  };

  // Get filtered data based on selected barangays
  const filteredTableData = useMemo(() => {
    if (selectedVotersAddresses.length === 0) {
      return allTableData;
    }
    return allTableData.filter(row => 
      selectedVotersAddresses.includes(row.barangay)
    );
  }, [selectedVotersAddresses, allTableData]);

  // Export to PDF
  const exportToPDF = () => {
    const doc = new jsPDF();
    const tableData = filteredTableData.map(row => [
      row.barangay,
      selectedColumns.VOTER ? row.VOTER.toLocaleString() : "-",
      selectedColumns.ADMIN ? row.ADMIN.toLocaleString() : "-",
      selectedColumns.OPPOSITION ? row.OPPOSITION.toLocaleString() : "-",
      selectedColumns["NO STATUS"] ? row["NO STATUS"].toLocaleString() : "-",
      selectedColumns.UNTAGGED ? row.UNTAGGED.toLocaleString() : "-",
      row.TOTAL.toLocaleString(),
    ]);

    const headers = ["BARANGAY"];
    if (selectedColumns.VOTER) headers.push("VOTER");
    if (selectedColumns.ADMIN) headers.push("ADMIN");
    if (selectedColumns.OPPOSITION) headers.push("OPPOSITION");
    if (selectedColumns["NO STATUS"]) headers.push("NO STATUS");
    if (selectedColumns.UNTAGGED) headers.push("UNTAGGED");
    headers.push("TOTAL");

    const totals = filteredTableData.reduce((sum, row) => {
      const voter = selectedColumns.VOTER ? row.VOTER : 0;
      const admin = selectedColumns.ADMIN ? row.ADMIN : 0;
      const opposition = selectedColumns.OPPOSITION ? row.OPPOSITION : 0;
      const noStatus = selectedColumns["NO STATUS"] ? row["NO STATUS"] : 0;
      const untagged = selectedColumns.UNTAGGED ? row.UNTAGGED : 0;
      return {
        barangay: "TOTAL",
        voter: sum.voter + voter,
        admin: sum.admin + admin,
        opposition: sum.opposition + opposition,
        noStatus: sum.noStatus + noStatus,
        untagged: sum.untagged + untagged,
      };
    }, { barangay: "TOTAL", voter: 0, admin: 0, opposition: 0, noStatus: 0, untagged: 0 });

    tableData.push([
      totals.barangay,
      selectedColumns.VOTER ? totals.voter.toLocaleString() : "-",
      selectedColumns.ADMIN ? totals.admin.toLocaleString() : "-",
      selectedColumns.OPPOSITION ? totals.opposition.toLocaleString() : "-",
      selectedColumns["NO STATUS"] ? totals.noStatus.toLocaleString() : "-",
      selectedColumns.UNTAGGED ? totals.untagged.toLocaleString() : "-",
      totals.voter.toLocaleString(), // TOTAL should equal VOTER count
    ]);

    doc.text("Voters Address Report", 14, 10);
    autoTable(doc, {
      head: [headers],
      body: tableData,
      startY: 20,
      theme: "grid",
      headStyles: { fillColor: [26, 35, 126], textColor: 255, fontStyle: "bold" },
    });

    doc.save("Voters_Address_Report.pdf");
  };

  // Export to Excel
  const exportToExcel = () => {
    const exportData = filteredTableData.map(row => ({
      BARANGAY: row.barangay,
      ...(selectedColumns.VOTER && { VOTER: row.VOTER }),
      ...(selectedColumns.ADMIN && { ADMIN: row.ADMIN }),
      ...(selectedColumns.OPPOSITION && { OPPOSITION: row.OPPOSITION }),
      ...(selectedColumns["NO STATUS"] && { "NO STATUS": row["NO STATUS"] }),
      ...(selectedColumns.UNTAGGED && { UNTAGGED: row.UNTAGGED }),
      TOTAL: row.VOTER, // TOTAL should equal VOTER count
    }));

    const totals = filteredTableData.reduce((sum, row) => {
      const voter = selectedColumns.VOTER ? row.VOTER : 0;
      const admin = selectedColumns.ADMIN ? row.ADMIN : 0;
      const opposition = selectedColumns.OPPOSITION ? row.OPPOSITION : 0;
      const noStatus = selectedColumns["NO STATUS"] ? row["NO STATUS"] : 0;
      const untagged = selectedColumns.UNTAGGED ? row.UNTAGGED : 0;
      return {
        barangay: "TOTAL",
        voter: sum.voter + voter,
        admin: sum.admin + admin,
        opposition: sum.opposition + opposition,
        noStatus: sum.noStatus + noStatus,
        untagged: sum.untagged + untagged,
      };
    }, { barangay: "TOTAL", voter: 0, admin: 0, opposition: 0, noStatus: 0, untagged: 0 });

    exportData.push({
      BARANGAY: totals.barangay,
      ...(selectedColumns.VOTER && { VOTER: totals.voter }),
      ...(selectedColumns.ADMIN && { ADMIN: totals.admin }),
      ...(selectedColumns.OPPOSITION && { OPPOSITION: totals.opposition }),
      ...(selectedColumns["NO STATUS"] && { "NO STATUS": totals.noStatus }),
      ...(selectedColumns.UNTAGGED && { UNTAGGED: totals.untagged }),
      TOTAL: totals.voter, // TOTAL should equal VOTER count
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Voters Address");
    XLSX.writeFile(wb, "Voters_Address_Report.xlsx");
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f5f7fa" }}>
      <Sidebar />
      <Box
        sx={{
          flexGrow: 1,
          width: { xs: "100%", md: "calc(100% - 260px)" },
          display: "flex",
          flexDirection: "column",
          minHeight: "100vh",
        }}
      >
        <Topbar />
        <Box sx={{ flexGrow: 1, p: 2, overflowX: "auto" }}>
          {/* Advanced Settings Component */}
          <AdvancedSettings
            advancedOpen={advancedOpen}
            setAdvancedOpen={setAdvancedOpen}
            selectedColumns={selectedColumns}
            handleColumnToggle={handleColumnToggle}
            allVotersAddresses={allVotersAddresses}
            selectedVotersAddresses={selectedVotersAddresses}
            handleVotersAddressChange={handleVotersAddressChange}
          />
          {/* Header with title and buttons */}
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
            <Box>
              <Typography variant="h5" sx={{ color: "#1a237e", fontWeight: 700 }}>
                Voters Address Report
              </Typography>
              <Typography variant="caption" sx={{ color: "#666", mt: 0.5, display: "block" }}>
                Political Status Distribution by Barangay
              </Typography>
            </Box>
            <Box sx={{ display: "flex", gap: 1 }}>
              <Button
                startIcon={<Refresh />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={handleRefreshData}
              >
                Refresh Data
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={exportToPDF}
              >
                Export PDF
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={exportToExcel}
              >
                Export Excel
              </Button>
              <Button
                startIcon={<Print />}
                variant="contained"
                color="success"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
              >
                Print Email
              </Button>
            </Box>
          </Box>

          {/* Table Component */}
          <VotersAddressTable 
            selectedColumns={selectedColumns}
            selectedVotersAddresses={selectedVotersAddresses}
            allTableData={allTableData}
            loading={loading}
            loadingProgress={loadingProgress}
          />
        </Box>
      </Box>
    </Box>
  );
};

export default VotersAddress;
