import React, { useState, useEffect } from 'react';
import { db, auth } from '../../firebase';
import { collection, getDocs, updateDoc, deleteDoc, doc, setDoc } from 'firebase/firestore';
import { createUserWithEmailAndPassword, sendEmailVerification } from 'firebase/auth';
import './UserManagement.css';

const UserManagement = ({ onBack }) => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedRole, setSelectedRole] = useState('all');
  const [currentPage, setCurrentPage] = useState(1);
  const [editingUser, setEditingUser] = useState(null);
  const [showConfirmDelete, setShowConfirmDelete] = useState(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editFormData, setEditFormData] = useState({});
  const [showConfirmEdit, setShowConfirmEdit] = useState(false);
  const [saveLoading, setSaveLoading] = useState(false);
  const [showAddUserModal, setShowAddUserModal] = useState(false);
  const [addFormData, setAddFormData] = useState({});
  const [showConfirmAdd, setShowConfirmAdd] = useState(false);
  const [addLoading, setAddLoading] = useState(false);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [availableServices, setAvailableServices] = useState([]);
  const [confirmPassword, setConfirmPassword] = useState('');

  const itemsPerPage = 3;

  useEffect(() => {
    fetchServices();
    fetchUsers();
  }, []);

  const fetchServices = async () => {
    try {
      const servicesRef = collection(db, 'services');
      const snapshot = await getDocs(servicesRef);
      const servicesList = snapshot.docs.map(doc => doc.data().name).filter(Boolean);
      setAvailableServices(servicesList);
    } catch (err) {
      console.error('Error fetching services:', err);
      setAvailableServices([]);
    }
  };

  const fetchUsers = async () => {
    try {
      setLoading(true);
      setError('');

      const usersRef = collection(db, 'users');
      const snapshot = await getDocs(usersRef);
      const usersList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      setUsers(usersList);
      setCurrentPage(1);
    } catch (err) {
      console.error('Error fetching users:', err);
      setError('Failed to load users');
      setUsers([]);
    } finally {
      setLoading(false);
    }
  };

  const openEditModal = (user) => {
    setEditingUser(user);
    setEditFormData({
      username: user.username || '',
      name: user.name || '',
      email: user.email || '',
      role: user.role || 'user',
      serviceAccess: user.serviceAccess || []
    });
    setShowEditModal(true);
  };

  const handleEditFieldChange = (field, value) => {
    setEditFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleServiceAccessChangeEdit = (service, checked) => {
    setEditFormData(prev => ({
      ...prev,
      serviceAccess: checked
        ? [...(prev.serviceAccess || []), service]
        : (prev.serviceAccess || []).filter(s => s !== service)
    }));
  };

  const handleSaveUserChanges = async () => {
    if (!editingUser) return;

    try {
      setSaveLoading(true);
      setError('');

      const userRef = doc(db, 'users', editingUser.id);
      await updateDoc(userRef, {
        username: editFormData.username,
        name: editFormData.name,
        email: editFormData.email,
        role: editFormData.role,
        serviceAccess: editFormData.role === 'encoder' ? editFormData.serviceAccess : [],
        updatedAt: new Date()
      });

      setUsers(users.map(u =>
        u.id === editingUser.id
          ? { ...u, ...editFormData }
          : u
      ));

      setSuccess('✓ User updated successfully!');
      setShowEditModal(false);
      setShowConfirmEdit(false);
      setEditingUser(null);
      setEditFormData({});
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Error saving user:', err);
      setError('Failed to save user: ' + err.message);
      setTimeout(() => setError(''), 3000);
    } finally {
      setSaveLoading(false);
    }
  };

  const handleDeleteUser = async (userId) => {
    try {
      setDeleteLoading(true);
      setError('');

      // Delete user from Firestore only
      // Note: User can't access the system without a Firestore record,
      // but theoretically could attempt to use Firebase Auth if they have the password
      await deleteDoc(doc(db, 'users', userId));
      setUsers(users.filter(u => u.id !== userId));

      setSuccess('✓ User deleted successfully!');
      setShowConfirmDelete(null);
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Error deleting user:', err);
      setError('Failed to delete user: ' + err.message);
      setTimeout(() => setError(''), 3000);
    } finally {
      setDeleteLoading(false);
    }
  };

  const handleAddFieldChange = (field, value) => {
    setAddFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleServiceAccessChangeNew = (service, checked) => {
    setAddFormData(prev => ({
      ...prev,
      serviceAccess: checked
        ? [...(prev.serviceAccess || []), service]
        : (prev.serviceAccess || []).filter(s => s !== service)
    }));
  };

  const handleCreateUser = async () => {
    if (!addFormData.username || !addFormData.email || !addFormData.password) {
      setError('Please fill in all required fields');
      setTimeout(() => setError(''), 3000);
      return;
    }

    if (addFormData.password.length < 6) {
      setError('Password must be at least 6 characters');
      setTimeout(() => setError(''), 3000);
      return;
    }

    if (addFormData.password !== confirmPassword) {
      setError('Passwords do not match');
      setTimeout(() => setError(''), 3000);
      return;
    }

    if (addFormData.role === 'encoder' && (!addFormData.serviceAccess || addFormData.serviceAccess.length === 0)) {
      setError('Please select at least one service for encoder role');
      setTimeout(() => setError(''), 3000);
      return;
    }

    setAddLoading(true);

    try {
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        addFormData.email,
        addFormData.password
      );

      const uid = userCredential.user.uid;

      // Send email verification
      await sendEmailVerification(userCredential.user, {
        url: window.location.origin + '/login',
        handleCodeInApp: false
      });

      const userRef = doc(db, 'users', uid);
      await setDoc(userRef, {
        username: addFormData.username,
        name: addFormData.name || '',
        email: addFormData.email,
        role: addFormData.role,
        serviceAccess: addFormData.role === 'encoder' ? addFormData.serviceAccess : [],
        createdAt: new Date(),
        updatedAt: new Date(),
        status: 'pending',
        emailVerified: false
      }, { merge: true });

      setUsers([
        ...users,
        {
          id: uid,
          username: addFormData.username,
          name: addFormData.name || '',
          email: addFormData.email,
          role: addFormData.role,
          serviceAccess: addFormData.role === 'encoder' ? addFormData.serviceAccess : [],
          createdAt: new Date(),
          status: 'pending',
          emailVerified: false
        }
      ]);

      setSuccess('✓ User account created! Verification email sent to ' + addFormData.email);
      setShowAddUserModal(false);
      setShowConfirmAdd(false);
      setAddFormData({
        username: '',
        name: '',
        email: '',
        password: '',
        role: 'user',
        serviceAccess: []
      });
      setConfirmPassword('');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      console.error('Error creating user:', err);

      if (err.code === 'auth/email-already-in-use') {
        setError('Email is already registered in the system');
      } else if (err.code === 'auth/invalid-email') {
        setError('Invalid email format');
      } else if (err.code === 'auth/weak-password') {
        setError('Password is too weak. Use at least 6 characters');
      } else {
        setError('Failed to create user account: ' + err.message);
      }
      setTimeout(() => setError(''), 3000);
    } finally {
      setAddLoading(false);
    }
  };

  const filteredUsers = users.filter(user => {
    const matchesSearch =
      user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.username?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesRole = selectedRole === 'all' || user.role === selectedRole;
    const isNotSuperAdmin = user.role !== 'superadmin';
    return matchesSearch && matchesRole && isNotSuperAdmin;
  });

  const paginatedUsers = filteredUsers.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const totalPages = Math.ceil(filteredUsers.length / itemsPerPage);

  const getServiceIcon = (service) => {
    const iconMap = {
      'Pharmacy': { icon: 'pill', color: '#f43f5e' },
      'Services': { icon: 'build', color: '#2dd4bf' },
      'Reports': { icon: 'bar_chart', color: '#a78bfa' }
    };

    const serviceData = iconMap[service] || { icon: 'info', color: '#0284c7' };

    return (
      <div 
        key={service}
        className="service-icon-circle"
        title={service}
      >
        <span
          className="material-symbols-outlined"
          style={{ color: serviceData.color, fontSize: '14px' }}
        >
          {serviceData.icon}
        </span>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="user-management">
        <div className="loading-message">Loading users...</div>
      </div>
    );
  }

  return (
    <main className="user-management">
      {/* Snackbar for messages */}
      {error && (
        <div className="snackbar snackbar-error">
          <div className="snackbar-content">
            <span>{error}</span>
          </div>
        </div>
      )}
      {success && (
        <div className="snackbar snackbar-success">
          <div className="snackbar-content">
            <span>{success}</span>
          </div>
        </div>
      )}

      {/* Header Section */}
      <div className="user-management-header">
        <div className="header-top">
          <div className="header-left">
            <button className="back-btn" onClick={onBack}>
              <span className="material-symbols-outlined">arrow_back</span>
              Back
            </button>
            <div className="header-title-section">
              <span className="material-symbols-outlined header-icon">group</span>
              <div>
                <h2>User Management</h2>
                <p>Manage system users and their roles</p>
              </div>
            </div>
          </div>
          <button
            className="btn-add-user"
            onClick={() => {
              setAddFormData({
                username: '',
                name: '',
                email: '',
                password: '',
                role: 'user',
                serviceAccess: []
            });
            setConfirmPassword('');
            setShowAddUserModal(true);
            }}
          >
            <span className="material-symbols-outlined">add</span>
            Add User
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="stats-cards">
        <div className="stat-card stat-blue">
          <div className="stat-icon-box blue">
            <span className="material-symbols-outlined">groups</span>
          </div>
          <div>
            <p className="stat-label">Total Users</p>
            <p className="stat-value">{filteredUsers.length}</p>
          </div>
        </div>

        <div className="stat-card stat-orange">
          <div className="stat-icon-box orange">
            <span className="material-symbols-outlined">admin_panel_settings</span>
          </div>
          <div>
            <p className="stat-label">Admins</p>
            <p className="stat-value">{filteredUsers.filter(u => u.role === 'admin').length}</p>
          </div>
        </div>

        <div className="stat-card stat-indigo">
          <div className="stat-icon-box indigo">
            <span className="material-symbols-outlined">edit_note</span>
          </div>
          <div>
            <p className="stat-label">Encoders</p>
            <p className="stat-value">{filteredUsers.filter(u => u.role === 'encoder').length}</p>
          </div>
        </div>
      </div>

      {/* Users Table */}
      <div className="users-container">
        <div className="table-filters">
          <div className="search-box">
            <span className="material-symbols-outlined search-icon">search</span>
            <input
              type="text"
              placeholder="Search by username, email or name..."
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                setCurrentPage(1);
              }}
              className="search-input"
            />
          </div>

          <div className="role-filter">
            <label>Filter by Role:</label>
            <select
              value={selectedRole}
              onChange={(e) => {
                setSelectedRole(e.target.value);
                setCurrentPage(1);
              }}
            >
              <option value="all">All Roles</option>
              <option value="admin">Admin</option>
              <option value="encoder">Encoder</option>
              <option value="user">User</option>
              <option value="superadmin">Super Admin</option>
            </select>
          </div>
        </div>

        {filteredUsers.length === 0 ? (
          <div className="no-users">
            <p>No users found matching your criteria</p>
          </div>
        ) : (
          <>
            <div className="table-wrapper">
              <table className="users-table">
                <thead>
                  <tr>
                    <th>Username</th>
                    <th>Role</th>
                    <th>Status</th>
                    <th>Service Access</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedUsers.map((user) => (
                    <tr key={user.id}>
                      <td>
                        <div className="user-cell">
                          <div className="user-avatar">
                            {(user.username || user.email)[0].toUpperCase()}
                          </div>
                          <span className="user-name">{user.username || user.email}</span>
                        </div>
                      </td>
                      <td>
                        <span className={`role-badge role-${user.role}`}>
                          {user.role === 'admin' ? 'Admin' : user.role === 'encoder' ? 'Encoder' : user.role === 'superadmin' ? 'Super Admin' : 'User'}
                        </span>
                      </td>
                      <td>
                        <span className={`status-badge ${user.status === 'active' ? 'status-active' : user.status === 'pending' ? 'status-pending' : 'status-inactive'}`}>
                          <span className="status-dot"></span>
                          {user.status === 'active' ? 'Active' : user.status === 'pending' ? 'Pending Verification' : 'Inactive'}
                        </span>
                      </td>
                      <td>
                        <div className="service-icons-container">
                          {user.role === 'encoder' && (user.serviceAccess || []).length > 0 ? (
                            (user.serviceAccess || []).map((service) => 
                              getServiceIcon(service)
                            )
                          ) : (
                            <span className="no-services">-</span>
                          )}
                        </div>
                      </td>
                      <td>
                        <div className="action-buttons">
                          <button
                            className="btn-edit"
                            onClick={() => openEditModal(user)}
                          >
                            <span className="material-symbols-outlined">edit</span>
                            Edit
                          </button>
                          <button
                            className="btn-delete"
                            onClick={() => setShowConfirmDelete(user.id)}
                          >
                            <span className="material-symbols-outlined">delete</span>
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div className="table-pagination">
              <p className="pagination-info">
                Showing <span className="font-bold">{paginatedUsers.length}</span> of <span className="font-bold">{filteredUsers.length}</span> users
              </p>
              <div className="pagination-buttons">
                <button
                  className="pagination-btn"
                  onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                  disabled={currentPage === 1}
                >
                  <span className="material-symbols-outlined">chevron_left</span>
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
                  <button
                    key={page}
                    className={`pagination-number ${currentPage === page ? 'active' : ''}`}
                    onClick={() => setCurrentPage(page)}
                  >
                    {page}
                  </button>
                ))}
                <button
                  className="pagination-btn"
                  onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                  disabled={currentPage === totalPages}
                >
                  <span className="material-symbols-outlined">chevron_right</span>
                </button>
              </div>
            </div>
          </>
        )}
      </div>

      {/* Edit Modal */}
      {showEditModal && editingUser && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content modal-content-wide" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header modal-header-enhanced">
              <div>
                <h3>Edit User Details</h3>
                <p className="modal-subtitle">Update this account and adjust role or access.</p>
              </div>
              <button className="modal-close" onClick={() => setShowEditModal(false)}>
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>

            <div className="form-grid">
              <div className="form-group">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">person</span>
                  Username
                </label>
                <input
                  type="text"
                  value={editFormData.username}
                  onChange={(e) => handleEditFieldChange('username', e.target.value)}
                  placeholder="johndoe123"
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">badge</span>
                  Full Name
                </label>
                <input
                  type="text"
                  value={editFormData.name}
                  onChange={(e) => handleEditFieldChange('name', e.target.value)}
                  placeholder="John Doe"
                  className="form-input"
                />
              </div>

              <div className="form-group form-group-full">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">alternate_email</span>
                  Email Address
                </label>
                <input
                  type="email"
                  value={editFormData.email}
                  onChange={(e) => handleEditFieldChange('email', e.target.value)}
                  placeholder="john@example.com"
                  className="form-input"
                />
              </div>

              <div className="form-group form-group-full">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">manage_accounts</span>
                  User Role
                </label>
                <div className="select-wrapper">
                  <select
                    value={editFormData.role || 'user'}
                    onChange={(e) => handleEditFieldChange('role', e.target.value)}
                    className="form-select"
                  >
                    <option value="admin">Administrator</option>
                    <option value="encoder">Encoder</option>
                    <option value="user">User</option>
                  </select>
                  <span className="material-symbols-outlined select-arrow">expand_more</span>
                </div>
              </div>

              {editFormData.role === 'encoder' && (
                <div className="form-group form-group-full">
                  <label className="label-with-icon">
                    <span className="material-symbols-outlined label-icon">apps</span>
                    Service Access
                  </label>
                  <div className="services-checkboxes">
                    {availableServices.map((service) => (
                      <div key={service} className="checkbox-group">
                        <input
                          type="checkbox"
                          id={`edit-service-${service}`}
                          checked={(editFormData.serviceAccess || []).includes(service)}
                          onChange={(e) => handleServiceAccessChangeEdit(service, e.target.checked)}
                        />
                        <label htmlFor={`edit-service-${service}`}>{service}</label>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="modal-actions modal-actions-enhanced">
              <button
                className="btn-cancel"
                onClick={() => setShowEditModal(false)}
              >
                <span className="material-symbols-outlined">close</span>
                Cancel
              </button>
              <button
                className="btn-save"
                onClick={() => setShowConfirmEdit(true)}
              >
                <span className="material-symbols-outlined">save</span>
                Save Changes
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirm Edit Modal */}
      {showConfirmEdit && (
        <div className="modal-overlay" onClick={() => setShowConfirmEdit(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Confirm Changes</h3>
              <button className="modal-close" onClick={() => setShowConfirmEdit(false)}>
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>
            <p>Are you sure you want to save these changes? This action will update the user details.</p>
            <div className="modal-actions">
              <button
                className="btn-cancel"
                onClick={() => setShowConfirmEdit(false)}
                disabled={saveLoading}
              >
                Cancel
              </button>
              <button
                className="btn-save"
                onClick={handleSaveUserChanges}
                disabled={saveLoading}
              >
                {saveLoading ? 'Saving...' : 'Confirm'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add User Modal */}
      {showAddUserModal && (
        <div className="modal-overlay" onClick={() => setShowAddUserModal(false)}>
          <div className="modal-content modal-content-wide" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header modal-header-enhanced">
              <div>
                <h3>Add New User</h3>
                <p className="modal-subtitle">Create a new account and assign a role.</p>
              </div>
              <button className="modal-close" onClick={() => setShowAddUserModal(false)}>
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>

            <div className="form-grid">
              <div className="form-group">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">person</span>
                  Username
                </label>
                <input
                  type="text"
                  value={addFormData.username || ''}
                  onChange={(e) => handleAddFieldChange('username', e.target.value)}
                  placeholder="johndoe123"
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">badge</span>
                  Full Name
                </label>
                <input
                  type="text"
                  value={addFormData.name || ''}
                  onChange={(e) => handleAddFieldChange('name', e.target.value)}
                  placeholder="John Doe"
                  className="form-input"
                />
              </div>

              <div className="form-group form-group-full">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">alternate_email</span>
                  Email Address
                </label>
                <input
                  type="email"
                  value={addFormData.email || ''}
                  onChange={(e) => handleAddFieldChange('email', e.target.value)}
                  placeholder="john@example.com"
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">lock</span>
                  Password
                </label>
                <input
                  type="password"
                  value={addFormData.password || ''}
                  onChange={(e) => handleAddFieldChange('password', e.target.value)}
                  placeholder="••••••••"
                  className="form-input"
                />
              </div>

              <div className="form-group">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">verified_user</span>
                  Confirm Password
                </label>
                <input
                  type="password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder="••••••••"
                  className="form-input"
                />
              </div>

              <div className="form-group form-group-full">
                <label className="label-with-icon">
                  <span className="material-symbols-outlined label-icon">manage_accounts</span>
                  User Role
                </label>
                <div className="select-wrapper">
                  <select
                    value={addFormData.role || 'user'}
                    onChange={(e) => handleAddFieldChange('role', e.target.value)}
                    className="form-select"
                  >
                    <option value="admin">Administrator</option>
                    <option value="encoder">Encoder</option>
                    <option value="user">User</option>
                  </select>
                  <span className="material-symbols-outlined select-arrow">expand_more</span>
                </div>
              </div>

              {addFormData.role === 'encoder' && (
                <div className="form-group form-group-full">
                  <label className="label-with-icon">
                    <span className="material-symbols-outlined label-icon">apps</span>
                    Service Access
                  </label>
                  <div className="services-checkboxes">
                    {availableServices.map((service) => (
                      <div key={service} className="checkbox-group">
                        <input
                          type="checkbox"
                          id={`new-service-${service}`}
                          checked={(addFormData.serviceAccess || []).includes(service)}
                          onChange={(e) => handleServiceAccessChangeNew(service, e.target.checked)}
                        />
                        <label htmlFor={`new-service-${service}`}>{service}</label>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="modal-actions modal-actions-enhanced">
              <button
                className="btn-cancel"
                onClick={() => setShowAddUserModal(false)}
              >
                Cancel
              </button>
              <button
                className="btn-create"
                onClick={() => setShowConfirmAdd(true)}
              >
                <span className="material-symbols-outlined">person_add</span>
                Create User
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirm Add Modal */}
      {showConfirmAdd && (
        <div className="modal-overlay" onClick={() => setShowConfirmAdd(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Confirm New User</h3>
              <button className="modal-close" onClick={() => setShowConfirmAdd(false)}>
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>
            <p>Are you sure you want to create this user account with the following details?</p>
            <div className="confirm-details">
              <p><strong>Username:</strong> {addFormData.username}</p>
              <p><strong>Email:</strong> {addFormData.email}</p>
              <p><strong>Role:</strong> {addFormData.role}</p>
            </div>
            <div className="modal-actions">
              <button
                className="btn-cancel"
                onClick={() => setShowConfirmAdd(false)}
                disabled={addLoading}
              >
                Cancel
              </button>
              <button
                className="btn-save"
                onClick={handleCreateUser}
                disabled={addLoading}
              >
                {addLoading ? 'Creating...' : 'Confirm'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showConfirmDelete && (
        <div className="modal-overlay" onClick={() => setShowConfirmDelete(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Confirm Delete</h3>
              <button className="modal-close" onClick={() => setShowConfirmDelete(null)}>
                <span className="material-symbols-outlined">close</span>
              </button>
            </div>
            <p>Are you sure you want to delete this user? This action cannot be undone.</p>
            <div className="modal-actions">
              <button
                className="btn-cancel"
                onClick={() => setShowConfirmDelete(null)}
                disabled={deleteLoading}
              >
                Cancel
              </button>
              <button
                className="btn-delete-confirm"
                onClick={() => handleDeleteUser(showConfirmDelete)}
                disabled={deleteLoading}
              >
                {deleteLoading ? 'Deleting...' : 'Delete'}
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
};

export default UserManagement;
