import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../../../firebase';
import { signOut } from 'firebase/auth';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import LoadingScreen from '../../../components/LoadingScreen';
import './ServicesPage.css';

// Service definitions with colors and icons
const ALL_SERVICES = [
  {
    id: 'medicine-assistant',
    name: 'MEDICINE ASSISTANT',
    icon: '💊',
    color: '#f43f5e',
    description: 'Ensuring safe, timely, and accurate medication use by providing guidance, reminders, and patient support.'
  },
  {
    id: 'burial-assistance',
    name: 'BURIAL ASSISTANCE',
    icon: '🤝',
    color: '#f59e0b',
    description: 'Supporting families in their time of loss with financial aid and logistical arrangements for funeral services.'
  },
  {
    id: 'education-support',
    name: 'EDUCATION SUPPORT',
    icon: '🎓',
    color: '#3b82f6',
    description: 'Educational scholarships, supply kits, and tutoring programs for students from low-income households.'
  },
  {
    id: 'financial-aid',
    name: 'FINANCIAL AID',
    icon: '💼',
    color: '#10b981',
    description: 'Immediate monetary assistance for emergency situations and essential living expenses.'
  },
  {
    id: 'livelihood-programs',
    name: 'LIVELIHOOD PROGRAMS',
    icon: '💼',
    color: '#a855f7',
    description: 'Skills training, job placement assistance, and seed funding for community enterprise initiatives.'
  },
  {
    id: 'health-checkup',
    name: 'HEALTH CHECKUP',
    icon: '⚕️',
    color: '#06b6d4',
    description: 'Schedule appointments for regular health screenings, vaccinations, and basic medical consultations.'
  }
];

const ServicesPage = ({ username: propUsername = 'User' }) => {
  const navigate = useNavigate();
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isCheckingAuth, setIsCheckingAuth] = useState(true);
  const [username, setUsername] = useState(propUsername);
  const [darkMode, setDarkMode] = useState(false);
  const [logs, setLogs] = useState([]);
  const [logsLoading, setLogsLoading] = useState(false);
  const [userInitials, setUserInitials] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef(null);

  // Check authentication
  useEffect(() => {
    const checkAuthentication = () => {
      try {
        const currentUser = auth.currentUser;
        const storedUsername = sessionStorage.getItem('servicesUsername') || localStorage.getItem('servicesUsername');
        const storedUid = sessionStorage.getItem('servicesUid') || localStorage.getItem('servicesUid');
        const storedEmail = sessionStorage.getItem('servicesEmail') || localStorage.getItem('servicesEmail');
        
        if ((currentUser || storedUid) && storedUsername) {
          setUsername(storedUsername);
          setUserInitials(storedUsername.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2));
          setUserEmail(currentUser?.email || storedEmail || '');
          setIsAuthenticated(true);
        } else {
          navigate('/services');
        }
      } catch (err) {
        console.error('Auth check error:', err);
        navigate('/services');
      } finally {
        setIsCheckingAuth(false);
      }
    };

    checkAuthentication();
  }, [navigate]);

  // Fetch available services for user
  useEffect(() => {
    if (isAuthenticated && !isCheckingAuth) {
      fetchServices();
    }
  }, [isAuthenticated, isCheckingAuth]);

  // Fetch logs/applications
  useEffect(() => {
    if (!isAuthenticated || isCheckingAuth || services.length === 0) {
      setLogs([]);
      return;
    }

    setLogsLoading(true);
    const q = query(
      collection(db, 'applications'),
      where('userName', '==', username)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const logsList = snapshot.docs.map(doc => {
        const data = doc.data();
        const createdAt = data.createdAt?.toDate ? data.createdAt.toDate() : 
                         (data.createdAt?.seconds ? new Date(data.createdAt.seconds * 1000) : new Date());
        
        return {
          id: doc.id,
          fullName: data.fullName || (data.formData && data.formData.fullName) || 'N/A',
          serviceName: data.serviceName || data.serviceId || 'Unknown',
          status: data.status || 'PENDING',
          createdAt: createdAt
        };
      });
      setLogs(logsList.sort((a, b) => b.createdAt - a.createdAt));
      setLogsLoading(false);
    }, (err) => {
      console.error('Error loading logs:', err);
      setLogs([]);
      setLogsLoading(false);
    });

    return () => unsubscribe();
  }, [services, isAuthenticated, isCheckingAuth, username]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (err) {
      console.error('Logout failed:', err);
    }
    sessionStorage.clear();
    localStorage.removeItem('servicesUsername');
    localStorage.removeItem('servicesUid');
    localStorage.removeItem('serviceAccess');
    localStorage.removeItem('role');
    navigate('/services');
  };

  const fetchServices = async () => {
    try {
      setLoading(true);
      const userRole = localStorage.getItem('role');
      const serviceAccessStr = localStorage.getItem('serviceAccess');
      
      let availableServices = ALL_SERVICES;

      // Filter services based on user's serviceAccess
      if (userRole === 'encoder' && serviceAccessStr) {
        try {
          const serviceAccess = JSON.parse(serviceAccessStr);
          if (Array.isArray(serviceAccess) && serviceAccess.length > 0) {
            availableServices = ALL_SERVICES.filter(service => 
              serviceAccess.includes(service.name)
            );
          }
        } catch (e) {
          console.error('Error parsing serviceAccess:', e);
        }
      }

      setServices(availableServices);
    } catch (err) {
      console.error('Error fetching services:', err);
      setServices([]);
    } finally {
      setLoading(false);
    }
  };

  // Calculate today's transaction count
  const todayCount = logs.filter(log => {
    const logDate = new Date(log.createdAt);
    const today = new Date();
    return logDate.toDateString() === today.toDateString();
  }).length;

  // Get recent transactions (limit to 5)
  const recentLogs = logs.slice(0, 5);

  if (isCheckingAuth) {
    return <LoadingScreen message="Verifying access..." />;
  }

  return (
    <div className={`services-container ${darkMode ? 'dark' : ''}`}>
      {/* Header with Logo and Actions */}
      <header className="services-page-header">
        <div className="header-left">
          <div className="logo-container">
            <span className="logo-text">
              <span className="logo-green">AKSYON</span>
              <span className="logo-red">AGAD</span>
            </span>
          </div>
        </div>
        <div className="header-right">
          <button 
            className="dark-mode-toggle"
            onClick={() => setDarkMode(!darkMode)}
            title="Toggle dark mode"
          >
            {darkMode ? '☀️' : '🌙'}
          </button>
          <div className="user-menu" ref={menuRef}>
            <button className="user-avatar-header" onClick={() => setMenuOpen(!menuOpen)}>
              {userInitials}
            </button>
            {menuOpen && (
              <div className="user-menu-dropdown">
                <div className="user-menu-header">
                  <div className="user-menu-name">{username}</div>
                  <div className="user-menu-email">{userEmail || 'No email available'}</div>
                </div>
                <button className="user-menu-item">My Profile</button>
                <button className="user-menu-item">Settings</button>
                <button className="user-menu-item logout" onClick={handleLogout}>Logout</button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="services-main">
        <div className="services-max-width">
          {/* Welcome Section with Stat Card */}
          <section className="welcome-section">
            <div className="welcome-content">
              <p className="portal-label">COMMUNITY SERVICES PORTAL</p>
              <h1 className="welcome-title">
                Welcome, <span className="username-highlight">{username}</span>
              </h1>
              <p className="welcome-description">
                Explore and access essential services designed for your community. Our team is here to support you with various welfare and development programs.
              </p>
            </div>
            <div className="today-transactions-card">
              <div className="card-icon">📋</div>
              <div className="card-content">
                <p className="card-label">Today's Transactions</p>
                <p className="card-value">{todayCount}</p>
              </div>
            </div>
          </section>

          {/* Services Grid */}
          <div className="services-grid-wrapper">
            <div className="services-left-col">
              <h2 className="services-section-title">
                ⊞ Available Services
              </h2>
              
              {loading ? (
                <div className="loading-container">Loading services...</div>
              ) : services.length === 0 ? (
                <div className="no-services">No services available</div>
              ) : (
                <div className="services-grid">
                  {services.map(service => (
                    <div key={service.id} className="service-card">
                      <div className="service-card-icon" style={{ 
                        backgroundColor: `${service.color}20`,
                        color: service.color 
                      }}>
                        {service.icon}
                      </div>
                      <h3 className="service-card-title">{service.name}</h3>
                      <p className="service-card-description">{service.description}</p>
                      <button
                        className="service-card-btn"
                        style={{ backgroundColor: service.color }}
                        onClick={() => navigate(`/services/${service.id}`)}
                      >
                        Access Service <span className="btn-arrow">→</span>
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Recent History Sidebar */}
            <div className="services-right-col">
              <div className="history-card">
                <div className="history-header">
                  <h2 className="history-title">⏱ Recent History</h2>
                  <span className="history-badge">Today</span>
                </div>
                
                {logsLoading ? (
                  <div className="history-loading">Loading history...</div>
                ) : recentLogs.length === 0 ? (
                  <div className="history-empty">No transactions yet</div>
                ) : (
                  <div className="history-list">
                    {recentLogs.map((log, idx) => (
                      <div 
                        key={log.id} 
                        className="history-item"
                        onClick={() => navigate(`/services/transaction/${log.id}`)}
                        style={{ cursor: 'pointer' }}
                      >
                        <div className="history-item-left">
                          <div className="history-time">
                            {log.createdAt.toLocaleTimeString('en-US', { 
                              hour: '2-digit', 
                              minute: '2-digit' 
                            })}
                          </div>
                          <h4 className="history-name">{log.fullName}</h4>
                          <p className="history-service">{log.serviceName}</p>
                          <span className={`history-status status-${log.status.toLowerCase().replace(/\s+/g, '-')}`}>
                            {log.status}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
                
                <button className="history-view-all" onClick={() => navigate('/services/transactions')}>View All Transactions</button>
              </div>
            </div>
          </div>

          {/* Detailed History Table */}
          <section className="history-table-section">
            <div className="history-table-header">
              <h3 className="history-table-title">⏳ Detailed History</h3>
              <div className="history-search">
                <input 
                  type="text" 
                  placeholder="Search transactions..." 
                  className="search-input"
                />
              </div>
            </div>

            {logsLoading ? (
              <div className="table-loading">Loading transactions...</div>
            ) : logs.length === 0 ? (
              <div className="table-empty">No transactions found</div>
            ) : (
              <>
                <div className="history-table-wrapper">
                  <table className="history-table">
                    <thead>
                      <tr>
                        <th>Transaction Date</th>
                        <th>Patient / Citizen Name</th>
                        <th>Service Type</th>
                        <th>Status</th>
                        <th>Prepared By</th>
                        <th style={{ textAlign: 'right' }}>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {logs.slice(0, 10).map(log => (
                        <tr key={log.id}>
                          <td>{log.createdAt.toLocaleString()}</td>
                          <td className="table-bold">{log.fullName}</td>
                          <td>{log.serviceName}</td>
                          <td>
                            <span className={`table-status status-${log.status.toLowerCase().replace(/\s+/g, '-')}`}>
                              {log.status}
                            </span>
                          </td>
                          <td className="table-bold">{username}</td>
                          <td style={{ textAlign: 'right' }}>
                            <button 
                              className="table-action"
                              onClick={() => navigate(`/services/transaction/${log.id}`)}
                            >
                              View Details
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="table-pagination">
                  <p>Showing 1-{Math.min(10, logs.length)} of {logs.length} transactions</p>
                  <div className="pagination-buttons">
                    <button className="pagination-btn" disabled>←</button>
                    <button className="pagination-btn">→</button>
                  </div>
                </div>
              </>
            )}
          </section>
        </div>
      </main>

      {/* Footer */}
      <footer className="services-footer">
        <p>© 2026 AKSYON AGAD Community Services Portal. All Rights Reserved.</p>
      </footer>
    </div>
  );
};

export default ServicesPage;
