import React, { useState, useEffect } from 'react';
import { db } from '../../firebase';
import { collection, addDoc, updateDoc, deleteDoc, doc, getDocs } from 'firebase/firestore';
import './ManageServices.css';

const ManageServices = ({ onBack }) => {
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [showConfirmDelete, setShowConfirmDelete] = useState(null);
  const [deleteLoading, setDeleteLoading] = useState(false);
  const [addLoading, setAddLoading] = useState(false);
  const [saveLoading, setSaveLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const serviceTypes = [
    { value: 'medical', label: 'Medical Services' },
    { value: 'medicine', label: 'Medicine Assistant' }
  ];

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    icon: '',
    color: '#667eea',
    type: 'medical'
  });

  const colorOptions = [
    '#667eea', '#f093fb', '#4facfe', '#43e97b', '#fa709a', '#fee140',
    '#a02a2a', '#1f8ef1', '#2a5298', '#764ba2'
  ];

  useEffect(() => {
    fetchServices();
  }, []);

  const fetchServices = async () => {
    try {
      setLoading(true);
      const snapshot = await getDocs(collection(db, 'services'));
      const servicesList = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      setServices(servicesList);
      setError('');
    } catch (err) {
      setError('Failed to load services');
      console.error('Error fetching services:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddService = async (e) => {
    e.preventDefault();
    
    if (!formData.name.trim() || !formData.description.trim() || !formData.icon.trim()) {
      setError('Please fill in all required fields');
      return;
    }

    setAddLoading(true);
    try {
      await addDoc(collection(db, 'services'), {
        name: formData.name.trim(),
        description: formData.description.trim(),
        icon: formData.icon.trim(),
        color: formData.color,
        type: formData.type,
        createdAt: new Date(),
        updatedAt: new Date()
      });

      setSuccess('✓ Service created successfully');
      setTimeout(() => setSuccess(''), 3000);
      setFormData({ name: '', description: '', icon: '', color: '#667eea', type: 'medical' });
      setShowAddModal(false);
      fetchServices();
    } catch (err) {
      setError('Failed to create service');
      console.error('Error adding service:', err);
    } finally {
      setAddLoading(false);
    }
  };

  const handleEditService = async (e) => {
    e.preventDefault();

    if (!formData.name.trim() || !formData.description.trim() || !formData.icon.trim()) {
      setError('Please fill in all required fields');
      return;
    }

    setSaveLoading(true);
    try {
      const serviceRef = doc(db, 'services', editingService.id);
      await updateDoc(serviceRef, {
        name: formData.name.trim(),
        description: formData.description.trim(),
        icon: formData.icon.trim(),
        color: formData.color,
        type: formData.type,
        updatedAt: new Date()
      });

      setSuccess('✓ Service updated successfully');
      setTimeout(() => setSuccess(''), 3000);
      setShowEditModal(false);
      setEditingService(null);
      setFormData({ name: '', description: '', icon: '', color: '#667eea', type: 'medical' });
      fetchServices();
    } catch (err) {
      setError('Failed to update service');
      console.error('Error updating service:', err);
    } finally {
      setSaveLoading(false);
    }
  };

  const handleDeleteService = async (serviceId) => {
    setDeleteLoading(true);
    try {
      await deleteDoc(doc(db, 'services', serviceId));
      setSuccess('✓ Service deleted successfully');
      setTimeout(() => setSuccess(''), 3000);
      setShowConfirmDelete(null);
      fetchServices();
    } catch (err) {
      setError('Failed to delete service');
      console.error('Error deleting service:', err);
    } finally {
      setDeleteLoading(false);
    }
  };

  const openEditModal = (service) => {
    setEditingService(service);
    setFormData({
      name: service.name,
      description: service.description,
      icon: service.icon,
      color: service.color,
      type: service.type || 'medical'
    });
    setShowEditModal(true);
    setError('');
  };

  const handleFieldChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const filteredServices = services.filter(service =>
    service.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    service.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="manage-services">
      <div className="services-header">
        <div className="header-top">
          {onBack && (
            <button className="back-btn" onClick={onBack} title="Go back">
              ← Back
            </button>
          )}
          <h2>🛠️ Manage Services</h2>
        </div>
        <p>Create and manage services that users can access</p>
      </div>

      {success && <div className="success-message">{success}</div>}
      {error && <div className="error-message">{error}</div>}

      <div className="services-controls">
        <div className="search-box">
          <input
            type="text"
            placeholder="🔍 Search services..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
        <button className="add-service-btn" onClick={() => {
          setShowAddModal(true);
          setFormData({ name: '', description: '', icon: '', color: '#667eea', type: 'medical' });
          setError('');
        }}>
          ➕ Add Service
        </button>
      </div>

      {loading ? (
        <div className="loading-state">Loading services...</div>
      ) : filteredServices.length === 0 ? (
        <div className="no-services">
          <p>📭 No services created yet</p>
          <button className="add-service-btn" onClick={() => {
            setShowAddModal(true);
            setFormData({ name: '', description: '', icon: '', color: '#667eea', type: 'medical' });
          }}>
            ➕ Create First Service
          </button>
        </div>
      ) : (
        <div className="services-table">
          <div className="table-header">
            <div className="col-icon">Icon</div>
            <div className="col-name">Service Name</div>
            <div className="col-description">Description</div>
            <div className="col-color">Color</div>
            <div className="col-actions">Actions</div>
          </div>
          
          {filteredServices.map((service) => (
            <div key={service.id} className="table-row">
              <div className="col-icon">
                <span className="service-icon">{service.icon}</span>
              </div>
              <div className="col-name">{service.name}</div>
              <div className="col-description">{service.description}</div>
              <div className="col-color">
                <div className="color-sample" style={{ backgroundColor: service.color }}></div>
              </div>
              <div className="col-actions">
                <button className="action-btn edit-btn" onClick={() => openEditModal(service)}>
                  ✏️ Edit
                </button>
                <button className="action-btn delete-btn" onClick={() => setShowConfirmDelete(service.id)}>
                  🗑️ Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Add Service Modal */}
      {showAddModal && (
        <div className="modal-overlay" onClick={() => setShowAddModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close" onClick={() => setShowAddModal(false)}>✕</button>
            <h3>➕ Add New Service</h3>
            <form onSubmit={handleAddService}>
              <div className="form-group">
                <label>Service Name *</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleFieldChange}
                  placeholder="e.g., Housing Services"
                  className="form-input"
                  disabled={addLoading}
                />
              </div>

              <div className="form-group">
                <label>Description *</label>
                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleFieldChange}
                  placeholder="e.g., Apply for housing assistance..."
                  className="form-input"
                  rows="3"
                  disabled={addLoading}
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Icon/Emoji *</label>
                  <input
                    type="text"
                    name="icon"
                    value={formData.icon}
                    onChange={handleFieldChange}
                    placeholder="e.g., 🏠"
                    className="form-input"
                    disabled={addLoading}
                  />
                </div>

                <div className="form-group">
                  <label>Service Type *</label>
                  <select
                    name="type"
                    value={formData.type}
                    onChange={handleFieldChange}
                    className="form-input"
                    disabled={addLoading}
                  >
                    {serviceTypes.map(st => (
                      <option key={st.value} value={st.value}>{st.label}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Color</label>
                  <div className="color-selector">
                    {colorOptions.map(color => (
                      <div
                        key={color}
                        className={`color-option ${formData.color === color ? 'selected' : ''}`}
                        style={{ backgroundColor: color }}
                        onClick={() => setFormData(prev => ({ ...prev, color }))}
                      />
                    ))}
                  </div>
                </div>
              </div>

              <div className="modal-actions">
                <button type="submit" className="btn-confirm-add" disabled={addLoading}>
                  {addLoading ? '⏳ Creating...' : '✓ Create Service'}
                </button>
                <button type="button" className="btn-cancel-add" onClick={() => setShowAddModal(false)} disabled={addLoading}>
                  ✕ Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Edit Service Modal */}
      {showEditModal && (
        <div className="modal-overlay" onClick={() => setShowEditModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="modal-close" onClick={() => setShowEditModal(false)}>✕</button>
            <h3>✏️ Edit Service</h3>
            <form onSubmit={handleEditService}>
              <div className="form-group">
                <label>Service Name *</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleFieldChange}
                  placeholder="e.g., Housing Services"
                  className="form-input"
                  disabled={saveLoading}
                />
              </div>

              <div className="form-group">
                <label>Description *</label>
                <textarea
                  name="description"
                  value={formData.description}
                  onChange={handleFieldChange}
                  placeholder="e.g., Apply for housing assistance..."
                  className="form-input"
                  rows="3"
                  disabled={saveLoading}
                />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Icon/Emoji *</label>
                  <input
                    type="text"
                    name="icon"
                    value={formData.icon}
                    onChange={handleFieldChange}
                    placeholder="e.g., 🏠"
                    className="form-input"
                    disabled={saveLoading}
                  />
                </div>

                <div className="form-group">
                  <label>Service Type *</label>
                  <select
                    name="type"
                    value={formData.type}
                    onChange={handleFieldChange}
                    className="form-input"
                    disabled={saveLoading}
                  >
                    {serviceTypes.map(st => (
                      <option key={st.value} value={st.value}>{st.label}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Color</label>
                  <div className="color-selector">
                    {colorOptions.map(color => (
                      <div
                        key={color}
                        className={`color-option ${formData.color === color ? 'selected' : ''}`}
                        style={{ backgroundColor: color }}
                        onClick={() => setFormData(prev => ({ ...prev, color }))}
                      />
                    ))}
                  </div>
                </div>
              </div>

              <div className="modal-actions">
                <button type="submit" className="btn-confirm-edit" disabled={saveLoading}>
                  {saveLoading ? '⏳ Saving...' : '✓ Save Changes'}
                </button>
                <button type="button" className="btn-cancel-edit" onClick={() => setShowEditModal(false)} disabled={saveLoading}>
                  ✕ Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showConfirmDelete && (
        <div className="modal-overlay" onClick={() => setShowConfirmDelete(null)}>
          <div className="modal-content modal-confirm" onClick={(e) => e.stopPropagation()}>
            <h3>🗑️ Delete Service</h3>
            <p>Are you sure you want to delete this service? This action cannot be undone.</p>
            <div className="modal-actions">
              <button className="btn-confirm-delete" onClick={() => handleDeleteService(showConfirmDelete)} disabled={deleteLoading}>
                {deleteLoading ? '⏳ Deleting...' : '✓ Delete'}
              </button>
              <button className="btn-cancel-delete" onClick={() => setShowConfirmDelete(null)} disabled={deleteLoading}>
                ✕ Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ManageServices;
