import React, { useState, useEffect, useMemo } from "react";
import Sidebar from "../../components/Sidebar";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Stack,
  LinearProgress,
  TablePagination,
  Button,
  MenuItem,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  useMediaQuery,
  useTheme,
  Divider,
  Slide,
} from "@mui/material";
import { Search, Close, FileDownload, UploadFile, Edit, SwapHoriz, Save, Groups, People} from "@mui/icons-material";
import * as XLSX from "xlsx";
import { db, storage } from "../../firebase";
import {
  collection,
  addDoc,
  onSnapshot,
  query,
  orderBy,
  limit,
  serverTimestamp,
} from "firebase/firestore";
import { ref, uploadBytesResumable, getDownloadURL } from "firebase/storage";

// Debounce hook
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

const AdminFamilyTree = () => {


  const [headers, setHeaders] = useState([]);
  const [families, setFamilies] = useState([]);
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 300);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [barangayFilter, setBarangayFilter] = useState("");
  const [votingFilter, setVotingFilter] = useState("");
  const [politicalFilter, setPoliticalFilter] = useState("");
  const [selectedFamily, setSelectedFamily] = useState(null);
  const [editingMember, setEditingMember] = useState(null);
  const [serverTime, setServerTime] = useState(new Date());
  const [progress, setProgress] = useState(0);
  const [expandedFamilies, setExpandedFamilies] = useState({});
  // Confirmation Dialog State
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmAction, setConfirmAction] = useState(null);
  const [confirmMessage, setConfirmMessage] = useState("");

  const theme = useTheme();
  const isSmallScreen = useMediaQuery(theme.breakpoints.down("sm"));

  const toggleFamily = (headName) => {
  setExpandedFamilies(prev => ({
    ...prev,
    [headName]: !prev[headName],
  }));
};


  useEffect(() => {
  const defaultExpanded = {};
  families.forEach(f => {
    const headName = f.head[headers[0]];
    if (headName) defaultExpanded[headName] = true;
  });
  setExpandedFamilies(defaultExpanded);
}, [families, headers]);

  // ✅ UPDATE: Update server time every second
  useEffect(() => {
    const timer = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Load latest uploaded Family Summary file
  useEffect(() => {
    const q = query(
      collection(db, "importFamilyExcel"),
      orderBy("uploadedAt", "desc"),
      limit(1)
    );

    const unsubscribe = onSnapshot(q, async (snapshot) => {
      if (!snapshot.empty) {
        const fileData = snapshot.docs[0].data();
        try {
          await loadExcelFromFirebase(fileData.fileName, fileData.fileURL);
        } catch (err) {
          console.error("⚠️ Failed to load Excel from Firebase:", err);
        }
      }
    });

    return () => unsubscribe();
  }, []);

  // Upload Excel
  const handleImportExcel = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const fileName = `${Date.now()}_${file.name}`;
    const fileRef = ref(storage, `familyUploads/${fileName}`);
    const uploadTask = uploadBytesResumable(fileRef, file);

    setLoading(true);
    uploadTask.on(
      "state_changed",
      (snapshot) => {
        // Calculate upload progress in %
        const percent = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
        setProgress(percent);
      },
      (error) => {
        console.error("❌ Upload failed:", error);
        setLoading(false);
        setProgress(0);
      },
      async () => {
        const fileURL = await getDownloadURL(uploadTask.snapshot.ref);
        await addDoc(collection(db, "importFamilyExcel"), {
          fileName,
          fileURL,
          uploadedAt: serverTimestamp(),
          totalFamilies: 0,
          totalRows: 0,
        });
        alert("✅ Excel file successfully uploaded!");
        setLoading(false);
        setProgress(0);
      }
    );
  };

  // Load Excel from Firebase
  const loadExcelFromFirebase = async (fileName, fileURL) => {
  setLoading(true);
  try {
    let downloadURL = fileURL;
    if (!fileURL?.startsWith("https")) {
      const fileRef = ref(storage, `familyUploads/${fileName}`);
      downloadURL = await getDownloadURL(fileRef);
    }

    const response = await fetch(downloadURL);
    if (!response.ok) throw new Error(`Failed to fetch file: ${response.status}`);

    const arrayBuffer = await response.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: "array" });

    // ✅ Combine all sheets
    const allData = [];
    workbook.SheetNames.forEach((sheetName) => {
      const ws = workbook.Sheets[sheetName];
      const jsonData = XLSX.utils.sheet_to_json(ws, { defval: "" });
      allData.push(...jsonData);
    });

    if (allData.length === 0) {
      setFamilies([]);
      setHeaders([]);
      setLoading(false);
      return;
    }

    // ✅ Get headers from first row
    const headers = Object.keys(allData[0]).filter(
      (h) => h && !h.toLowerCase().includes("empty")
    );
    setHeaders(headers);

    const familyHeadCol = headers.find((h) => h.toLowerCase().includes("head"));
    const memberCol = headers.find((h) => h.toLowerCase().includes("member"));

    if (!familyHeadCol || !memberCol) {
      throw new Error("❌ Missing 'Family Heads' or 'Family Members' column in Excel file.");
    }

    // ✅ Group rows into families
    const grouped = [];
    let currentFamily = null;

    allData.forEach((row) => {
      let head = (row[familyHeadCol] || "").trim();
      let member = (row[memberCol] || "").trim();

      member = member.replace(/^\d+\.\s*/, ""); // remove numbering

      if ((head && head !== "") || (head === "-" && member)) {
        if (currentFamily) grouped.push(currentFamily);
        currentFamily = { head: row, members: [] };
      } else if (member && member !== "-" && currentFamily) {
        currentFamily.members.push({ ...row, [memberCol]: member });
      }
    });

    if (currentFamily) grouped.push(currentFamily);
    setFamilies(grouped);
  } catch (err) {
    console.error("❌ Error loading Excel:", err);
    setFamilies([]);
  } finally {
    setLoading(false);
  }
};

  // Filters & search
  const filteredFamilies = useMemo(() => {
    return families.filter((f) => {
      const term = debouncedSearch.toLowerCase();
      const inSearch =
        f.head[headers[0]]?.toLowerCase().includes(term) ||
        f.members.some((m) => JSON.stringify(m).toLowerCase().includes(term));

      const inBarangay = !barangayFilter || f.head["Voter Barangay"] === barangayFilter;
      const inVoting = !votingFilter || f.head["Voting Status"] === votingFilter;
      const inPolitical = !politicalFilter || f.head["Political Status"] === politicalFilter;

      return inSearch && inBarangay && inVoting && inPolitical;
    });
  }, [families, debouncedSearch, barangayFilter, votingFilter, politicalFilter, headers]);

  const paginatedFamilies = filteredFamilies.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  const handleChangePage = (_, newPage) => setPage(newPage);
  const handleChangeRowsPerPage = (e) => {
    setRowsPerPage(parseInt(e.target.value, 10));
    setPage(0);
  };

  // Open confirmation dialog
  const openConfirm = (message, action) => {
    setConfirmMessage(message);
    setConfirmAction(() => action);
    setConfirmOpen(true);
  };

  // Generate Family Heads Report
  const handleExportHeads = () =>
    openConfirm("Generate Family Heads Report?", () => {
      const wb = XLSX.utils.book_new();
      const headsData = filteredFamilies.map((f) => f.head);
      const wsHeads = XLSX.utils.json_to_sheet(headsData);
      XLSX.utils.book_append_sheet(wb, wsHeads, "Family Heads");
      XLSX.writeFile(wb, "Family_Heads_Report.xlsx");
    });

  // Generate Family Tree Report
  const handleExportTree = async () => {
  if (!families.length) return alert("No family data to export.");

  try {
    // ✅ Build flattened Excel rows
    const rows = [];

    families.forEach((fam) => {
      const headRow = {
        "Family Heads": fam.head?.["Family Heads"] || fam.head?.name || "",
        "Family Members": "-",
        "Voting Status": fam.head?.["Voting Status"] || "",
        "Voter Barangay": fam.head?.["Voter Barangay"] || "",
        "Political Status": fam.head?.["Political Status"] || "",
      };
      rows.push(headRow);

      (fam.members || []).forEach((mem) => {
        const memRow = {
          "Family Heads": "-",
          "Family Members": mem?.["Family Members"] || mem?.name || "",
          "Voting Status": mem?.["Voting Status"] || "",
          "Voter Barangay": mem?.["Voter Barangay"] || "",
          "Political Status": mem?.["Political Status"] || "",
        };
        rows.push(memRow);
      });
    });

    // ✅ Convert to worksheet
    const ws = XLSX.utils.json_to_sheet(rows);

    // ✅ Auto-adjust column widths
    const colWidths = Object.keys(rows[0] || {}).map((key) => ({
      wch: Math.max(key.length, ...rows.map((r) => (r[key] ? r[key].toString().length : 0))) + 2,
    }));
    ws["!cols"] = colWidths;

    // ✅ Create workbook and save file
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Family Tree");
    XLSX.writeFile(wb, "FamilyTree_NewFormat.xlsx");

    alert("✅ Family tree exported successfully!");
  } catch (err) {
    console.error("❌ Export error:", err);
    alert("Failed to export family tree.");
  }
};
    

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f0f2f5" }}>
      <Sidebar />

      <Box
  sx={{
    flexGrow: 1,
    p: 4,
    position: "relative",
    overflowX: "auto",
    width: { xs: "100%", md: "calc(100% - 260px)" },
  }}
>
  {/* Header with Server Time */}
 <Box
  sx={{
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    mb: 3,
  }}
>
  <Typography
    variant="h4"
    sx={{
      color: "#1f8ef1",
      fontWeight: 600,
      display: "flex",
      alignItems: "center",
      gap: 1,
    }}
  >
    <Groups fontSize="large" />
    Family Summary Management
  </Typography>

  {/* Server time as inline tag */}
  <Typography
    variant="subtitle2"
    sx={{
      bgcolor: "#8b8d8f33",
      color: "#14141480",
      fontWeight: 600,
      px: 1.5,
      py: 1,
      borderRadius: 1,
      fontSize: 20,
    }}
  >
    {serverTime.toLocaleString("en-US", {
      hour12: false,
      month: "short",
      day: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    })}
  </Typography>
</Box>

        <Stack direction={isSmallScreen ? "column" : "row"} spacing={2} mb={3}>
          <Button
            variant="contained"
            component="label"
            color="success"
            startIcon={<UploadFile />}
          >
            Import Family Summary
            <input type="file" accept=".xls,.xlsx" hidden onChange={handleImportExcel} />
          </Button>
          <Button
            variant="contained"
            color="secondary"
            startIcon={<FileDownload />}
            onClick={handleExportHeads}
          >
            Generate Report – Family Heads
          </Button>
          <Button
            variant="contained"
            color="primary"
            startIcon={<FileDownload />}
            onClick={handleExportTree}
          >
            Generate Report – Family Tree
          </Button>
        </Stack>

        <TextField
          fullWidth
          variant="outlined"
          size="small"
          placeholder="Search family head or member..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          InputProps={{ startAdornment: <Search sx={{ mr: 1, color: "gray" }} /> }}
          sx={{ mb: 2 }}
        />

        <Stack
          direction={isSmallScreen ? "column" : "row"}
          spacing={2}
          mb={2}
          flexWrap="wrap"
        >
          <TextField
            select
            label="Voter Barangay"
            size="small"
            value={barangayFilter}
            onChange={(e) => setBarangayFilter(e.target.value)}
            sx={{ width: 220 }}
          >
            <MenuItem value="">All</MenuItem>
            {[...new Set(families.map((f) => f.head["Voter Barangay"]))].map((b, i) => (
              <MenuItem key={i} value={b}>
                {b || "-"}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            select
            label="Voting Status"
            size="small"
            value={votingFilter}
            onChange={(e) => setVotingFilter(e.target.value)}
            sx={{ width: 220 }}
          >
            <MenuItem value="">All</MenuItem>
            {[...new Set(families.map((f) => f.head["Voting Status"]))].map((s, i) => (
              <MenuItem key={i} value={s}>
                {s || "-"}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            select
            label="Political Status"
            size="small"
            value={politicalFilter}
            onChange={(e) => setPoliticalFilter(e.target.value)}
            sx={{ width: 220 }}
          >
            <MenuItem value="">All</MenuItem>
            {[...new Set(families.map((f) => f.head["Political Status"]))].map((p, i) => (
              <MenuItem key={i} value={p}>
                {p || "-"}
              </MenuItem>
            ))}
          </TextField>
        </Stack>

       {loading && (
        <Box sx={{ position: "relative", mb: 2 }}>
          <LinearProgress variant="determinate" value={progress} sx={{ height: 10, borderRadius: 5 }} />
          <Typography
            variant="caption"
            sx={{
              position: "absolute",
              top: 0,
              left: "50%",
              transform: "translateX(-50%)",
              color: "#000",
              fontWeight: 600,
            }}
          >
            {progress}%
          </Typography>
        </Box>
      )}

        <Paper sx={{ bgcolor: "#fff", borderRadius: 2, boxShadow: "0 4px 20px rgba(31,142,241,0.1)" }}>
        <Box
    sx={{
      transition: "opacity 0.4s ease",
      opacity: loading ? 0.5 : 1,
    }}
  >
  <TableContainer
  sx={{
    maxHeight: 400,
    overflowY: "scroll",
    "&::-webkit-scrollbar": { width: 0, background: "transparent" },
    scrollbarWidth: "none",
    msOverflowStyle: "none",
  }}
>
  <Table stickyHeader>
    <TableHead>
      <TableRow>
        {headers.map((header, i) => (
          <TableCell
            key={i}
            sx={{
              color: "#fff",
              fontWeight: 600,
              backgroundColor: "#252424f5",
              position: "sticky",
              top: 0,
              zIndex: 1,
              fontSize: 12,
              py: 0.5,
              px: 1,
              whiteSpace: "nowrap",
            }}
          >
            {header}
          </TableCell>
        ))}
      </TableRow>
    </TableHead>

   <TableBody>
  {paginatedFamilies.length === 0 ? (
    <TableRow>
      <TableCell align="center" colSpan={headers.length}>
        No family data — import or check Excel file.
      </TableCell>
    </TableRow>
  ) : (
    paginatedFamilies.map((family, index) => {
      let headName = family.head?.[headers[0]]?.trim();
    if (!headName && family.members?.length > 0) headName = "-"; // allow "-" if there are members

      const isExpanded = expandedFamilies[headName];

      return (
        <React.Fragment key={index}>
          {/* Family Head Row */}
          <TableRow
            hover
            sx={{
              cursor: "pointer",
              backgroundColor: "#e8f0ff",
              "&:hover": { backgroundColor: "#d0e7ff" },
            }}
            onClick={() => toggleFamily(headName)}
          >
            <TableCell sx={{ fontWeight: 600, color: "#1f8ef1" }}>
              {isExpanded ? "▼ " : "► "} {headName}
            </TableCell>
            <TableCell>-</TableCell>
            <TableCell>{family.head["Voting Status"] || "-"}</TableCell>
            <TableCell>{family.head["Voter Barangay"] || "-"}</TableCell>
            <TableCell>{family.head["Political Status"] || "-"}</TableCell>
          </TableRow>

          {/* Family Members (only if expanded) */}
          {isExpanded &&
            family.members?.map((member, mIndex) => {
              const memberName = member?.[headers[1]]?.trim();
              if (!memberName) return null; // skip empty member rows

              return (
                <TableRow
                  key={`${index}-member-${mIndex}`}
                  sx={{ backgroundColor: "#f9f9f9" }}
                >
                  <TableCell>-</TableCell>
                  <TableCell>
    {memberName}
  </TableCell>
                  <TableCell>{member["Voting Status"] || "-"}</TableCell>
                  <TableCell>{member["Voter Barangay"] || "-"}</TableCell>
                  <TableCell>{member["Political Status"] || "-"}</TableCell>
                </TableRow>
              );
            })}
        </React.Fragment>
      );
    })
  )}
</TableBody>
  </Table>
</TableContainer>
  <TablePagination
    component="div"
    count={filteredFamilies.length}
    page={page}
    onPageChange={handleChangePage}
    rowsPerPage={rowsPerPage}
    onRowsPerPageChange={handleChangeRowsPerPage}
    rowsPerPageOptions={[5, 10, 20, 50, 100]}
  />
  </Box>
</Paper>

    
{/* Family Members Dialog */}
<Dialog
  open={Boolean(selectedFamily)}
  onClose={() => setSelectedFamily(null)}
  fullWidth
  maxWidth="lg"
  TransitionComponent={Slide}
  TransitionProps={{ direction: "up" }}
  sx={{ "& .MuiDialog-paper": { width: "98%", maxWidth: 1300 } }}
>
  <DialogTitle
    sx={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
    }}
  >
    <Typography
      variant="h6"
      sx={{ fontSize: 18, display: "flex", alignItems: "center", gap: 1 }}
    >
      <People fontSize="small" />
      Family Members of "{selectedFamily?.head?.["Family Heads"] || "-"}"
    </Typography>
    <IconButton onClick={() => setSelectedFamily(null)}>
      <Close />
    </IconButton>
  </DialogTitle>

  <DialogContent dividers sx={{ p: 2, overflowX: "auto" }}>
    {selectedFamily?.members?.length > 0 ? (
      <Table size="small" sx={{ minWidth: 800 }}>
        <TableHead>
          <TableRow>
            <TableCell
              sx={{
                fontWeight: "bold",
                color: "#fff",
                backgroundColor: "#252424f5",
                py: 1,
              }}
            >
              #
            </TableCell>
            <TableCell
              sx={{
                fontWeight: "bold",
                color: "#fff",
                backgroundColor: "#252424f5",
                py: 1,
              }}
            >
              Family Members
            </TableCell>
            <TableCell
              sx={{
                fontWeight: "bold",
                color: "#fff",
                backgroundColor: "#252424f5",
                py: 1,
              }}
            >
              Voting Status
            </TableCell>
            <TableCell
              sx={{
                fontWeight: "bold",
                color: "#fff",
                backgroundColor: "#252424f5",
                py: 1,
              }}
            >
              Voter Barangay
            </TableCell>
            <TableCell
              sx={{
                fontWeight: "bold",
                color: "#fff",
                backgroundColor: "#252424f5",
                py: 1,
              }}
            >
              Political Status
            </TableCell>
            <TableCell
              sx={{
                fontWeight: "bold",
                color: "#fff",
                backgroundColor: "#252424f5",
                py: 1,
              }}
            >
              Actions
            </TableCell>
          </TableRow>
        </TableHead>

        <TableBody>
          {selectedFamily.members.map((member, i) => (
            <TableRow key={i} hover sx={{ py: 0 }}>
              <TableCell sx={{ py: 0.5 }}>{i + 1}</TableCell>
              <TableCell sx={{ py: 0.5 }}>
                {member["Family Members"] || "-"}
              </TableCell>
              <TableCell sx={{ py: 0.5 }}>
                {member["Voting Status"] || "-"}
              </TableCell>
              <TableCell sx={{ py: 0.5 }}>
                {member["Voter Barangay"] || "-"}
              </TableCell>
              <TableCell sx={{ py: 0.5 }}>
                {member["Political Status"] || "-"}
              </TableCell>
              <TableCell
                sx={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  gap: 0.5,
                  py: 0.5,
                }}
              >
                <Button
                  size="small"
                  startIcon={<Edit fontSize="small" />}
                  variant="outlined"
                  fullWidth
                  onClick={() => {
                    openConfirm("Do you want to edit this details?", () => {
                      setEditingMember({ ...member, index: i });
                    });
                  }}
                >
                  Edit Details
                </Button>

                <Divider flexItem sx={{ my: 0.5 }} />

                <Button
                  size="small"
                  startIcon={<SwapHoriz fontSize="small" />}
                  variant="outlined"
                  color="secondary"
                  fullWidth
                  onClick={() =>
                    openConfirm(
                      `Transfer "${member["Family Members"]}" to another family?`,
                      () => {
                        alert(
                          `Member ${member["Family Members"]} transferred!`
                        );
                      }
                    )
                  }
                >
                  Transfer Family
                </Button>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    ) : (
      <Typography
        variant="body2"
        sx={{ textAlign: "center", py: 2, fontStyle: "italic", color: "#777" }}
      >
        No members found for this family.
      </Typography>
    )}
  </DialogContent>
</Dialog>

        {/* Edit Member Dialog */}
<Dialog
  open={Boolean(editingMember)}
  onClose={() => setEditingMember(null)}
  fullWidth
  maxWidth="sm"
>
  <DialogTitle sx={{ display: "flex", alignItems: "center", gap: 1 }}>
    <Edit fontSize="small" color="primary" />
    Edit Member Details
  </DialogTitle>

  <DialogContent dividers>
    {editingMember &&
      headers.map((header) => (
        <TextField
          key={header}
          label={header}
          value={editingMember[header] || ""}
          onChange={(e) =>
            setEditingMember((prev) => ({ ...prev, [header]: e.target.value }))
          }
          fullWidth
          sx={{ mb: 2 }}
        />
      ))}
  </DialogContent>

  <DialogActions sx={{ justifyContent: "space-between", px: 2, pb: 2 }}>
    <Button
      variant="outlined"
      startIcon={<Close />}
      color="secondary"
      onClick={() => setEditingMember(null)}
      sx={{ borderRadius: 2 }}
    >
      Cancel
    </Button>
    <Button
      variant="outlined"
      startIcon={<Save />}
      color="primary"
      onClick={() => {
        const updatedMembers = [...selectedFamily.members];
        updatedMembers[editingMember.index] = { ...editingMember };
        setSelectedFamily((prev) => ({
          ...prev,
          members: updatedMembers,
        }));
        setFamilies((prev) =>
          prev.map((f) =>
            f.head[headers[0]] === selectedFamily.head[headers[0]]
              ? { ...f, members: updatedMembers }
              : f
          )
        );
        setEditingMember(null);
      }}
      sx={{ borderRadius: 2 }}
    >
      Save
    </Button>
  </DialogActions>
</Dialog>

        {/* Confirmation Dialog */}
        <Dialog open={confirmOpen} onClose={() => setConfirmOpen(false)}>
          <DialogTitle>Confirm Action</DialogTitle>
          <DialogContent>
            <Typography>{confirmMessage}</Typography>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setConfirmOpen(false)} color="secondary">
              Cancel
            </Button>
            <Button
              onClick={() => {
                confirmAction?.();
                setConfirmOpen(false);
              }}
              color="primary"
            >
              Confirm
            </Button>
          </DialogActions>
        </Dialog>
      </Box>
    </Box>
  );
};

export default AdminFamilyTree;