// Service Type Form Templates
// Each service type has different form fields and structure

export const serviceFormTemplates = {
  medical: {
    name: 'Medical Services',
    steps: ['Patient Info', 'Medical History', 'Review'],
    fields: {
      step1: [
        { name: 'fullName', label: 'Full Name', type: 'text', required: true },
        { name: 'email', label: 'Email Address', type: 'email', required: true },
        { name: 'phone', label: 'Phone Number', type: 'tel', required: true },
        { name: 'dateOfBirth', label: 'Date of Birth', type: 'date', required: true },
        { name: 'address', label: 'Address', type: 'text', required: true }
      ],
      step2: [
        { name: 'bloodType', label: 'Blood Type', type: 'select', options: ['O+', 'O-', 'A+', 'A-', 'B+', 'B-', 'AB+', 'AB-'], required: true },
        { name: 'allergies', label: 'Allergies', type: 'textarea', required: false },
        { name: 'currentMedications', label: 'Current Medications', type: 'textarea', required: false },
        { name: 'medicalConditions', label: 'Medical Conditions', type: 'textarea', required: false },
        { name: 'symptoms', label: 'Symptoms or Concerns', type: 'textarea', required: true }
      ]
    }
  },
  medicine: {
    name: 'Medicine Assistant',
    steps: ['Your Info', 'Medicine Details', 'Review'],
    fields: {
      step1: [
        { name: 'fullName', label: 'Full Name', type: 'text', required: true }
      ],
      step2: [
        { name: 'prescriptionTable', label: 'Prescription Details', type: 'prescriptionTable', required: true }
      ]
    }
  }
};

export const getServiceTemplate = (serviceType) => {
  return serviceFormTemplates[serviceType] || serviceFormTemplates.medical;
};
