import React, { useState, useEffect, useMemo } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import FamilyProfileAddressSettings from "./components/FamilyProfileAddressSettings";
import FamilyProfileAddressTable from "./components/FamilyProfileAddressTable";
import {
  Box,
  Typography,
  Button,
} from "@mui/material";
import { FileDownload, Print } from "@mui/icons-material";
import { Refresh } from "@mui/icons-material";
import { db } from "../../firebase";
import { collection, getDocs, query, limit, startAfter, orderBy } from "firebase/firestore";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import * as XLSX from "xlsx";

const FamilyProfileAddress = () => {

  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [selectedColumns, setSelectedColumns] = useState({
    BARANGAY: true,
    PUROK: true,
    "FAMILY HEAD": true,
    "FAMILY MEMBER": true,
    TOTAL: true,
    "NON-VOTER FAMILY HEAD": true,
    "NON-VOTER FAMILY MEMBER": true,
    "GRAND TOTAL": true,
  });
  const [familyAddressData, setFamilyAddressData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [selectedBarangays, setSelectedBarangays] = useState([]);
  const [selectedPuroks, setSelectedPuroks] = useState([]);
  const [allBarangays, setAllBarangays] = useState([]);
  const [allPuroks, setAllPuroks] = useState([]);

  // Fetch family profile address data
  useEffect(() => {
    const fetchFamilyProfileAddressData = async () => {
      // Check if data exists in localStorage
      const cachedData = localStorage.getItem("familyProfileAddressData");
      if (cachedData) {
        try {
          const addressArray = JSON.parse(cachedData);
          setFamilyAddressData(addressArray);
          
          // Extract unique barangays and puroks
          const barangays = Array.from(new Set(addressArray.map(item => item.barangay))).sort();
          const puroks = Array.from(new Set(addressArray.map(item => item.purok))).sort();
          
          setAllBarangays(barangays);
          setSelectedBarangays(barangays);
          setAllPuroks(puroks);
          setSelectedPuroks(puroks);
          return; // Skip Firestore fetch if cache exists
        } catch (error) {
          console.error("Error parsing cached data:", error);
        }
      }

      // No cache or cache error - fetch from Firestore
      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const addressMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        const BATCH_SIZE = 10000;
        let batchCount = 0;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          batchCount += 1;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const barangay = voter.ProfiledBarangay || "Unknown Barangay";
            
            // Skip records with unknown barangay
            if (barangay === "Unknown Barangay") return;
            
            const purok = voter.ProfiledPurok || "Unknown Purok";
            const familyType = (voter.FamilyType || "").toUpperCase().trim();
            const votingStatus = (voter.VotingStatus || "").toUpperCase().trim();
            
            const key = `${barangay}|${purok}`;
            
            if (!addressMap.has(key)) {
              addressMap.set(key, {
                barangay: barangay,
                purok: purok,
                "FAMILY HEAD": 0,
                "FAMILY MEMBER": 0,
                TOTAL: 0,
                "NON-VOTER FAMILY HEAD": 0,
                "NON-VOTER FAMILY MEMBER": 0,
                "GRAND TOTAL": 0,
              });
            }
            
            const addressRecord = addressMap.get(key);
            
            // Count voters (VotingStatus = "VOTER")
            if (votingStatus === "VOTER") {
              if (familyType === "FAMILY HEAD") {
                addressRecord["FAMILY HEAD"] += 1;
                addressRecord.TOTAL += 1;
              } else if (familyType === "FAMILY MEMBER") {
                addressRecord["FAMILY MEMBER"] += 1;
                addressRecord.TOTAL += 1;
              }
            }
            
            // Count non-voters (VotingStatus = "NON-VOTER")
            if (votingStatus === "NON-VOTER") {
              if (familyType === "FAMILY HEAD") {
                addressRecord["NON-VOTER FAMILY HEAD"] += 1;
              } else if (familyType === "FAMILY MEMBER") {
                addressRecord["NON-VOTER FAMILY MEMBER"] += 1;
              }
            }
          });

          const fetchProgress = Math.min(80, batchCount * 10);
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        setLoadingProgress(85);

        const addressArray = Array.from(addressMap.values()).filter(record => record.barangay !== "Unknown Barangay").map(record => ({
          ...record,
          "GRAND TOTAL": record.TOTAL + record["NON-VOTER FAMILY HEAD"] + record["NON-VOTER FAMILY MEMBER"]
        })).sort((a, b) => {
          if (a.barangay !== b.barangay) return a.barangay.localeCompare(b.barangay);
          return a.purok.localeCompare(b.purok);
        });

        setLoadingProgress(95);

        setFamilyAddressData(addressArray);
        
        // Save to localStorage for future visits
        localStorage.setItem("familyProfileAddressData", JSON.stringify(addressArray));
        
        // Extract unique barangays and puroks
        const barangays = Array.from(new Set(addressArray.map(item => item.barangay))).sort();
        const puroks = Array.from(new Set(addressArray.map(item => item.purok))).sort();
        
        setAllBarangays(barangays);
        setSelectedBarangays(barangays);
        setAllPuroks(puroks);
        setSelectedPuroks(puroks);

        setLoadingProgress(100);
      } catch (error) {
        console.error("Error fetching family profile address data:", error);
        setFamilyAddressData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchFamilyProfileAddressData();
  }, []);

  const handleRefreshData = () => {
    const fetchFreshData = async () => {
      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const addressMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        const BATCH_SIZE = 10000;
        let batchCount = 0;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          batchCount += 1;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const barangay = voter.ProfiledBarangay || "Unknown Barangay";
            
            // Skip records with unknown barangay
            if (barangay === "Unknown Barangay") return;
            
            const purok = voter.ProfiledPurok || "Unknown Purok";
            const familyType = (voter.FamilyType || "").toUpperCase().trim();
            const votingStatus = (voter.VotingStatus || "").toUpperCase().trim();
            
            const key = `${barangay}|${purok}`;
            
            if (!addressMap.has(key)) {
              addressMap.set(key, {
                barangay: barangay,
                purok: purok,
                "FAMILY HEAD": 0,
                "FAMILY MEMBER": 0,
                TOTAL: 0,
                "NON-VOTER FAMILY HEAD": 0,
                "NON-VOTER FAMILY MEMBER": 0,
                "GRAND TOTAL": 0,
              });
            }
            
            const addressRecord = addressMap.get(key);
            
            // Count voters (VotingStatus = "VOTER")
            if (votingStatus === "VOTER") {
              if (familyType === "FAMILY HEAD") {
                addressRecord["FAMILY HEAD"] += 1;
                addressRecord.TOTAL += 1;
              } else if (familyType === "FAMILY MEMBER") {
                addressRecord["FAMILY MEMBER"] += 1;
                addressRecord.TOTAL += 1;
              }
            }
            
            // Count non-voters (VotingStatus = "NON-VOTER")
            if (votingStatus === "NON-VOTER") {
              if (familyType === "FAMILY HEAD") {
                addressRecord["NON-VOTER FAMILY HEAD"] += 1;
              } else if (familyType === "FAMILY MEMBER") {
                addressRecord["NON-VOTER FAMILY MEMBER"] += 1;
              }
            }
          });

          const fetchProgress = Math.min(80, batchCount * 10);
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        setLoadingProgress(85);

        const addressArray = Array.from(addressMap.values()).filter(record => record.barangay !== "Unknown Barangay").map(record => ({
          ...record,
          "GRAND TOTAL": record.TOTAL + record["NON-VOTER FAMILY HEAD"] + record["NON-VOTER FAMILY MEMBER"]
        })).sort((a, b) => {
          if (a.barangay !== b.barangay) return a.barangay.localeCompare(b.barangay);
          return a.purok.localeCompare(b.purok);
        });

        setLoadingProgress(95);

        setFamilyAddressData(addressArray);
        
        // Save to localStorage for future visits
        localStorage.setItem("familyProfileAddressData", JSON.stringify(addressArray));

        setLoadingProgress(100);
      } catch (error) {
        console.error("Error fetching family profile address data:", error);
        setFamilyAddressData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchFreshData();
  };

  const handleColumnToggle = (column) => {
    setSelectedColumns((prev) => ({
      ...prev,
      [column]: !prev[column],
    }));
  };

  const handleBarangayChange = (value) => {
    if (value.includes("SELECT_ALL_BARANGAY")) {
      if (selectedBarangays.length === allBarangays.length) {
        setSelectedBarangays([]);
        setSelectedPuroks([]);
        setAllPuroks([]);
      } else {
        setSelectedBarangays(allBarangays);
        const puroks = Array.from(new Set(familyAddressData.map(item => item.purok))).sort();
        setAllPuroks(puroks);
        setSelectedPuroks(puroks);
      }
    } else {
      setSelectedBarangays(value);
      // Update puroks based on selected barangays
      if (value.length === 0) {
        setSelectedPuroks([]);
        setAllPuroks([]);
      } else {
        const puroks = Array.from(new Set(
          familyAddressData.filter(item => value.includes(item.barangay)).map(item => item.purok)
        )).sort();
        setAllPuroks(puroks);
        // Don't auto-select puroks - let user choose
        setSelectedPuroks([]);
      }
    }
  };

  const handlePurokChange = (value) => {
    if (value.includes("SELECT_ALL_PUROK")) {
      if (selectedPuroks.length === allPuroks.length) {
        setSelectedPuroks([]);
      } else {
        setSelectedPuroks(allPuroks);
      }
    } else {
      setSelectedPuroks(value);
    }
  };

  // Filter table data - group by barangay OR show individual puroks based on selection
  const filteredTableData = useMemo(() => {
    if (selectedBarangays.length === 0) {
      return [];
    }
    
    // Check if specific barangays are selected (not all)
    const isSpecificBarangaysSelected = selectedBarangays.length > 0 && selectedBarangays.length < allBarangays.length;
    
    let filtered = familyAddressData.filter(row => {
      const barangayMatch = selectedBarangays.includes(row.barangay);
      // If specific barangays are selected with puroks, also check purok match
      if (isSpecificBarangaysSelected && selectedPuroks.length > 0) {
        return barangayMatch && selectedPuroks.includes(row.purok);
      }
      return barangayMatch;
    });

    // If specific barangays AND specific puroks are selected, show individual purok rows
    if (isSpecificBarangaysSelected && selectedPuroks.length > 0) {
      return filtered.map(record => ({
        ...record,
      })).sort((a, b) => {
        if (a.barangay !== b.barangay) return a.barangay.localeCompare(b.barangay);
        return a.purok.localeCompare(b.purok);
      });
    }

    // Otherwise, group by barangay (when all barangays selected or when waiting for purok selection)
    const barangayMap = new Map();
    
    filtered.forEach(row => {
      if (!barangayMap.has(row.barangay)) {
        barangayMap.set(row.barangay, {
          barangay: row.barangay,
          purok: "",
          "FAMILY HEAD": 0,
          "FAMILY MEMBER": 0,
          TOTAL: 0,
          "NON-VOTER FAMILY HEAD": 0,
          "NON-VOTER FAMILY MEMBER": 0,
          "GRAND TOTAL": 0,
        });
      }
      
      const barangayRecord = barangayMap.get(row.barangay);
      barangayRecord["FAMILY HEAD"] += row["FAMILY HEAD"] || 0;
      barangayRecord["FAMILY MEMBER"] += row["FAMILY MEMBER"] || 0;
      barangayRecord.TOTAL += row.TOTAL || 0;
      barangayRecord["NON-VOTER FAMILY HEAD"] += row["NON-VOTER FAMILY HEAD"] || 0;
      barangayRecord["NON-VOTER FAMILY MEMBER"] += row["NON-VOTER FAMILY MEMBER"] || 0;
      barangayRecord["GRAND TOTAL"] += row["GRAND TOTAL"] || 0;
    });
    
    return Array.from(barangayMap.values()).sort((a, b) => a.barangay.localeCompare(b.barangay));
  }, [familyAddressData, selectedBarangays, selectedPuroks, allBarangays]);

  const handleExportToExcel = () => {
    const exportData = filteredTableData.map(row => ({
      BARANGAY: row.barangay,
      PUROK: row.purok,
      ...(selectedColumns["FAMILY HEAD"] && { "FAMILY HEAD": row["FAMILY HEAD"] }),
      ...(selectedColumns["FAMILY MEMBER"] && { "FAMILY MEMBER": row["FAMILY MEMBER"] }),
      ...(selectedColumns.TOTAL && { TOTAL: row.TOTAL }),
      ...(selectedColumns["NON-VOTER FAMILY HEAD"] && { "NON-VOTER FAMILY HEAD": row["NON-VOTER FAMILY HEAD"] }),
      ...(selectedColumns["NON-VOTER FAMILY MEMBER"] && { "NON-VOTER FAMILY MEMBER": row["NON-VOTER FAMILY MEMBER"] }),
      ...(selectedColumns["GRAND TOTAL"] && { "GRAND TOTAL": row["GRAND TOTAL"] }),
    }));

    const totals = filteredTableData.reduce(
      (sum, row) => ({
        familyHead: sum.familyHead + (row["FAMILY HEAD"] || 0),
        familyMember: sum.familyMember + (row["FAMILY MEMBER"] || 0),
        total: sum.total + (row.TOTAL || 0),
        nonVoterFamilyHead: sum.nonVoterFamilyHead + (row["NON-VOTER FAMILY HEAD"] || 0),
        nonVoterFamilyMember: sum.nonVoterFamilyMember + (row["NON-VOTER FAMILY MEMBER"] || 0),
        grandTotal: sum.grandTotal + (row["GRAND TOTAL"] || 0),
      }),
      { familyHead: 0, familyMember: 0, total: 0, nonVoterFamilyHead: 0, nonVoterFamilyMember: 0, grandTotal: 0 }
    );

    exportData.push({
      BARANGAY: "TOTAL",
      PUROK: "",
      ...(selectedColumns["FAMILY HEAD"] && { "FAMILY HEAD": totals.familyHead }),
      ...(selectedColumns["FAMILY MEMBER"] && { "FAMILY MEMBER": totals.familyMember }),
      ...(selectedColumns.TOTAL && { TOTAL: totals.total }),
      ...(selectedColumns["NON-VOTER FAMILY HEAD"] && { "NON-VOTER FAMILY HEAD": totals.nonVoterFamilyHead }),
      ...(selectedColumns["NON-VOTER FAMILY MEMBER"] && { "NON-VOTER FAMILY MEMBER": totals.nonVoterFamilyMember }),
      ...(selectedColumns["GRAND TOTAL"] && { "GRAND TOTAL": totals.grandTotal }),
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Family Profile Address");
    XLSX.writeFile(wb, "Family_Profile_Address_Report.xlsx");
  };

  const handlePrintReport = () => {
    const doc = new jsPDF();
    const tableData = filteredTableData.map((item) => {
      const row = [item.barangay, item.purok];
      if (selectedColumns["FAMILY HEAD"]) row.push(item["FAMILY HEAD"] || 0);
      if (selectedColumns["FAMILY MEMBER"]) row.push(item["FAMILY MEMBER"] || 0);
      if (selectedColumns.TOTAL) row.push(item.TOTAL || 0);
      if (selectedColumns["NON-VOTER FAMILY HEAD"]) row.push(item["NON-VOTER FAMILY HEAD"] || 0);
      if (selectedColumns["NON-VOTER FAMILY MEMBER"]) row.push(item["NON-VOTER FAMILY MEMBER"] || 0);
      if (selectedColumns["GRAND TOTAL"]) row.push(item["GRAND TOTAL"] || 0);
      return row;
    });

    const columns = [
      "BARANGAY",
      "PUROK",
      ...(selectedColumns["FAMILY HEAD"] ? ["FAMILY HEAD"] : []),
      ...(selectedColumns["FAMILY MEMBER"] ? ["FAMILY MEMBER"] : []),
      ...(selectedColumns.TOTAL ? ["TOTAL"] : []),
      ...(selectedColumns["NON-VOTER FAMILY HEAD"] ? ["NON-VOTER FAMILY HEAD"] : []),
      ...(selectedColumns["NON-VOTER FAMILY MEMBER"] ? ["NON-VOTER FAMILY MEMBER"] : []),
      ...(selectedColumns["GRAND TOTAL"] ? ["GRAND TOTAL"] : []),
    ];

    const totals = filteredTableData.reduce(
      (sum, row) => ({
        familyHead: sum.familyHead + (row["FAMILY HEAD"] || 0),
        familyMember: sum.familyMember + (row["FAMILY MEMBER"] || 0),
        total: sum.total + (row.TOTAL || 0),
        nonVoterFamilyHead: sum.nonVoterFamilyHead + (row["NON-VOTER FAMILY HEAD"] || 0),
        nonVoterFamilyMember: sum.nonVoterFamilyMember + (row["NON-VOTER FAMILY MEMBER"] || 0),
        grandTotal: sum.grandTotal + (row["GRAND TOTAL"] || 0),
      }),
      { familyHead: 0, familyMember: 0, total: 0, nonVoterFamilyHead: 0, nonVoterFamilyMember: 0, grandTotal: 0 }
    );

    const totalRow = ["TOTAL", ""];
    if (selectedColumns["FAMILY HEAD"]) totalRow.push(totals.familyHead);
    if (selectedColumns["FAMILY MEMBER"]) totalRow.push(totals.familyMember);
    if (selectedColumns.TOTAL) totalRow.push(totals.total);
    if (selectedColumns["NON-VOTER FAMILY HEAD"]) totalRow.push(totals.nonVoterFamilyHead);
    if (selectedColumns["NON-VOTER FAMILY MEMBER"]) totalRow.push(totals.nonVoterFamilyMember);
    if (selectedColumns["GRAND TOTAL"]) totalRow.push(totals.grandTotal);
    tableData.push(totalRow);

    doc.text("Family Profile Address Report", 14, 10);
    autoTable(doc, {
      head: [columns],
      body: tableData,
      startY: 20,
      theme: "grid",
      headStyles: { fillColor: [26, 35, 126], textColor: 255, fontStyle: "bold" },
    });

    doc.save("Family_Profile_Address_Report.pdf");
  };;

  return (
    <Box sx={{ display: "flex", height: "100vh", bgcolor: "#f5f5f5" }}>
      <Sidebar />
      <Box sx={{ flex: 1, display: "flex", flexDirection: "column" }}>
        <Topbar />
        <Box sx={{ flex: 1, overflow: "auto", p: 2 }}>
          <FamilyProfileAddressSettings
            advancedOpen={advancedOpen}
            setAdvancedOpen={setAdvancedOpen}
            selectedColumns={selectedColumns}
            handleColumnToggle={handleColumnToggle}
            allBarangays={allBarangays}
            selectedBarangays={selectedBarangays}
            handleBarangayChange={handleBarangayChange}
            allPuroks={allPuroks}
            selectedPuroks={selectedPuroks}
            handlePurokChange={handlePurokChange}
          />
          {/* Header with title and buttons */}
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 3 }}>
            <Box>
              <Typography variant="h5" sx={{ color: "#1a237e", fontWeight: 700 }}>
                Family Profile Address
              </Typography>
              <Typography variant="caption" sx={{ color: "#666", mt: 0.5, display: "block" }}>
                Family Heads Distribution by Barangay and Purok
              </Typography>
            </Box>
            <Box sx={{ display: "flex", gap: 1 }}>
              <Button
                startIcon={<Refresh />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={handleRefreshData}
              >
                Refresh Data
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={handleExportToExcel}
              >
                Export Excel
              </Button>
              <Button
                startIcon={<Print />}
                variant="contained"
                color="success"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={handlePrintReport}
              >
                Print Report
              </Button>
            </Box>
          </Box>

          {/* Table Component */}
          <FamilyProfileAddressTable 
            selectedColumns={selectedColumns}
            allTableData={filteredTableData}
            loading={loading}
            loadingProgress={loadingProgress}
            isSpecificBarangaySelected={selectedBarangays.length === allBarangays.length}
          />
        </Box>
      </Box>
    </Box>
  );
};

export default FamilyProfileAddress;
