import React, { useState, useEffect, useMemo } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import AdvancedSettings from "./components/AdvancedSettings";
import {
  Box,
  Typography,
  Button,
  CircularProgress,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import { FileDownload, Print } from "@mui/icons-material";
import { Refresh } from "@mui/icons-material";
import { db } from "../../firebase";
import { collection, getDocs, query, limit, startAfter, orderBy } from "firebase/firestore";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import * as XLSX from "xlsx";

const spinAnimation = `
  @keyframes spin {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }
`;

const FamilyVotersAddress = () => {

  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [selectedColumns, setSelectedColumns] = useState({
    BARANGAY: true,
    "FAMILY HEAD": true,
    "FAMILY MEMBER": true,
    "TOTAL": true,
  });
  const [allBarangays, setAllBarangays] = useState([]);
  const [selectedBarangays, setSelectedBarangays] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [tableData, setTableData] = useState([]);

  // Fetch barangays and table data in single pass
  useEffect(() => {
    const fetchAllData = async () => {
      // Check if data is cached
      const cachedData = localStorage.getItem("familyVotersAddressData");
      if (cachedData) {
        try {
          const data = JSON.parse(cachedData);
          setAllBarangays(data.barangays);
          setSelectedBarangays(data.barangays);
          setTableData(data.tableData);
          return;
        } catch (err) {
          console.log("Cache parse error, refetching...");
          localStorage.removeItem("familyVotersAddressData");
        }
      }

      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const barangaysSet = new Set();
        const familyTypeDataMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        const BATCH_SIZE = 10000;
        let batchCount = 0;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          batchCount += 1;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const barangay = voter.VotersBarangay || "Unknown";
            const familyType = voter.FamilyType || "Unknown";
            const votingStatus = voter.VotingStatus || "Unknown";

            if (!barangay || barangay === "Unknown" || !familyType || familyType === "Unknown") {
              return;
            }

            barangaysSet.add(barangay);

            const key = `${barangay}_${familyType}_${votingStatus}`;

            if (!familyTypeDataMap.has(key)) {
              familyTypeDataMap.set(key, {
                barangay,
                familyType,
                votingStatus,
                count: 0,
              });
            }

            const record = familyTypeDataMap.get(key);
            record.count += 1;
          });

          // Show realistic progress: 0-70% for fetching
          const fetchProgress = Math.min(70, batchCount * 10);
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        setLoadingProgress(75);

        // Transform data to have BARANGAY, FAMILY HEAD, FAMILY MEMBER, NON-VOTER columns
        const barangayDataMap = new Map();
        familyTypeDataMap.forEach((item) => {
          const barangayKey = item.barangay;
          
          if (!barangayDataMap.has(barangayKey)) {
            barangayDataMap.set(barangayKey, {
              barangay: item.barangay,
              "FAMILY HEAD": 0,
              "FAMILY MEMBER": 0,
              "NON-VOTER FAMILY HEAD": 0,
              "NON-VOTER FAMILY MEMBER": 0,
              "TOTAL": 0,
            });
          }

          const record = barangayDataMap.get(barangayKey);
          if (item.familyType === "Family Head" && item.votingStatus !== "NON-VOTER") {
            record["FAMILY HEAD"] += item.count;
          } else if (item.familyType === "Family Member" && item.votingStatus !== "NON-VOTER") {
            record["FAMILY MEMBER"] += item.count;
          } else if (item.familyType === "Family Head" && item.votingStatus === "NON-VOTER") {
            record["NON-VOTER FAMILY HEAD"] += item.count;
          } else if (item.familyType === "Family Member" && item.votingStatus === "NON-VOTER") {
            record["NON-VOTER FAMILY MEMBER"] += item.count;
          }
        });

        // Calculate TOTAL (voters only) and other totals
        barangayDataMap.forEach((record) => {
          record["TOTAL"] = record["FAMILY HEAD"] + record["FAMILY MEMBER"];
        });

        setLoadingProgress(85);

        const aggregatedData = Array.from(barangayDataMap.values()).sort((a, b) =>
          a.barangay.localeCompare(b.barangay)
        );

        setLoadingProgress(90);

        const barangays = Array.from(barangaysSet).sort();
        setAllBarangays(barangays);
        setSelectedBarangays(barangays);
        setTableData(aggregatedData);

        // Cache the data
        localStorage.setItem(
          "familyVotersAddressData",
          JSON.stringify({
            barangays,
            tableData: aggregatedData,
            timestamp: Date.now(),
          })
        );

        setLoadingProgress(100);
      } catch (err) {
        console.error("Error fetching data:", err);
        setAllBarangays([]);
        setTableData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchAllData();
  }, []);

  const handleRefreshData = () => {
    // Clear cache and refetch data without reloading page
    localStorage.removeItem("familyVotersAddressData");
    
    const fetchFreshData = async () => {
      setLoading(true);
      setLoadingProgress(0);
      try {
        const votersCol = collection(db, "voters");
        const barangaysSet = new Set();
        const familyTypeDataMap = new Map();
        let lastDoc = null;
        let hasMore = true;
        const BATCH_SIZE = 10000;
        let batchCount = 0;

        while (hasMore) {
          let q;
          if (lastDoc) {
            q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
          } else {
            q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
          }

          const snapshot = await getDocs(q);
          if (snapshot.docs.length === 0) {
            hasMore = false;
            break;
          }

          lastDoc = snapshot.docs[snapshot.docs.length - 1];
          batchCount += 1;

          snapshot.docs.forEach((doc) => {
            const voter = doc.data();
            const barangay = voter.VotersBarangay || "Unknown";
            const familyType = voter.FamilyType || "Unknown";
            const votingStatus = voter.VotingStatus || "Unknown";

            if (!barangay || barangay === "Unknown" || !familyType || familyType === "Unknown") {
              return;
            }

            barangaysSet.add(barangay);

            const key = `${barangay}_${familyType}_${votingStatus}`;

            if (!familyTypeDataMap.has(key)) {
              familyTypeDataMap.set(key, {
                barangay,
                familyType,
                votingStatus,
                count: 0,
              });
            }

            const record = familyTypeDataMap.get(key);
            record.count += 1;
          });

          const fetchProgress = Math.min(70, batchCount * 10);
          setLoadingProgress(fetchProgress);

          if (snapshot.docs.length < BATCH_SIZE) {
            hasMore = false;
          }
        }

        setLoadingProgress(75);

        const barangayDataMap = new Map();
        familyTypeDataMap.forEach((item) => {
          const barangayKey = item.barangay;
          
          if (!barangayDataMap.has(barangayKey)) {
            barangayDataMap.set(barangayKey, {
              barangay: item.barangay,
              "FAMILY HEAD": 0,
              "FAMILY MEMBER": 0,
              "NON-VOTER FAMILY HEAD": 0,
              "NON-VOTER FAMILY MEMBER": 0,
              "TOTAL": 0,
            });
          }

          const record = barangayDataMap.get(barangayKey);
          if (item.familyType === "Family Head" && item.votingStatus !== "NON-VOTER") {
            record["FAMILY HEAD"] += item.count;
          } else if (item.familyType === "Family Member" && item.votingStatus !== "NON-VOTER") {
            record["FAMILY MEMBER"] += item.count;
          } else if (item.familyType === "Family Head" && item.votingStatus === "NON-VOTER") {
            record["NON-VOTER FAMILY HEAD"] += item.count;
          } else if (item.familyType === "Family Member" && item.votingStatus === "NON-VOTER") {
            record["NON-VOTER FAMILY MEMBER"] += item.count;
          }
        });

        barangayDataMap.forEach((record) => {
          record["TOTAL"] = record["FAMILY HEAD"] + record["FAMILY MEMBER"];
        });

        setLoadingProgress(85);

        const aggregatedData = Array.from(barangayDataMap.values()).sort((a, b) =>
          a.barangay.localeCompare(b.barangay)
        );

        setLoadingProgress(90);

        const barangays = Array.from(barangaysSet).sort();
        setAllBarangays(barangays);
        setSelectedBarangays(barangays);
        setTableData(aggregatedData);

        localStorage.setItem(
          "familyVotersAddressData",
          JSON.stringify({
            barangays,
            tableData: aggregatedData,
            timestamp: Date.now(),
          })
        );

        setLoadingProgress(100);
      } catch (err) {
        console.error("Error fetching data:", err);
        setAllBarangays([]);
        setTableData([]);
      } finally {
        setLoading(false);
        setLoadingProgress(0);
      }
    };

    fetchFreshData();
  };

  const handleBarangayChange = (value) => {
    if (value.includes("SELECT_ALL_BARANGAY")) {
      if (selectedBarangays.length === allBarangays.length) {
        setSelectedBarangays([]);
      } else {
        setSelectedBarangays(allBarangays);
      }
    } else {
      setSelectedBarangays(value);
    }
  };

  const handleColumnToggle = (column) => {
    setSelectedColumns((prev) => ({
      ...prev,
      [column]: !prev[column],
    }));
  };

  // Get filtered data based on selected barangays
  const filteredTableData = useMemo(() => {
    if (selectedBarangays.length === 0) {
      return tableData;
    }
    return tableData.filter(row => selectedBarangays.includes(row.barangay));
  }, [selectedBarangays, tableData]);

  // Export to PDF
  const exportToPDF = () => {
    const doc = new jsPDF();
    const tableData = filteredTableData.map(row => [
      row.barangay,
      selectedColumns["FAMILY HEAD"] ? row["FAMILY HEAD"].toLocaleString() : "",
      selectedColumns["FAMILY MEMBER"] ? row["FAMILY MEMBER"].toLocaleString() : "",
      selectedColumns["TOTAL"] ? (row["FAMILY HEAD"] + row["FAMILY MEMBER"]).toLocaleString() : "",
    ]);

    const headers = ["BARANGAY"];
    if (selectedColumns["FAMILY HEAD"]) headers.push("FAMILY HEAD");
    if (selectedColumns["FAMILY MEMBER"]) headers.push("FAMILY MEMBER");
    if (selectedColumns["TOTAL"]) headers.push("TOTAL");

    const totals = filteredTableData.reduce(
      (sum, row) => ({
        familyHead: sum.familyHead + (row["FAMILY HEAD"] || 0),
        familyMember: sum.familyMember + (row["FAMILY MEMBER"] || 0),
        total: sum.total + (row["TOTAL"] || 0),
      }),
      { familyHead: 0, familyMember: 0, total: 0 }
    );

    tableData.push([
      "TOTAL",
      selectedColumns["FAMILY HEAD"] ? totals.familyHead.toLocaleString() : "",
      selectedColumns["FAMILY MEMBER"] ? totals.familyMember.toLocaleString() : "",
      selectedColumns["TOTAL"] ? (totals.familyHead + totals.familyMember).toLocaleString() : "",
    ]);

    doc.text("Family Voters Address Report", 14, 10);
    autoTable(doc, {
      head: [headers],
      body: tableData,
      startY: 20,
      theme: "grid",
      headStyles: { fillColor: [26, 35, 126], textColor: 255, fontStyle: "bold" },
    });

    doc.save("Family_Voters_Address_Report.pdf");
  };

  // Export to Excel
  const exportToExcel = () => {
    const exportData = filteredTableData.map(row => ({
      BARANGAY: row.barangay,
      ...(selectedColumns["FAMILY HEAD"] && { "FAMILY HEAD": row["FAMILY HEAD"] }),
      ...(selectedColumns["FAMILY MEMBER"] && { "FAMILY MEMBER": row["FAMILY MEMBER"] }),
      ...(selectedColumns["TOTAL"] && { "TOTAL": row["FAMILY HEAD"] + row["FAMILY MEMBER"] }),
    }));

    const totals = filteredTableData.reduce(
      (sum, row) => ({
        familyHead: sum.familyHead + (row["FAMILY HEAD"] || 0),
        familyMember: sum.familyMember + (row["FAMILY MEMBER"] || 0),
        total: sum.total + (row["TOTAL"] || 0),
      }),
      { familyHead: 0, familyMember: 0, total: 0 }
    );

    exportData.push({
      BARANGAY: "TOTAL",
      ...(selectedColumns["FAMILY HEAD"] && { "FAMILY HEAD": totals.familyHead }),
      ...(selectedColumns["FAMILY MEMBER"] && { "FAMILY MEMBER": totals.familyMember }),
      ...(selectedColumns["TOTAL"] && { "TOTAL": totals.familyHead + totals.familyMember }),
    });

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Family Voters Address");
    XLSX.writeFile(wb, "Family_Voters_Address_Report.xlsx");
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f5f7fa" }}>
      <Sidebar />
      <Box
        sx={{
          flexGrow: 1,
          width: { xs: "100%", md: "calc(100% - 260px)" },
          display: "flex",
          flexDirection: "column",
          minHeight: "100vh",
        }}
      >
        <Topbar />
        <Box sx={{ flexGrow: 1, p: 2, overflowX: "auto" }}>
          {/* Advanced Settings Component */}
          <AdvancedSettings
            advancedOpen={advancedOpen}
            setAdvancedOpen={setAdvancedOpen}
            selectedColumns={selectedColumns}
            handleColumnToggle={handleColumnToggle}
            allVotersAddresses={allBarangays}
            selectedVotersAddresses={selectedBarangays}
            handleVotersAddressChange={handleBarangayChange}
          />

          {/* Header with title and buttons */}
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
            <Box>
              <Typography variant="h5" sx={{ color: "#1a237e", fontWeight: 700 }}>
                Family Voters Address Report
              </Typography>
              <Typography variant="caption" sx={{ color: "#666", mt: 0.5, display: "block" }}>
                Family Distribution by Barangay
              </Typography>
            </Box>
            <Box sx={{ display: "flex", gap: 1 }}>
              <Button
                startIcon={<Refresh />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={handleRefreshData}
              >
                Refresh Data
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={exportToPDF}
              >
                Export PDF
              </Button>
              <Button
                startIcon={<FileDownload />}
                variant="outlined"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
                onClick={exportToExcel}
              >
                Export Excel
              </Button>
              <Button
                startIcon={<Print />}
                variant="contained"
                color="success"
                size="small"
                sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }}
              >
                Print Email
              </Button>
            </Box>
          </Box>

          {/* Table Component */}
          <TableContainer component={Paper} sx={{ borderRadius: 1.5, boxShadow: "0 2px 8px rgba(0,0,0,0.1)" }}>
            {loading ? (
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  minHeight: 400,
                  flexDirection: "column",
                  gap: 2,
                }}
              >
                <style>{spinAnimation}</style>
                <Box sx={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <CircularProgress
                    size={80}
                    sx={{
                      color: "#1f8ef1",
                      animation: "spin 1s linear infinite"
                    }}
                    variant="determinate"
                    value={loadingProgress}
                  />
                  <Typography
                    variant="h6"
                    sx={{
                      position: "absolute",
                      color: "#1f8ef1",
                      fontWeight: 700,
                      fontSize: 24
                    }}
                  >
                    {loadingProgress}%
                  </Typography>
                </Box>
                <Typography variant="caption" sx={{ color: "#1f8ef1", fontWeight: 600 }}>
                  Loading family voters data...
                </Typography>
              </Box>
            ) : (
              <Table size="small" stickyHeader>
                <TableHead>
                  <TableRow>
                    <TableCell sx={{ color: "#fff", fontWeight: 700, fontSize: 13, py: 2.5, px: 2, bgcolor: "#1a237e" }}>BARANGAY</TableCell>
                    {selectedColumns["FAMILY HEAD"] && (
                      <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 13, py: 2.5, px: 2, bgcolor: "#6366f1" }}>FAMILY HEAD</TableCell>
                    )}
                    {selectedColumns["FAMILY MEMBER"] && (
                      <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 13, py: 2.5, px: 2, bgcolor: "#10b981" }}>FAMILY MEMBER</TableCell>
                    )}
                    {selectedColumns["TOTAL"] && (
                      <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 13, py: 2.5, px: 2, bgcolor: "#8b5cf6" }}>TOTAL</TableCell>
                    )}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredTableData.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={6} align="center" sx={{ py: 4 }}>
                        <Typography variant="body2" sx={{ color: "#999" }}>
                          No family records found.
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ) : (
                    <>
                      {filteredTableData.map((row, idx) => (
                        <TableRow key={idx} hover sx={{ "&:nth-of-type(odd)": { bgcolor: "#fafafa" } }}>
                          <TableCell sx={{ fontSize: 12 }}>{row.barangay}</TableCell>
                          {selectedColumns["FAMILY HEAD"] && (
                            <TableCell align="center" sx={{ fontSize: 12 }}>{row["FAMILY HEAD"]?.toLocaleString() || 0}</TableCell>
                          )}
                          {selectedColumns["FAMILY MEMBER"] && (
                            <TableCell align="center" sx={{ fontSize: 12 }}>{row["FAMILY MEMBER"]?.toLocaleString() || 0}</TableCell>
                          )}
                          {selectedColumns["TOTAL"] && (
                            <TableCell align="center" sx={{ fontSize: 12, fontWeight: 600 }}>{row["TOTAL"]?.toLocaleString() || 0}</TableCell>
                          )}
                        </TableRow>
                      ))}
                      {/* Totals Row */}
                      {filteredTableData.length > 0 && (() => {
                        const totals = filteredTableData.reduce(
                          (sum, row) => ({
                            familyHead: sum.familyHead + (row["FAMILY HEAD"] || 0),
                            familyMember: sum.familyMember + (row["FAMILY MEMBER"] || 0),
                            total: sum.total + (row["TOTAL"] || 0),
                          }),
                          { familyHead: 0, familyMember: 0, total: 0 }
                        );

                        return (
                          <TableRow sx={{ bgcolor: "#e8eaf6" }}>
                            <TableCell sx={{ fontWeight: 700, color: "#1a237e" }}>TOTAL</TableCell>
                            {selectedColumns["FAMILY HEAD"] && (
                              <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.familyHead.toLocaleString()}</TableCell>
                            )}
                            {selectedColumns["FAMILY MEMBER"] && (
                              <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.familyMember.toLocaleString()}</TableCell>
                            )}
                            {selectedColumns["TOTAL"] && (
                              <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{(totals.familyHead + totals.familyMember).toLocaleString()}</TableCell>
                            )}
                          </TableRow>
                        );
                      })()}
                    </>
                  )}
                </TableBody>
              </Table>
            )}
          </TableContainer>
        </Box>
      </Box>
    </Box>
  );
};

export default FamilyVotersAddress;
