import React from 'react';
import { useNavigate } from 'react-router-dom';
import './Mainpage_Topbar.css';
import logo from '../../assets/aksyonagadlogo.png';

const Topbar = () => {
  const navigate = useNavigate();
  const handleLogoClick = (e) => {
    e.preventDefault();
    navigate('/');
  };



  return (
    <>
      <nav className="topbar">
        <div className="topbar-container">
          <div className="topbar-logo">
            <a href="/" onClick={handleLogoClick} className="topbar-logo-link">
              <img src={logo} alt="AKSYONAGAD logo" className="topbar-logo-img" />
            </a>
          </div>
        </div>
      </nav>
    </>
  );
};

export default Topbar;
