// src/pages/admin/AdminPcvlMgt.jsx
import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Grid,
  Paper,
  Button,
  LinearProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  TablePagination,
} from "@mui/material";
import Sidebar from "../../components/Sidebar";
import CloudUploadIcon from "@mui/icons-material/CloudUpload";
import DownloadIcon from "@mui/icons-material/Download";
import CompareArrowsIcon from "@mui/icons-material/CompareArrows";
import {
  getStorage,
  ref,
  uploadBytesResumable,
  getDownloadURL,
} from "firebase/storage";
import {
  collection,
  addDoc,
  serverTimestamp,
  onSnapshot,
  orderBy,
  query,
} from "firebase/firestore";
import { db } from "../../firebase";
import { getAuth } from "firebase/auth";
import * as XLSX from "xlsx";

const AdminPcvlMgt = () => {
  const [excelFile, setExcelFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadedFiles, setUploadedFiles] = useState([]);
  const [loadingFiles, setLoadingFiles] = useState(true);

  const [crossmatchFile, setCrossmatchFile] = useState(null);
  const [crossmatching, setCrossmatching] = useState(false);
  const [crossmatchProgress, setCrossmatchProgress] = useState(0);

  const [matchesOld, setMatchesOld] = useState([]);
  const [matchesNew, setMatchesNew] = useState([]);
  const [unmatchedOld, setUnmatchedOld] = useState([]);
  const [unmatchedNew, setUnmatchedNew] = useState([]);

  const [openMatchesDialog, setOpenMatchesDialog] = useState(false);
  const [openUnmatchedDialog, setOpenUnmatchedDialog] = useState(false);

  // Pagination
  const [matchPage, setMatchPage] = useState(0);
  const [matchRowsPerPage, setMatchRowsPerPage] = useState(10);
  const [unmatchPage, setUnmatchPage] = useState(0);
  const [unmatchRowsPerPage, setUnmatchRowsPerPage] = useState(10);

  const storage = getStorage();
  const auth = getAuth();

  // ---------------- Upload Excel ----------------
  const handleFileChange = (e) => {
    if (e.target.files.length > 0) setExcelFile(e.target.files[0]);
  };

  const handleImportExcel = async () => {
    const user = auth.currentUser;
    if (!user) return alert("You must be logged in to upload.");
    if (!excelFile) return alert("Please select an Excel file first!");

    setUploading(true);
    setUploadProgress(0);

    try {
      const timestamp = Date.now();
      const safeFileName = excelFile.name.replace(/\s/g, "_");
      const storagePath = `pcvl-excel/${safeFileName}_${timestamp}.xlsx`;
      const storageRef = ref(storage, storagePath);

      const uploadTask = uploadBytesResumable(storageRef, excelFile);

      uploadTask.on(
        "state_changed",
        (snapshot) => {
          const percent = Math.round(
            (snapshot.bytesTransferred / snapshot.totalBytes) * 100
          );
          setUploadProgress(percent);
        },
        (error) => {
          console.error("Upload error:", error);
          alert("Failed to upload Excel file.");
          setUploading(false);
        },
        async () => {
          const downloadURL = await getDownloadURL(storageRef);
          await addDoc(collection(db, "importExcel"), {
            name: excelFile.name,
            storagePath,
            fileUrl: downloadURL,
            uploadedAt: serverTimestamp(),
          });

          // Parse Excel and batch upload to Firestore 'voters' collection
          try {
            const arrayBuffer = await excelFile.arrayBuffer();
            const workbook = XLSX.read(arrayBuffer, { type: "array" });
            const allData = [];
            workbook.SheetNames.forEach((sheetName) => {
              const ws = workbook.Sheets[sheetName];
              const jsonData = XLSX.utils.sheet_to_json(ws, { defval: "" });
              allData.push(...jsonData);
            });

            if (allData.length > 0) {
              // Batch upload to Firestore
              const votersCol = collection(db, "voters");
              // Firestore batch limit is 500, so chunk if needed
              const chunkSize = 400;
              for (let i = 0; i < allData.length; i += chunkSize) {
                const chunk = allData.slice(i, i + chunkSize);
                const batch = window.firebaseBatch ? window.firebaseBatch(db) : null;
                for (const row of chunk) {
                  // Use Voters Name + Address + Barangay as unique key if available
                  const voterKey = `${row["Voters Name"] || row["Voter's Name"] || ""}_${row["Address"] || row["Voter's Address"] || ""}_${row["Barangay"] || row["Voter's Barangay"] || ""}`.replace(/\s+/g, "_");
                  // Prevent duplicates: set doc with voterKey
                  if (batch) {
                    batch.set(collection(votersCol, voterKey), row);
                  } else {
                    // Fallback: addDoc (may create duplicates)
                    await addDoc(votersCol, row);
                  }
                }
                if (batch) await batch.commit();
              }
              alert(`Uploaded ${allData.length} voters to Firestore.`);
            }
          } catch (excelErr) {
            console.error("Excel parse/upload error:", excelErr);
            alert("Excel parsed, but failed to upload voters to Firestore.");
          }

          alert("Excel file uploaded successfully!");
          setExcelFile(null);
          setUploading(false);
        }
      );
    } catch (err) {
      console.error(err);
      alert("Unexpected error occurred.");
      setUploading(false);
    }
  };

  // ---------------- Load Uploaded Files ----------------
  useEffect(() => {
    const q = query(collection(db, "importExcel"), orderBy("uploadedAt", "desc"));
    const unsub = onSnapshot(q, (snapshot) => {
      const files = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
      setUploadedFiles(files);
      setLoadingFiles(false);
    });
    return () => unsub();
  }, []);

  // ---------------- Download ----------------
  const handleDownload = async (url, name) => {
    try {
      const res = await fetch(url);
      const blob = await res.blob();
      const link = document.createElement("a");
      link.href = window.URL.createObjectURL(blob);
      link.download = name;
      link.click();
    } catch (error) {
      console.error("Download failed:", error);
      alert("Failed to download file.");
    }
  };

  // ---------------- Export Unmatched as Excel ----------------
  const handleExportUnmatched = (data, filename) => {
    if (!data || data.length === 0) return alert("No data to export.");
    const ws = XLSX.utils.json_to_sheet(data);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Unmatched");
    XLSX.writeFile(wb, filename);
  };

  // ---------------- Crossmatch ----------------
  const handleCrossmatch = async (url) => {
    if (!crossmatchFile)
      return alert("Please select an Excel file to crossmatch!");
    setCrossmatching(true);
    setCrossmatchProgress(0);

    try {
      const cleanSheet = (data) => {
        let headerRow = data.find((row) =>
          Object.values(row).some((v) =>
            String(v).toLowerCase().includes("voter")
          )
        );

        if (headerRow) {
          const keys = Object.keys(data[0]);
          const map = {};
          keys.forEach((k, i) => {
            map[k] = Object.values(headerRow)[i] || k;
          });

          data = data
            .slice(data.indexOf(headerRow) + 1)
            .map((row) => {
              const cleaned = {};
              Object.entries(row).forEach(([k, v]) => {
                cleaned[map[k]] = v;
              });
              return cleaned;
            });
        }

        return data.filter(
          (r) =>
            r["Voter's Name"] &&
            !String(r["Voter's Name"]).toLowerCase().includes("no.")
        );
      };

      const normalize = (str) =>
        String(str || "")
          .trim()
          .toLowerCase()
          .replace(/[^a-z0-9]/g, "");

      const res = await fetch(url);
      const blob = await res.arrayBuffer();
      const wb1 = XLSX.read(blob, { type: "array" });
      const data1 = cleanSheet(
        XLSX.utils.sheet_to_json(wb1.Sheets[wb1.SheetNames[0]])
      );

      const reader = new FileReader();
      reader.onload = (e) => {
        const wb2 = XLSX.read(e.target.result, { type: "array" });
        const data2 = cleanSheet(
          XLSX.utils.sheet_to_json(wb2.Sheets[wb2.SheetNames[0]])
        );

        const mOld = [];
        const mNew = [];
        const uOld = [];
        const uNew = [];

        data2.forEach((row2, i) => {
          const name2 = normalize(row2["Voter's Name"]);
          const addr2 = normalize(row2["Voter's Address"]);
          const brgy2 = normalize(row2["Voter's Barangay"]);

          const match = data1.find((row1) => {
            const name1 = normalize(row1["Voter's Name"]);
            const addr1 = normalize(row1["Voter's Address"]);
            const brgy1 = normalize(row1["Voter's Barangay"]);
            return name1 === name2 && addr1 === addr2 && brgy1 === brgy2;
          });

          if (match) {
            mOld.push(match);
            mNew.push(row2);
          } else {
            uNew.push(row2);
          }

          setCrossmatchProgress(Math.round(((i + 1) / data2.length) * 100));
        });

        data1.forEach((row1) => {
          const name1 = normalize(row1["Voter's Name"]);
          const addr1 = normalize(row1["Voter's Address"]);
          const brgy1 = normalize(row1["Voter's Barangay"]);

          const found = data2.some((row2) => {
            const name2 = normalize(row2["Voter's Name"]);
            const addr2 = normalize(row2["Voter's Address"]);
            const brgy2 = normalize(row2["Voter's Barangay"]);
            return name1 === name2 && addr1 === addr2 && brgy1 === brgy2;
          });

          if (!found) uOld.push(row1);
        });

        setMatchesOld(mOld);
        setMatchesNew(mNew);
        setUnmatchedOld(uOld);
        setUnmatchedNew(uNew);
        setCrossmatching(false);

        alert(
          `✅ Crossmatch Complete!\nMatched: ${mNew.length}\nUnmatched (New): ${uNew.length}\nUnmatched (Old): ${uOld.length}`
        );
      };
      reader.readAsArrayBuffer(crossmatchFile);
    } catch (err) {
      console.error("Crossmatch Error:", err);
      alert("Crossmatch failed. Check the Excel format.");
      setCrossmatching(false);
    }
  };

  // ---------------- Pagination ----------------
  const handleMatchPageChange = (_, newPage) => setMatchPage(newPage);
  const handleMatchRowsChange = (e) => {
    setMatchRowsPerPage(parseInt(e.target.value, 10));
    setMatchPage(0);
  };
  const handleUnmatchPageChange = (_, newPage) => setUnmatchPage(newPage);
  const handleUnmatchRowsChange = (e) => {
    setUnmatchRowsPerPage(parseInt(e.target.value, 10));
    setUnmatchPage(0);
  };

  // ---------------- Render ----------------
  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f0f2f5" }}>
      <Sidebar />
      <Box sx={{ flexGrow: 1, p: { xs: 2, sm: 3, md: 4 } }}>
        <Typography variant="h4" sx={{ mb: 3, fontWeight: 600, color: "#1f8ef1" }}>
          PCVL Management
        </Typography>

        {/* Upload Excel */}
        <Grid container spacing={3}>
          <Grid item xs={12} sm={6} md={4}>
            <Paper
              elevation={3}
              sx={{
                p: 3,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                borderRadius: 2,
                boxShadow: "0 4px 20px rgba(31,142,241,0.15)",
              }}
            >
              <CloudUploadIcon sx={{ fontSize: 40, color: "#1f8ef1" }} />
              <Typography variant="h6" sx={{ mt: 1, fontWeight: 600, color: "#1f8ef1" }}>
                Import PCVL Excel
              </Typography>
              <input
                type="file"
                accept=".xlsx,.xls"
                onChange={handleFileChange}
                style={{ margin: "10px 0" }}
              />
              <Button
                variant="contained"
                color="primary"
                fullWidth
                onClick={handleImportExcel}
                disabled={uploading}
              >
                {uploading ? `Uploading... ${uploadProgress}%` : "Import Excel"}
              </Button>
              {uploading && (
                <Box sx={{ width: "100%", mt: 1 }}>
                  <LinearProgress variant="determinate" value={uploadProgress} />
                </Box>
              )}
            </Paper>
          </Grid>
        </Grid>

        {/* Uploaded Files */}
        <Box sx={{ mt: 5 }}>
          <Typography variant="h6" sx={{ mb: 2, fontWeight: 600, color: "#1f8ef1" }}>
            Uploaded PCVL Files
          </Typography>
          {loadingFiles ? (
            <Box sx={{ display: "flex", justifyContent: "center", py: 5 }}>
              <CircularProgress sx={{ color: "#1f8ef1" }} />
            </Box>
          ) : uploadedFiles.length === 0 ? (
            <Typography>No uploaded files found.</Typography>
          ) : (
            <TableContainer component={Paper} sx={{ borderRadius: 2 }}>
              <Table>
                <TableHead>
                  <TableRow sx={{ backgroundColor: "#1f8ef1" }}>
                    <TableCell sx={{ color: "#fff", fontWeight: 600 }}>File Name</TableCell>
                    <TableCell sx={{ color: "#fff", fontWeight: 600 }}>Uploaded At</TableCell>
                    <TableCell sx={{ color: "#fff", fontWeight: 600 }}>Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {uploadedFiles.map((file) => (
                    <TableRow key={file.id}>
                      <TableCell>{file.name}</TableCell>
                      <TableCell>
                        {file.uploadedAt?.toDate
                          ? new Date(file.uploadedAt.toDate()).toLocaleString()
                          : "Pending..."}
                      </TableCell>
                      <TableCell>
                        <Button
                          startIcon={<DownloadIcon />}
                          variant="outlined"
                          onClick={() => handleDownload(file.fileUrl, file.name)}
                          sx={{ mr: 1 }}
                        >
                          Download
                        </Button>
                        <input
                          type="file"
                          accept=".xlsx,.xls"
                          onChange={(e) => setCrossmatchFile(e.target.files[0])}
                          style={{ display: "none" }}
                          id={`crossmatch-${file.id}`}
                        />
                        <label htmlFor={`crossmatch-${file.id}`}>
                          <Button
                            variant="contained"
                            component="span"
                            startIcon={<CompareArrowsIcon />}
                            sx={{ mr: 1 }}
                          >
                            Import for Crossmatch
                          </Button>
                        </label>
                        <Button
                          variant="contained"
                          color="secondary"
                          onClick={() => handleCrossmatch(file.fileUrl)}
                          disabled={!crossmatchFile || crossmatching}
                        >
                          {crossmatching
                            ? `Crossmatching... ${crossmatchProgress}%`
                            : "Crossmatch"}
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          )}
        </Box>

        {/* Results */}
        {(matchesNew.length > 0 || unmatchedNew.length > 0) && (
          <Box sx={{ mt: 4 }}>
            <Typography sx={{ mb: 2 }}>
              ✅ Matches: {matchesNew.length} | ❌ Unmatched (New): {unmatchedNew.length} | ❌
              Unmatched (Old): {unmatchedOld.length}
            </Typography>
            <Button
              variant="contained"
              color="success"
              onClick={() => setOpenMatchesDialog(true)}
              sx={{ mr: 2 }}
            >
              View Matches
            </Button>
            <Button
              variant="contained"
              color="error"
              onClick={() => setOpenUnmatchedDialog(true)}
            >
              View Unmatched
            </Button>
          </Box>
        )}

        {/* Matches Dialog */}
        <Dialog open={openMatchesDialog} onClose={() => setOpenMatchesDialog(false)} fullWidth maxWidth="lg">
          <DialogTitle>Matched Records ({matchesNew.length})</DialogTitle>
          <DialogContent>
            <Typography variant="h6" sx={{ mt: 1 }}>
              🗂 Old File (PCVL)
            </Typography>
            <Table size="small" sx={{ mb: 3 }}>
              <TableHead>
                <TableRow>
                  {matchesOld.length > 0 &&
                    Object.keys(matchesOld[0]).map((header) => (
                      <TableCell key={header}>{header}</TableCell>
                    ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {matchesOld
                  .slice(matchPage * matchRowsPerPage, matchPage * matchRowsPerPage + matchRowsPerPage)
                  .map((row, i) => (
                    <TableRow key={i}>
                      {Object.values(row).map((cell, j) => (
                        <TableCell key={j}>{cell}</TableCell>
                      ))}
                    </TableRow>
                  ))}
              </TableBody>
            </Table>

            <Typography variant="h6" sx={{ mt: 2 }}>
              📄 New Imported File
            </Typography>
            <Table size="small">
              <TableHead>
                <TableRow>
                  {matchesNew.length > 0 &&
                    Object.keys(matchesNew[0]).map((header) => (
                      <TableCell key={header}>{header}</TableCell>
                    ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {matchesNew
                  .slice(matchPage * matchRowsPerPage, matchPage * matchRowsPerPage + matchRowsPerPage)
                  .map((row, i) => (
                    <TableRow key={i}>
                      {Object.values(row).map((cell, j) => (
                        <TableCell key={j}>{cell}</TableCell>
                      ))}
                    </TableRow>
                  ))}
              </TableBody>
            </Table>

            <TablePagination
              component="div"
              count={matchesNew.length}
              page={matchPage}
              onPageChange={handleMatchPageChange}
              rowsPerPage={matchRowsPerPage}
              onRowsPerPageChange={handleMatchRowsChange}
              rowsPerPageOptions={[5, 10, 25, 50]}
            />
          </DialogContent>
        </Dialog>

        {/* Unmatched Dialog */}
        <Dialog open={openUnmatchedDialog} onClose={() => setOpenUnmatchedDialog(false)} fullWidth maxWidth="lg">
          <DialogTitle>
            Unmatched Records

            <Box sx={{ mt: 2 }}>
              <Button
                variant="contained"
                color="warning"
                onClick={() => handleExportUnmatched(unmatchedOld, "Unmatched_Old.xlsx")}
                sx={{ mr: 2 }}
              >
                Export Unmatched (Old)
              </Button>
              <Button
                variant="contained"
                color="primary"
                onClick={() => handleExportUnmatched(unmatchedNew, "Unmatched_New.xlsx")}
              >
                Export Unmatched (New)
              </Button>
            </Box>
          </DialogTitle>
          <DialogContent>
            <Typography variant="h6" sx={{ mt: 2 }}>
              ❌ Unmatched - Old PCVL Records ({unmatchedOld.length})
            </Typography>
            <Table size="small" sx={{ mb: 3 }}>
              <TableHead>
                <TableRow>
                  {unmatchedOld.length > 0 &&
                    Object.keys(unmatchedOld[0]).map((header) => (
                      <TableCell key={header}>{header}</TableCell>
                    ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {unmatchedOld
                  .slice(
                    unmatchPage * unmatchRowsPerPage,
                    unmatchPage * unmatchRowsPerPage + unmatchRowsPerPage
                  )
                  .map((row, i) => (
                    <TableRow key={i}>
                      {Object.values(row).map((cell, j) => (
                        <TableCell key={j}>{cell}</TableCell>
                      ))}
                    </TableRow>
                  ))}
              </TableBody>
            </Table>

            <Typography variant="h6" sx={{ mt: 2 }}>
              ❌ Unmatched - New Imported Records ({unmatchedNew.length})
            </Typography>
            <Table size="small">
              <TableHead>
                <TableRow>
                  {unmatchedNew.length > 0 &&
                    Object.keys(unmatchedNew[0]).map((header) => (
                      <TableCell key={header}>{header}</TableCell>
                    ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {unmatchedNew
                  .slice(
                    unmatchPage * unmatchRowsPerPage,
                    unmatchPage * unmatchRowsPerPage + unmatchRowsPerPage
                  )
                  .map((row, i) => (
                    <TableRow key={i}>
                      {Object.values(row).map((cell, j) => (
                        <TableCell key={j}>{cell}</TableCell>
                      ))}
                    </TableRow>
                  ))}
              </TableBody>
            </Table>

            <TablePagination
              component="div"
              count={unmatchedNew.length}
              page={unmatchPage}
              onPageChange={handleUnmatchPageChange}
              rowsPerPage={unmatchRowsPerPage}
              onRowsPerPageChange={handleUnmatchRowsChange}
              rowsPerPageOptions={[5, 10, 25, 50]}
            />
          </DialogContent>
        </Dialog>
      </Box>
    </Box>
  );
};

export default AdminPcvlMgt;