import React, { useState, useEffect } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import VotersStatsCard from "./components/VotersStatsCard";
import VotersSearchBar from "./components/VotersSearchBar";
import VotersTable from "./components/VotersTable";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableRow,
  TextField,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Slide,
  Card,
  CardContent,
  Grid,
  Divider,
  Select,
  MenuItem,
  CircularProgress,
} from "@mui/material";
import { 
  Close, 
  Edit, 
  SwapHoriz, 
  Save, 
  PersonSearch,
  Info,
} from "@mui/icons-material";
import { db } from "../../firebase";
import {
  collection,
  query,
  orderBy,
  limit,
  getDocs,
  where,
  startAfter,
  getCountFromServer,
  doc,
  updateDoc,
} from "firebase/firestore";

// Debounce hook
function useDebounce(value, delay) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

const AdminVotersProfileMgt = () => {


  // Fixed professional headers for the voters table (matching Firestore field names)
  const headers = [
    "VotersName",
    "VotersAddress",
    "VotersBarangay",
    "ProfiledBarangay",
    "ProfiledPurok",
    "Precinct",
    "BirthDate",
    "PoliticalStatus",
    "FamilyType",
    "VotingStatus",
  ];
  
  // Display labels for headers
  const headerLabels = {
    "VotersName": "Voters Name",
    "VotersAddress": "Voters Address",
    "VotersBarangay": "Voters Barangay",
    "ProfiledBarangay": "Profile Barangay",
    "ProfiledPurok": "Profile Purok",
    "Precinct": "Precinct",
    "BirthDate": "Birth Date",
    "PoliticalStatus": "Political Status",
    "FamilyType": "Family Type",
    "VotingStatus": "Voting Status",
  };
  const [voters, setVoters] = useState([]);
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 150);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [page, setPage] = useState(0);
  const [pageCursors, setPageCursors] = useState([]); // Array of lastDoc for each page
  const [editingMember, setEditingMember] = useState(null);
  const [serverTime, setServerTime] = useState(new Date());
  const [selectedVoter, setSelectedVoter] = useState(null);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [confirmAction, setConfirmAction] = useState(null);
  const [confirmMessage, setConfirmMessage] = useState("");
  const [totalVoters, setTotalVoters] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSearchQuery, setLastSearchQuery] = useState(null); // Track search to avoid redundant count fetches (null triggers initial fetch)
  const [statusCounts, setStatusCounts] = useState({
    ADMIN: 0,
    OPPOSITION: 0,
    UNTAGGED: 0,
    "NO STATUS": 0,
  });


  // Update server time every second
  useEffect(() => {
    const timer = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Fetch status counts on component mount (once)
  useEffect(() => {
    const fetchStatusCounts = async () => {
      try {
        const votersCollection = collection(db, "voters");
        const statuses = ["ADMIN", "OPPOSITION", "UNTAGGED", "NO STATUS"];
        const counts = { ADMIN: 0, OPPOSITION: 0, UNTAGGED: 0, "NO STATUS": 0 };

        // Fetch counts for each status in parallel
        const countPromises = statuses.map((status) =>
          getCountFromServer(
            query(votersCollection, where("PoliticalStatus", "==", status))
          ).then((snapshot) => {
            counts[status] = snapshot.data().count;
          }).catch((err) => {
            console.error(`Error fetching ${status} count:`, err);
          })
        );

        await Promise.all(countPromises);

        setStatusCounts(counts);
      } catch (err) {
        console.error("Error fetching status counts:", err);
      }
    };

    fetchStatusCounts();
  }, []);

  // Update server time every second
  useEffect(() => {
    const timer = setInterval(() => setServerTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Load voters from Firestore with pagination and search (optimized)
  useEffect(() => {
    const fetchVoters = async () => {
      try {
        let votersQuery = collection(db, "voters");
        
        // Build query constraints - order matters in Firestore!
        let constraints = [];
        let countQuery = null;
        
        if (debouncedSearch && debouncedSearch.trim() !== "") {
          // Search query using correct field name - optimized for speed
          const searchTerm = debouncedSearch.trim();
          constraints = [
            where("VotersName", ">=", searchTerm),
            where("VotersName", "<", searchTerm + "\uf8ff"),
            orderBy("VotersName"),
            limit(rowsPerPage),
          ];
          countQuery = query(
            votersQuery,
            where("VotersName", ">=", searchTerm),
            where("VotersName", "<", searchTerm + "\uf8ff")
          );
        } else {
          // No search - just order by with limit
          constraints = [
            orderBy("VotersName"),
            limit(rowsPerPage),
          ];
          countQuery = query(votersQuery);
        }
        
        // Add startAfter for pagination (must come after orderBy)
        if (page > 0 && pageCursors.length > page - 1) {
          const prevPageCursor = pageCursors[page - 1];
          constraints.splice(constraints.length - 1, 0, startAfter(prevPageCursor));
        }
        
        const q = query(votersQuery, ...constraints);
        
        // Optimization: Fetch count and data in parallel, only fetch count when search changes
        const countPromise =
          debouncedSearch !== lastSearchQuery
            ? getCountFromServer(countQuery)
            : Promise.resolve(null);

        const [countSnapshot, snapshot] = await Promise.all([
          countPromise,
          getDocs(q),
        ]);

        // Update total count only if search changed
        if (countSnapshot) {
          setTotalVoters(countSnapshot.data().count);
          setLastSearchQuery(debouncedSearch);
        }
        
        // Fetch page data
        const data = snapshot.docs.map((doc) => doc.data());
        setVoters(data);
        
        // Update cursors array with the last document for navigation
        if (snapshot.docs.length > 0) {
          const newCursors = [...pageCursors];
          newCursors[page] = snapshot.docs[snapshot.docs.length - 1];
          setPageCursors(newCursors);
        }
      } catch (err) {
        console.error("Error loading voters from Firestore:", err);
        setVoters([]);
      }
    };
    fetchVoters();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debouncedSearch, rowsPerPage, page]);


  // Display voters as-is (already ordered by Firestore query)
  const paginatedVoters = voters;

  const handleChangePage = (_, newPage) => {
    setPage(newPage);
  };
  const handleChangeRowsPerPage = (e) => {
    setRowsPerPage(parseInt(e.target.value, 10));
    setPage(0);
    setPageCursors([]);
  };

  // Open confirmation dialog
  const openConfirm = (message, action) => {
    setConfirmMessage(message);
    setConfirmAction(() => action);
    setConfirmOpen(true);
  };

  // Save voter profile to Firestore
  const handleSaveVoterProfile = async () => {
    if (!editingMember || !editingMember.VotersName) {
      alert("Voter name is required");
      return;
    }

    setIsSaving(true);

    try {
      // Find the voter document by VotersName
      const votersRef = collection(db, "voters");
      const q = query(votersRef, where("VotersName", "==", editingMember.VotersName));
      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        alert("Voter record not found in database");
        setIsSaving(false);
        return;
      }

      // Update the first matching document
      const voterDocId = snapshot.docs[0].id;
      const voterDocRef = doc(db, "voters", voterDocId);

      // Prepare update data
      const updateData = {};
      headers.forEach((header) => {
        updateData[header] = editingMember[header] || "";
      });

      // Update Firestore document
      await updateDoc(voterDocRef, updateData);

      // Update local state
      setVoters((prev) =>
        prev.map((v) =>
          v["VotersName"] === editingMember["VotersName"]
            ? { ...editingMember }
            : v
        )
      );

      // Close dialog and show success message
      setEditingMember(null);
      setIsSaving(false);
      alert("Voter profile updated successfully!");
    } catch (error) {
      console.error("Error updating voter profile:", error);
      setIsSaving(false);
      alert(`Error updating voter profile: ${error.message}`);
    }
  };

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f5f7fa" }}>
      <Sidebar />
      <Box sx={{ flexGrow: 1, width: { xs: "100%", md: "calc(100% - 260px)" }, display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <Topbar />
        <Box sx={{ flexGrow: 1, p: 3, position: "relative", overflowX: "auto" }}>

          {/* Professional Header Card */}
          <Card sx={{ mb: 3, bgcolor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)" }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 2, flexWrap: "wrap" }}>
                <Box>
                  <Typography variant="h4" sx={{ color: "#1a237e", fontWeight: 700, mb: 1, display: "flex", alignItems: "center", gap: 1 }}>
                    <PersonSearch sx={{ fontSize: 32, color: "#1f8ef1" }} />
                    Voters Profile Management
                  </Typography>
                  <Typography variant="body2" sx={{ color: "#666", mb: 2 }}>
                    Comprehensive voter database management and profile administration
                  </Typography>
                </Box>
                <Box sx={{ textAlign: "right" }}>
                  <Typography variant="caption" sx={{ color: "#999", display: "block", mb: 1 }}>
                    Server Time
                  </Typography>
                  <Typography sx={{ bgcolor: "#f0f0f0", px: 2, py: 1, borderRadius: 1.5, fontSize: 12, fontWeight: 600, fontFamily: "monospace" }}>
                    {serverTime.toLocaleString("en-US", {
                      hour12: false,
                      month: "short",
                      day: "2-digit",
                      year: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                      second: "2-digit",
                    })}
                  </Typography>
                </Box>
              </Box>
              <Divider sx={{ my: 2 }} />
              <VotersStatsCard totalVoters={totalVoters} statusCounts={statusCounts} />
            </CardContent>
          </Card>

          {/* Search & Filter Section */}
          <VotersSearchBar 
            search={search} 
            setSearch={setSearch} 
            setPage={setPage} 
            setPageCursors={setPageCursors} 
          />

          {/* Voters Table Card */}
          <VotersTable
            headers={headers}
            headerLabels={headerLabels}
            paginatedVoters={paginatedVoters}
            setSelectedVoter={setSelectedVoter}
            page={page}
            rowsPerPage={rowsPerPage}
            handleChangePage={handleChangePage}
            handleChangeRowsPerPage={handleChangeRowsPerPage}
          />

{/* Voter Profile Dialog */}
<Dialog
  open={Boolean(selectedVoter)}
  onClose={() => setSelectedVoter(null)}
  fullWidth
  maxWidth="md"
  TransitionComponent={Slide}
  TransitionProps={{ direction: "up" }}
  sx={{ "& .MuiDialog-paper": { width: "95%", maxWidth: 900 } }}
>
  <DialogTitle
    sx={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      bgcolor: "#1a237e",
      color: "#fff",
      p: 2.5,
    }}
  >
    <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
      <PersonSearch sx={{ fontSize: 24 }} />
      <Typography variant="h6" sx={{ fontSize: 18, fontWeight: 600 }}>
        Voter Profile Details
      </Typography>
    </Box>
    <IconButton
      onClick={() => setSelectedVoter(null)}
      sx={{ color: "#fff", "&:hover": { bgcolor: "rgba(255,255,255,0.1)" } }}
    >
      <Close />
    </IconButton>
  </DialogTitle>

  <DialogContent dividers sx={{ p: 3, bgcolor: "#fafbfc" }}>
    {selectedVoter ? (
      <Box>
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6}>
            <Box sx={{ p: 2, bgcolor: "#fff", borderRadius: 1.5, border: "1px solid #e0e0e0" }}>
              <Typography variant="caption" sx={{ color: "#666", fontWeight: 600, display: "block", mb: 0.5 }}>
                Voter's Name
              </Typography>
              <Typography variant="body1" sx={{ fontWeight: 600, color: "#1a237e" }}>
                {selectedVoter["VotersName"] || "—"}
              </Typography>
            </Box>
          </Grid>
          <Grid item xs={12} sm={6}>
            <Box sx={{ p: 2, bgcolor: "#fff", borderRadius: 1.5, border: "1px solid #e0e0e0" }}>
              <Typography variant="caption" sx={{ color: "#666", fontWeight: 600, display: "block", mb: 0.5 }}>
                Barangay
              </Typography>
              <Typography variant="body1" sx={{ fontWeight: 600, color: "#1a237e" }}>
                {selectedVoter["VotersBarangay"] || "—"}
              </Typography>
            </Box>
          </Grid>
        </Grid>

        <Typography variant="subtitle2" sx={{ fontWeight: 700, color: "#1a237e", mb: 1.5 }}>
          Complete Information
        </Typography>
        <TableContainer component={Paper} sx={{ bgcolor: "#fff", border: "1px solid #e0e0e0" }}>
          <Table size="small">
            <TableBody>
              {headers.map((header) => (
                <TableRow key={header} sx={{ "&:last-child td": { borderBottom: 0 } }}>
                  <TableCell
                    sx={{
                      fontWeight: 600,
                      bgcolor: "#f5f7fa",
                      width: "35%",
                      color: "#1a237e",
                      fontSize: 13,
                      py: 1.5,
                    }}
                  >
                    {header}
                  </TableCell>
                  <TableCell
                    sx={{
                      color: "#333",
                      fontSize: 13,
                      py: 1.5,
                    }}
                  >
                    {selectedVoter[header] || "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Box>
    ) : (
      <Box sx={{ textAlign: "center", py: 4 }}>
        <Info sx={{ fontSize: 48, color: "#ccc", mb: 1 }} />
        <Typography variant="body2" sx={{ color: "#999" }}>
          No voter data available.
        </Typography>
      </Box>
    )}
  </DialogContent>

  <DialogActions sx={{ px: 3, py: 2, gap: 1, bgcolor: "#fafbfc" }}>
    <Button
      variant="outlined"
      startIcon={<Edit />}
      color="primary"
      onClick={() =>
        openConfirm(
          "Do you want to edit this voter's details?",
          () => setEditingMember({ ...selectedVoter })
        )
      }
      sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
    >
      Edit Profile
    </Button>
    <Button
      variant="outlined"
      startIcon={<SwapHoriz />}
      color="secondary"
      onClick={() =>
        openConfirm(
          `Transfer "${selectedVoter["Family Members"]}" to another family?`,
          () => {
            alert(`Voter ${selectedVoter["Family Members"]} transferred!`);
          }
        )
      }
      sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
    >
      Transfer Family
    </Button>

    <Button
      variant="contained"
      color="error"
      startIcon={<Close />}
      onClick={() => setSelectedVoter(null)}
      sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
    >
      Close
    </Button>
  </DialogActions>
</Dialog>
            {/* Edit Member Dialog */}
      <Dialog
        open={Boolean(editingMember)}
        onClose={() => !isSaving && setEditingMember(null)}
        fullWidth
        maxWidth="sm"
        PaperProps={{
          sx: {
            borderRadius: 2,
          },
        }}
      >
        <DialogTitle sx={{ bgcolor: "#1a237e", color: "#fff", p: 2.5, display: "flex", alignItems: "center", gap: 1.5 }}>
          <Edit fontSize="small" />
          Edit Voter Profile
        </DialogTitle>

        <DialogContent dividers sx={{ p: 3, bgcolor: "#fafbfc" }}>
          {editingMember && (
            <Box>
              {headers.map((header) => {
                // Render FamilyType as dropdown
                if (header === "FamilyType") {
                  return (
                    <Box key={header} sx={{ mb: 2 }}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600, display: "block", mb: 0.5 }}>
                        {header}
                      </Typography>
                      <Select
                        value={editingMember[header] || ""}
                        onChange={(e) =>
                          setEditingMember((prev) => ({ ...prev, [header]: e.target.value }))
                        }
                        fullWidth
                        size="small"
                        disabled={isSaving}
                        sx={{
                          borderRadius: 1.5,
                          "& .MuiOutlinedInput-root": {
                            "&:hover fieldset": {
                              borderColor: "#1f8ef1",
                            },
                          },
                        }}
                      >
                        <MenuItem value="Family Head">Family Head</MenuItem>
                        <MenuItem value="Family Member">Family Member</MenuItem>
                      </Select>
                    </Box>
                  );
                }

                // Render PoliticalStatus as dropdown
                if (header === "PoliticalStatus") {
                  return (
                    <Box key={header} sx={{ mb: 2 }}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600, display: "block", mb: 0.5 }}>
                        {header}
                      </Typography>
                      <Select
                        value={editingMember[header] || ""}
                        onChange={(e) =>
                          setEditingMember((prev) => ({ ...prev, [header]: e.target.value }))
                        }
                        fullWidth
                        size="small"
                        disabled={isSaving}
                        sx={{
                          borderRadius: 1.5,
                          "& .MuiOutlinedInput-root": {
                            "&:hover fieldset": {
                              borderColor: "#1f8ef1",
                            },
                          },
                        }}
                      >
                        <MenuItem value="ADMIN">ADMIN</MenuItem>
                        <MenuItem value="OPPOSITION">OPPOSITION</MenuItem>
                        <MenuItem value="NO STATUS">NO STATUS</MenuItem>
                        <MenuItem value="UNTAGGED">UNTAGGED</MenuItem>
                      </Select>
                    </Box>
                  );
                }

                // Render VotingStatus as dropdown (new field)
                if (header === "VotingStatus") {
                  return (
                    <Box key={header} sx={{ mb: 2 }}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600, display: "block", mb: 0.5 }}>
                        {header}
                      </Typography>
                      <Select
                        value={editingMember[header] || ""}
                        onChange={(e) =>
                          setEditingMember((prev) => ({ ...prev, [header]: e.target.value }))
                        }
                        fullWidth
                        size="small"
                        disabled={isSaving}
                        sx={{
                          borderRadius: 1.5,
                          "& .MuiOutlinedInput-root": {
                            "&:hover fieldset": {
                              borderColor: "#1f8ef1",
                            },
                          },
                        }}
                      >
                        <MenuItem value="VOTER">VOTER</MenuItem>
                        <MenuItem value="NON-VOTER">NON-VOTER</MenuItem>
                      </Select>
                    </Box>
                  );
                }

                // Render other fields as text inputs
                return (
                  <TextField
                    key={header}
                    label={header}
                    value={editingMember[header] || ""}
                    onChange={(e) =>
                      setEditingMember((prev) => ({ ...prev, [header]: e.target.value }))
                    }
                    fullWidth
                    size="small"
                    disabled={isSaving}
                    sx={{
                      mb: 2,
                      "& .MuiOutlinedInput-root": {
                        borderRadius: 1.5,
                        "&:hover fieldset": {
                          borderColor: "#1f8ef1",
                        },
                      },
                    }}
                  />
                );
              })}
            </Box>
          )}
        </DialogContent>

        <DialogActions sx={{ px: 3, py: 2, gap: 1, bgcolor: "#fafbfc" }}>
          <Button
            variant="outlined"
            startIcon={<Close />}
            color="secondary"
            onClick={() => setEditingMember(null)}
            disabled={isSaving}
            sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
          >
            Cancel
          </Button>
          <Button
            variant="contained"
            startIcon={isSaving ? <CircularProgress size={20} sx={{ mr: 1, color: "#fff" }} /> : <Save />}
            color="primary"
            onClick={handleSaveVoterProfile}
            disabled={isSaving}
            sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
          >
            {isSaving ? "Saving..." : "Save"}
          </Button>
        </DialogActions>
      </Dialog>

        {/* Confirmation Dialog */}
        <Dialog
          open={confirmOpen}
          onClose={() => setConfirmOpen(false)}
          PaperProps={{
            sx: {
              borderRadius: 2,
              maxWidth: 400,
            },
          }}
        >
          <DialogTitle sx={{ bgcolor: "#1a237e", color: "#fff", p: 2.5, fontWeight: 700 }}>
            Confirm Action
          </DialogTitle>
          <DialogContent sx={{ p: 3, bgcolor: "#fafbfc" }}>
            <Box sx={{ pt: 1 }}>
              <Typography sx={{ color: "#333", fontSize: 14, lineHeight: 1.6 }}>
                {confirmMessage}
              </Typography>
            </Box>
          </DialogContent>
          <DialogActions sx={{ px: 3, py: 2, gap: 1, bgcolor: "#fafbfc" }}>
            <Button
              onClick={() => setConfirmOpen(false)}
              color="secondary"
              variant="outlined"
              sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
            >
              Cancel
            </Button>
            <Button
              onClick={() => {
                confirmAction?.();
                setConfirmOpen(false);
              }}
              color="primary"
              variant="contained"
              sx={{ borderRadius: 1.5, textTransform: "none", fontWeight: 600 }}
            >
              Confirm
            </Button>
          </DialogActions>
        </Dialog>
        </Box>
      </Box>
    </Box>
  );
};

export default AdminVotersProfileMgt;