import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../../../firebase';
import { doc, getDoc } from 'firebase/firestore';
import Topbar from '../../components/Mainpage_Topbar';
import LoadingScreen from '../../../components/LoadingScreen';
import './TransactionDetail.css';

const TransactionDetail = ({ username = 'User' }) => {
  const { transactionId } = useParams();
  const navigate = useNavigate();
  const [transaction, setTransaction] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [internalNotes, setInternalNotes] = useState('');

  useEffect(() => {
    const fetchTransaction = async () => {
      try {
        setLoading(true);
        const docRef = doc(db, 'applications', transactionId);
        const docSnap = await getDoc(docRef);
        
        if (docSnap.exists()) {
          const data = { id: docSnap.id, ...docSnap.data() };
          setTransaction(data);
          setInternalNotes(data.internalNotes || '');
        } else {
          setError('Transaction not found');
        }
      } catch (err) {
        console.error('Error fetching transaction:', err);
        setError('Failed to load transaction details');
      } finally {
        setLoading(false);
      }
    };

    if (transactionId) {
      fetchTransaction();
    }
  }, [transactionId]);

  const handleSaveNotes = () => {
    // TODO: Save notes to Firestore
    alert('Notes saved!');
  };

  const handleApprove = () => {
    // TODO: Update status to approved in Firestore
    alert('Application approved!');
  };

  const handleReject = () => {
    // TODO: Update status to rejected in Firestore
    alert('Application rejected!');
  };

  const getStatusBgColor = (status) => {
    switch (status?.toLowerCase()) {
      case 'pending review':
      case 'pending':
        return '#fef3c7';
      case 'approved':
      case 'completed':
        return '#d1fae5';
      case 'rejected':
        return '#fee2e2';
      case 'in review':
        return '#e0e7ff';
      default:
        return '#f3f4f6';
    }
  };

  const getStatusTextColor = (status) => {
    switch (status?.toLowerCase()) {
      case 'pending review':
      case 'pending':
        return '#d97706';
      case 'approved':
      case 'completed':
        return '#059669';
      case 'rejected':
        return '#dc2626';
      case 'in review':
        return '#4338ca';
      default:
        return '#4b5563';
    }
  };

  if (loading) {
    return <LoadingScreen message="Loading transaction details..." />;
  }

  if (error || !transaction) {
    return (
      <>
        <Topbar activePage="services" username={username} hideNavLinks={true} />
        <div className="transaction-detail-container">
          <div className="error-state">
            <p className="error-message">❌ {error || 'Transaction not found'}</p>
            <button className="back-button" onClick={() => navigate('/services/transactions')}>← Back to Transactions</button>
          </div>
        </div>
      </>
    );
  }

  const step1 = transaction.step1 || {};
  const step2 = transaction.step2 || {};

  return (
    <>
      <Topbar activePage="services" username={username} hideNavLinks={true} />
      <div className="transaction-detail-container">
        {/* Breadcrumb Navigation */}
        <nav className="breadcrumb-nav">
          <a href="/services/dashboard" className="breadcrumb-link">Dashboard</a>
          <span className="breadcrumb-separator">›</span>
          <a href="/services/transactions" className="breadcrumb-link">Transactions</a>
          <span className="breadcrumb-separator">›</span>
          <span className="breadcrumb-current">{transaction.id}</span>
        </nav>

        {/* Header Section */}
        <div className="detail-header-card">
          <div className="header-left">
            <div className="header-icon">
              <span>📋</span>
            </div>
            <div className="header-info">
              <div className="header-title-row">
                <h1 className="transaction-id">{transaction.id}</h1>
                <span 
                  className="status-badge"
                  style={{
                    backgroundColor: getStatusBgColor(transaction.status),
                    color: getStatusTextColor(transaction.status)
                  }}
                >
                  {transaction.status?.toUpperCase() || 'PENDING'}
                </span>
              </div>
              <p className="header-timestamp">Submitted on {transaction.createdAt?.toDate?.().toLocaleDateString()} at {transaction.createdAt?.toDate?.().toLocaleTimeString()}</p>
            </div>
          </div>
          <div className="header-actions">
            <button className="action-btn print-btn">
              <span className="btn-icon">🖨️</span> Print
            </button>
            <button className="action-btn update-btn">
              <span className="btn-icon">✎</span> Update Status
            </button>
          </div>
        </div>

        {/* Main Content Grid */}
        <div className="detail-content-grid">
          {/* Left Column */}
          <div className="detail-left-column">
            {/* Citizen Information Section */}
            <section className="detail-section">
              <div className="section-header">
                <span className="section-icon">👤</span>
                <h2 className="section-title">Citizen Information</h2>
              </div>
              <div className="section-content">
                <div className="info-grid">
                  <div className="info-item full-width">
                    <label className="info-label">Full Name</label>
                    <p className="info-value">{step1.fullName || transaction.userName || 'N/A'}</p>
                  </div>
                  <div className="info-item">
                    <label className="info-label">Birth Date</label>
                    <p className="info-value">{step1.birthDate || 'N/A'}</p>
                  </div>
                  <div className="info-item">
                    <label className="info-label">Sex</label>
                    <p className="info-value">{step1.sex || 'N/A'}</p>
                  </div>
                  <div className="info-item">
                    <label className="info-label">Contact Number</label>
                    <p className="info-value">+63 912 345 6789</p>
                  </div>
                  <div className="info-item">
                    <label className="info-label">Email Address</label>
                    <p className="info-value">contact@example.com</p>
                  </div>
                  <div className="info-item full-width">
                    <label className="info-label">Address</label>
                    <p className="info-value">{step1.profiledBarangay || step1.barangay || 'N/A'}</p>
                  </div>
                </div>
              </div>
            </section>

            {/* Service Details Section */}
            <section className="detail-section">
              <div className="section-header">
                <span className="section-icon">⚕️</span>
                <h2 className="section-title">Service Details</h2>
              </div>
              <div className="section-content">
                <div className="service-details">
                  <div className="detail-row">
                    <div className="detail-col">
                      <label className="info-label">Service Type</label>
                      <p className="info-value">{transaction.serviceName || 'N/A'}</p>
                    </div>
                    <div className="detail-col">
                      <label className="info-label">Application Type</label>
                      <p className="info-value">{transaction.applicationType || 'N/A'}</p>
                    </div>
                  </div>

                  {transaction.serviceType === 'medicine' && step2.prescriptions && (
                    <div className="detail-full">
                      <label className="info-label">Requested Medicines</label>
                      <div className="medicines-list">
                        {step2.prescriptions.map((prescription, idx) => (
                          <div key={idx} className="medicine-item">
                            <span className="medicine-icon">✓</span>
                            <span className="medicine-text">
                              {prescription.name} {prescription.dosage ? `(${prescription.dosage})` : ''}
                            </span>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </section>
          </div>

          {/* Right Column */}
          <div className="detail-right-column">
            {/* Timeline Section */}
            <section className="detail-section">
              <div className="section-header">
                <span className="section-icon">📅</span>
                <h2 className="section-title">Timeline</h2>
              </div>
              <div className="section-content timeline-content">
                <div className="timeline">
                  <div className="timeline-item completed">
                    <div className="timeline-marker completed">
                      <span>✓</span>
                    </div>
                    <div className="timeline-body">
                      <h4 className="timeline-title">Submitted</h4>
                      <p className="timeline-date">{transaction.createdAt?.toDate?.().toLocaleDateString()} • {transaction.createdAt?.toDate?.().toLocaleTimeString()}</p>
                      <p className="timeline-description">Successfully lodged through the web portal.</p>
                    </div>
                  </div>

                  <div className="timeline-item active">
                    <div className="timeline-marker active">
                      <span>⟳</span>
                    </div>
                    <div className="timeline-body">
                      <h4 className="timeline-title">In Review</h4>
                      <p className="timeline-date">{transaction.createdAt?.toDate?.().toLocaleDateString()} • {transaction.createdAt?.toDate?.().toLocaleTimeString()}</p>
                      <p className="timeline-description">Assigned to Health Officer: Dr. Sarah Velasco.</p>
                    </div>
                  </div>

                  <div className="timeline-item pending">
                    <div className="timeline-marker pending">
                      <span>◯</span>
                    </div>
                    <div className="timeline-body">
                      <h4 className="timeline-title">Approved / Completed</h4>
                      <p className="timeline-date">Estimated: {new Date(Date.now() + 86400000).toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>
              </div>
            </section>

            {/* Actions Section */}
            <section className="detail-section">
              <div className="section-header">
                <span className="section-icon">⚡</span>
                <h2 className="section-title">Actions</h2>
              </div>
              <div className="section-content actions-content">
                <div className="notes-group">
                  <label className="info-label">Internal Notes</label>
                  <textarea
                    className="notes-textarea"
                    placeholder="Add a private note for other admins..."
                    value={internalNotes}
                    onChange={(e) => setInternalNotes(e.target.value)}
                  />
                </div>
                <button className="save-notes-btn" onClick={handleSaveNotes}>
                  <span className="btn-icon">💾</span> Save Notes
                </button>
                <div className="action-buttons">
                  <button className="action-approve-btn" onClick={handleApprove}>
                    <span className="btn-icon">✓</span> Approve
                  </button>
                  <button className="action-reject-btn" onClick={handleReject}>
                    <span className="btn-icon">✕</span> Reject
                  </button>
                </div>
              </div>
            </section>
          </div>
        </div>

        {/* Footer */}
        <footer className="transaction-footer">
          <p>© 2026 AKSYON AGAD Community Services Portal. All Rights Reserved.</p>
        </footer>
      </div>
    </>
  );
};

export default TransactionDetail;
