import React from "react";
import {
  Box,
  Typography,
  Card,
  Collapse,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Checkbox,
  Grid,
} from "@mui/material";
import { ExpandMore, ExpandLess } from "@mui/icons-material";

const AdvancedSettings = ({
  advancedOpen,
  setAdvancedOpen,
  selectedColumns,
  handleColumnToggle,
  allVotersAddresses = [],
  selectedVotersAddresses = [],
  handleVotersAddressChange,
}) => {
  const columnOptions = Object.keys(selectedColumns);
  const selectedColumnsList = columnOptions.filter(col => selectedColumns[col]);

  return (
    <Card 
      sx={{ 
        bgcolor: "#fff", 
        boxShadow: "0 2px 8px rgba(0,0,0,0.08)", 
        mb: 3,
        borderRadius: 1.5,
        border: "1px solid #e5e7eb"
      }}
    >
      <Box
        onClick={() => setAdvancedOpen(!advancedOpen)}
        sx={{
          p: 2.5,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          cursor: "pointer",
          "&:hover": { bgcolor: "#f8f9fa" },
          transition: "background-color 0.2s ease",
          borderBottom: advancedOpen ? "1px solid #e5e7eb" : "none"
        }}
      >
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, color: "#1a237e" }}>
            Advanced Settings
          </Typography>
          <Typography variant="caption" sx={{ color: "#666", display: "block", mt: 0.5 }}>
            Customize your view and filters
          </Typography>
        </Box>
        {advancedOpen ? (
          <ExpandLess sx={{ color: "#135bec", fontSize: 28 }} />
        ) : (
          <ExpandMore sx={{ color: "#135bec", fontSize: 28 }} />
        )}
      </Box>

      <Collapse in={advancedOpen}>
        <Box sx={{ p: 3, bgcolor: "#fafbfc" }}>
          <Grid container spacing={3}>
            {/* Select VotersBarangay Dropdown */}
            <Grid item xs={12} md={6}>
              <FormControl fullWidth size="small">
                <InputLabel sx={{ fontWeight: 600 }}>Select Voters Barangay</InputLabel>
                <Select
                  multiple
                  value={selectedVotersAddresses}
                  onChange={(e) => handleVotersAddressChange(e.target.value)}
                  label="Select Voters Barangay"
                  renderValue={(selected) =>
                    selected.length === 0
                      ? "All Voters Barangays"
                      : selected.length === allVotersAddresses.length
                      ? "All Voters Barangays"
                      : `${selected.length} barangay${selected.length !== 1 ? 'ies' : ''} selected`
                  }
                  sx={{
                    borderRadius: 1,
                    "& .MuiOutlinedInput-root": {
                      backgroundColor: "#fff",
                    },
                  }}
                >
                  <MenuItem 
                    value="SELECT_ALL_ADDRESS" 
                    sx={{ 
                      fontWeight: 700, 
                      color: "#135bec",
                      backgroundColor: selectedVotersAddresses.length === allVotersAddresses.length ? "#e8ecff" : "transparent",
                      "&:hover": {
                        backgroundColor: "#f0f4ff",
                      }
                    }}
                  >
                    <Checkbox
                      checked={selectedVotersAddresses.length === allVotersAddresses.length}
                      indeterminate={selectedVotersAddresses.length > 0 && selectedVotersAddresses.length < allVotersAddresses.length}
                      size="small"
                      sx={{ mr: 1 }}
                    />
                    <Typography sx={{ fontWeight: 700 }}>
                      {selectedVotersAddresses.length === allVotersAddresses.length ? "Deselect All" : "Select All"}
                    </Typography>
                  </MenuItem>
                  {allVotersAddresses.length === 0 ? (
                    <MenuItem disabled sx={{ fontWeight: 600, color: "#999" }}>
                      No voters addresses available
                    </MenuItem>
                  ) : (
                    allVotersAddresses.map((address) => (
                      <MenuItem key={address} value={address}>
                        <Checkbox
                          checked={selectedVotersAddresses.includes(address)}
                          size="small"
                          sx={{ mr: 1 }}
                        />
                        <Typography sx={{ fontWeight: 500 }}>{address}</Typography>
                      </MenuItem>
                    ))
                  )}
                </Select>
              </FormControl>
            </Grid>

            {/* Select Columns Dropdown */}
            <Grid item xs={12} md={6}>
              <FormControl fullWidth size="small">
                <InputLabel sx={{ fontWeight: 600 }}>Select Columns</InputLabel>
                <Select
                  multiple
                  value={selectedColumnsList}
                  onChange={(e) => {
                    const value = e.target.value;
                    
                    // Handle "Select All" option
                    if (value.includes("SELECT_ALL")) {
                      if (selectedColumnsList.length === columnOptions.length) {
                        // All selected, so deselect all
                        columnOptions.forEach(col => {
                          if (selectedColumns[col]) {
                            handleColumnToggle(col);
                          }
                        });
                      } else {
                        // Not all selected, so select all
                        columnOptions.forEach(col => {
                          if (!selectedColumns[col]) {
                            handleColumnToggle(col);
                          }
                        });
                      }
                    } else {
                      // Regular column selection
                      columnOptions.forEach(col => {
                        if (value.includes(col) && !selectedColumns[col]) {
                          handleColumnToggle(col);
                        } else if (!value.includes(col) && selectedColumns[col]) {
                          handleColumnToggle(col);
                        }
                      });
                    }
                  }}
                  label="Select Columns"
                  renderValue={(selected) =>
                    selected.length === columnOptions.length
                      ? "All Columns"
                      : selected.length === 0
                      ? "No Columns Selected"
                      : `${selected.length} column${selected.length !== 1 ? 's' : ''} selected`
                  }
                  sx={{
                    borderRadius: 1,
                    "& .MuiOutlinedInput-root": {
                      backgroundColor: "#fff",
                    },
                  }}
                >
                  <MenuItem 
                    value="SELECT_ALL" 
                    sx={{ 
                      fontWeight: 700, 
                      color: "#135bec",
                      backgroundColor: selectedColumnsList.length === columnOptions.length ? "#e8ecff" : "transparent",
                      "&:hover": {
                        backgroundColor: "#f0f4ff",
                      }
                    }}
                  >
                    <Checkbox
                      checked={selectedColumnsList.length === columnOptions.length}
                      indeterminate={selectedColumnsList.length > 0 && selectedColumnsList.length < columnOptions.length}
                      size="small"
                      sx={{ mr: 1 }}
                    />
                    <Typography sx={{ fontWeight: 700 }}>
                      {selectedColumnsList.length === columnOptions.length ? "Deselect All" : "Select All"}
                    </Typography>
                  </MenuItem>
                  {columnOptions.map((column) => (
                    <MenuItem key={column} value={column}>
                      <Checkbox
                        checked={selectedColumns[column]}
                        size="small"
                        sx={{ mr: 1 }}
                      />
                      <Typography sx={{ fontWeight: 500 }}>{column}</Typography>
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>

          {/* Summary Section */}
          <Box sx={{ mt: 3, pt: 3, borderTop: "1px solid #e5e7eb" }}>
            <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>
              Active Columns: <span style={{ color: "#135bec", fontWeight: 700 }}>{selectedColumnsList.join(", ") || "None"}</span>
            </Typography>
          </Box>
        </Box>
      </Collapse>
    </Card>
  );
};

export default AdvancedSettings;
