import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth } from '../firebase';
import { sendEmailVerification } from 'firebase/auth';
import './VerificationPage.css';

const VerificationPage = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const user = auth.currentUser;

  const handleResendEmail = async () => {
    if (!user) {
      navigate('/login');
      return;
    }

    try {
      setLoading(true);

      await sendEmailVerification(user, {
        url: window.location.origin + window.location.pathname + '#/verify-email-action',
        handleCodeInApp: true
      });

      navigate('/verification-sent', { replace: true });
    } catch (error) {
      console.error('Error resending verification email:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleBackToLogin = async () => {
    try {
      await auth.signOut();
      navigate('/superadmin');
    } catch (error) {
      console.error('Error signing out:', error);
      navigate('/superadmin');
    }
  };

  return (
    <div className="verification-page">
      {/* Top Navigation Bar */}
      <header className="verification-header">
        <div className="header-content">
          <div className="header-left">
            <div className="logo-icon">
              <span className="material-symbols-outlined">emergency_home</span>
            </div>
            <h2 className="logo-text">AKSYON AGAD</h2>
          </div>
          <div className="header-right">
            <div className="user-avatar">
              {user?.email?.charAt(0).toUpperCase() || 'U'}
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="verification-main">
        <div className="verification-container">
          {/* Verification Card */}
          <div className="verification-card">
            {/* Visual Illustration Section */}
            <div className="verification-illustration">
              <div className="mail-icon-wrapper">
                <div className="mail-circle">
                  <span className="material-symbols-outlined mail-icon">mail</span>
                </div>
                <div className="verified-badge">
                  <span className="material-symbols-outlined verified-icon">verified</span>
                </div>
              </div>
            </div>

            {/* Content Section */}
            <div className="verification-content">
              <h1 className="verification-title">Verify Your Email Address</h1>
              <p className="verification-description">
                To access your account, please verify your email address. We have sent a link to your registered email. <br />
                Please check your inbox and your spam folder.
              </p>

              {/* Primary Action */}
              <div className="verification-actions">
                <button
                  className="btn-resend"
                  onClick={handleResendEmail}
                  disabled={loading}
                >
                  <span className="material-symbols-outlined">send</span>
                  <span>{loading ? 'Sending...' : 'Resend Verification Email'}</span>
                </button>

                {/* Secondary Action */}
                <button
                  className="btn-back"
                  onClick={handleBackToLogin}
                >
                  <span className="material-symbols-outlined">arrow_back</span>
                  <span>Back to Login</span>
                </button>
              </div>
            </div>
          </div>

          {/* Helpful Tip */}
          <div className="verification-tip">
            <span className="material-symbols-outlined tip-icon">info</span>
            <p className="tip-text">
              Didn't receive the email? Check your spam or <a href="mailto:support@aksyonagad.ph" className="tip-link">contact support</a>.
            </p>
          </div>
        </div>
      </main>

      {/* Footer */}
      <footer className="verification-footer">
        <div className="footer-links">
          <a href="/privacy-policy">Privacy Policy</a>
          <a href="/terms-of-service">Terms of Service</a>
          <a href="/help-center">Help Center</a>
        </div>
        <p className="footer-copyright">© 2024 AKSYON AGAD Portal. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default VerificationPage;
