import React, { useEffect, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { auth } from '../firebase';
import { applyActionCode } from 'firebase/auth';
import LoadingScreen from '../components/LoadingScreen';

const VerifyEmailHandler = () => {
  const navigate = useNavigate();
  const { search } = useLocation();
  const [status, setStatus] = useState('processing');

  useEffect(() => {
    const params = new URLSearchParams(search);
    const mode = params.get('mode');
    const oobCode = params.get('oobCode');

    const handleVerification = async () => {
      if (mode !== 'verifyEmail' || !oobCode) {
        setStatus('invalid');
        return;
      }

      try {
        await applyActionCode(auth, oobCode);
        setStatus('success');
        setTimeout(() => navigate('/login'), 2500);
      } catch (error) {
        console.error('Error applying action code:', error);
        setStatus('error');
      }
    };

    handleVerification();
  }, [search, navigate]);

  if (status === 'processing') return <LoadingScreen message="Verifying email..." />;

  return (
    <div style={{display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',minHeight:'60vh'}}>
      {status === 'success' && (
        <div>
          <h2>Email verified</h2>
          <p>Thank you — your email has been verified. Redirecting to login...</p>
        </div>
      )}
      {status === 'error' && (
        <div>
          <h2>Verification failed</h2>
          <p>There was a problem verifying your email. The link may be expired or invalid.</p>
          <button onClick={() => navigate('/verification-sent')}>Resend verification</button>
        </div>
      )}
      {status === 'invalid' && (
        <div>
          <h2>Invalid verification link</h2>
          <p>This link is not a valid verification link.</p>
          <button onClick={() => navigate('/login')}>Back to login</button>
        </div>
      )}
    </div>
  );
};

export default VerifyEmailHandler;
