import React, { useState, useEffect } from "react";
import Sidebar from "../../components/Sidebar";
import Topbar from "../../components/Topbar";
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  CircularProgress,
} from "@mui/material";
import { FileDownload, People, Cake, PendingActions } from "@mui/icons-material";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from "recharts";
import { db } from "../../firebase";
import { collection, query, where, getCountFromServer, getDocs, orderBy, limit, startAfter } from "firebase/firestore";
import jsPDF from "jspdf";
import * as XLSX from "xlsx";
import html2canvas from "html2canvas";

const ReportsOverview = () => {

  const [tabValue, setTabValue] = useState(0);
  const [votersBarangayData, setVotersBarangayData] = useState([]);
  const [profiledBarangayData, setProfiledBarangayData] = useState([]);
  const [barangayData, setBarangayData] = useState([]);

  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({
    totalFamilies: 0,
    totalVoters: 0,
    largestAgeGroup: "18-24",
    pendingUpdates: 0,
  });

  // Calculate age from birthdate
  const calculateAge = (birthDate) => {
    if (!birthDate) return null;
    const today = new Date();
    const birth = birthDate.toDate ? birthDate.toDate() : new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const monthDiff = today.getMonth() - birth.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < birth.getDate())) {
      age--;
    }
    return age;
  };

  // Get age bracket from age
  const getAgeBracket = (age) => {
    if (!age) return null;
    if (age >= 10 && age <= 17) return "10-17";
    if (age >= 18 && age <= 24) return "18-24";
    if (age >= 25 && age <= 34) return "25-34";
    if (age >= 35 && age <= 44) return "35-44";
    if (age >= 45 && age <= 54) return "45-54";
    if (age >= 55 && age <= 64) return "55-64";
    if (age >= 65) return "65+";
    return null;
  };

  // Fetch and process data from Firestore
  const fetchDataFromFirestore = async () => {
    const votersCol = collection(db, "voters");
    
    // Get total voters count
    const totalCount = await getCountFromServer(query(votersCol));
    
    // Get pending updates (no PoliticalStatus)
    const pendingCount = await getCountFromServer(
      query(votersCol, where("PoliticalStatus", "==", ""))
    );

    // Fetch all voters data
    const votersMap = new Map();
    const profiledMap = new Map();
    let lastDoc = null;
    let hasMore = true;
    const BATCH_SIZE = 5000;

    while (hasMore) {
      let q;
      if (lastDoc) {
        q = query(votersCol, orderBy("__name__"), startAfter(lastDoc), limit(BATCH_SIZE));
      } else {
        q = query(votersCol, orderBy("__name__"), limit(BATCH_SIZE));
      }

      const snapshot = await getDocs(q);
      if (snapshot.docs.length === 0) {
        hasMore = false;
        break;
      }

      lastDoc = snapshot.docs[snapshot.docs.length - 1];

      snapshot.docs.forEach((doc) => {
        const voter = doc.data();
        const votersBarangay = (voter.VotersBarangay && voter.VotersBarangay.trim() !== "-") ? voter.VotersBarangay : "[NO BARANGAY]";
        const profiledBarangay = (voter.ProfiledBarangay && voter.ProfiledBarangay.trim() !== "-") ? voter.ProfiledBarangay : "[NO BARANGAY]";
        const birthDate = voter.BirthDate;
        const age = calculateAge(birthDate);
        const ageBracket = getAgeBracket(age);
        const votingStatus = voter.VotingStatus || "UNKNOWN";
        const politicalStatus = (voter.PoliticalStatus || "").toUpperCase().trim();

        if (!ageBracket) return;

        // For Voters Barangay tab - VOTER with any political status (UNTAGGED, ADMIN, OPPOSITION, NO STATUS)
        // Uses VotersBarangay field
        // Exclude NON-VOTER
        if (votingStatus === "VOTER") {
          if (!votersMap.has(votersBarangay)) {
            votersMap.set(votersBarangay, {
              barangay: votersBarangay,
              "10-17": 0,
              "18-24": 0,
              "25-34": 0,
              "35-44": 0,
              "45-54": 0,
              "55-64": 0,
              "65+": 0,
              total: 0,
            });
          }
          const record = votersMap.get(votersBarangay);
          record[ageBracket]++;
          record.total++;
        }

        // For Profiled Barangay tab
        // Uses ProfiledBarangay field
        // Only VOTER with (ADMIN, OPPOSITION, NO STATUS)
        // Exclude: NON-VOTER and UNTAGGED
        const isProfiled = votingStatus === "VOTER" && 
                          (politicalStatus === "ADMIN" || 
                           politicalStatus === "OPPOSITION" || 
                           politicalStatus === "NO_STATUS" ||
                           politicalStatus === "NO STATUS");
        if (isProfiled) {
          if (!profiledMap.has(profiledBarangay)) {
            profiledMap.set(profiledBarangay, {
              barangay: profiledBarangay,
              "10-17": 0,
              "18-24": 0,
              "25-34": 0,
              "35-44": 0,
              "45-54": 0,
              "55-64": 0,
              "65+": 0,
              total: 0,
            });
          }
          const profiledRecord = profiledMap.get(profiledBarangay);
          profiledRecord[ageBracket]++;
          profiledRecord.total++;
        }
      });

      if (snapshot.docs.length < BATCH_SIZE) {
        hasMore = false;
      }
    }

    // Sort data alphabetically (including [NO BARANGAY])
    const votersArray = Array.from(votersMap.values()).sort((a, b) => {
      return a.barangay.localeCompare(b.barangay);
    });
    const profiledArray = Array.from(profiledMap.values()).sort((a, b) => {
      return a.barangay.localeCompare(b.barangay);
    });

    // Calculate largest age group from current tab data
    const calculateLargestAgeGroup = () => {
      const brackets = ["10-17", "18-24", "25-34", "35-44", "45-54", "55-64", "65+"];
      let maxBracket = "18-24";
      let maxCount = 0;
      
      brackets.forEach((bracket) => {
        const votersTotal = votersArray.reduce((sum, row) => sum + (row[bracket] || 0), 0);
        const total = votersTotal;
        if (total > maxCount) {
          maxCount = total;
          maxBracket = bracket;
        }
      });
      return maxBracket;
    };

    const statsData = {
      totalFamilies: Math.floor(totalCount.data().count / 4),
      totalVoters: totalCount.data().count,
      largestAgeGroup: calculateLargestAgeGroup(),
      pendingUpdates: pendingCount.data().count,
    };

    // Cache the data
    localStorage.setItem("reportsOverviewData", JSON.stringify({
      votersData: votersArray,
      profiledData: profiledArray,
      totalVoters: statsData.totalVoters,
      pendingUpdates: statsData.pendingUpdates,
    }));

    return {
      votersArray,
      profiledArray,
      statsData,
    };
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Check if data exists in cache
        const cachedData = localStorage.getItem("reportsOverviewData");
        if (cachedData) {
          const { votersData, profiledData, totalVoters, pendingUpdates } = JSON.parse(cachedData);
          setVotersBarangayData(votersData);
          setProfiledBarangayData(profiledData);
          setBarangayData(votersData);
          setStats({
            totalFamilies: Math.floor(totalVoters / 4),
            totalVoters: totalVoters,
            largestAgeGroup: "18-24",
            pendingUpdates: pendingUpdates,
          });
          return;
        }

        setLoading(true);
        const { votersArray, profiledArray, statsData } = await fetchDataFromFirestore();
        setVotersBarangayData(votersArray);
        setProfiledBarangayData(profiledArray);
        setBarangayData(votersArray);
        setStats(statsData);
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Handle refresh data from Firestore
  const handleRefreshData = async () => {
    try {
      setLoading(true);
      localStorage.removeItem("reportsOverviewData");
      const { votersArray, profiledArray, statsData } = await fetchDataFromFirestore();
      setVotersBarangayData(votersArray);
      setProfiledBarangayData(profiledArray);
      setBarangayData(votersArray);
      setStats(statsData);
    } catch (err) {
      console.error("Error refreshing data:", err);
    } finally {
      setLoading(false);
    }
  };

  // Update table data when tab changes
  const handleTabChange = (e, newValue) => {
    setTabValue(newValue);
    setBarangayData(newValue === 0 ? votersBarangayData : profiledBarangayData);
  };

  // Export to Excel - Both tabs
  const handleExportExcel = () => {
    const wb = XLSX.utils.book_new();

    // Export Voters Barangay tab (excluding [NO BARANGAY])
    const votersFilteredData = votersBarangayData.filter(row => row.barangay !== "[NO BARANGAY]");
    const votersExportData = votersFilteredData.map((row, idx) => ({
      ID: idx + 1,
      BARANGAY: row.barangay,
      "10-17": row["10-17"],
      "18-24": row["18-24"],
      "25-34": row["25-34"],
      "35-44": row["35-44"],
      "45-54": row["45-54"],
      "55-64": row["55-64"],
      "65+": row["65+"],
      TOTAL: row.total,
    }));

    votersExportData.push({
      ID: "",
      BARANGAY: "OVERALL TOTAL",
      "10-17": votersFilteredData.reduce((sum, row) => sum + (row["10-17"] || 0), 0),
      "18-24": votersFilteredData.reduce((sum, row) => sum + (row["18-24"] || 0), 0),
      "25-34": votersFilteredData.reduce((sum, row) => sum + (row["25-34"] || 0), 0),
      "35-44": votersFilteredData.reduce((sum, row) => sum + (row["35-44"] || 0), 0),
      "45-54": votersFilteredData.reduce((sum, row) => sum + (row["45-54"] || 0), 0),
      "55-64": votersFilteredData.reduce((sum, row) => sum + (row["55-64"] || 0), 0),
      "65+": votersFilteredData.reduce((sum, row) => sum + (row["65+"] || 0), 0),
      TOTAL: votersFilteredData.reduce((sum, row) => sum + (row.total || 0), 0),
    });

    const votersWs = XLSX.utils.json_to_sheet(votersExportData);
    XLSX.utils.book_append_sheet(wb, votersWs, "Voters Barangay");

    // Export Profiled Barangay tab (excluding [NO BARANGAY])
    const profiledFilteredData = profiledBarangayData.filter(row => row.barangay !== "[NO BARANGAY]");
    const profiledExportData = profiledFilteredData.map((row, idx) => ({
      ID: idx + 1,
      BARANGAY: row.barangay,
      "10-17": row["10-17"],
      "18-24": row["18-24"],
      "25-34": row["25-34"],
      "35-44": row["35-44"],
      "45-54": row["45-54"],
      "55-64": row["55-64"],
      "65+": row["65+"],
      TOTAL: row.total,
    }));

    profiledExportData.push({
      ID: "",
      BARANGAY: "OVERALL TOTAL",
      "10-17": profiledFilteredData.reduce((sum, row) => sum + (row["10-17"] || 0), 0),
      "18-24": profiledFilteredData.reduce((sum, row) => sum + (row["18-24"] || 0), 0),
      "25-34": profiledFilteredData.reduce((sum, row) => sum + (row["25-34"] || 0), 0),
      "35-44": profiledFilteredData.reduce((sum, row) => sum + (row["35-44"] || 0), 0),
      "45-54": profiledFilteredData.reduce((sum, row) => sum + (row["45-54"] || 0), 0),
      "55-64": profiledFilteredData.reduce((sum, row) => sum + (row["55-64"] || 0), 0),
      "65+": profiledFilteredData.reduce((sum, row) => sum + (row["65+"] || 0), 0),
      TOTAL: profiledFilteredData.reduce((sum, row) => sum + (row.total || 0), 0),
    });

    const profiledWs = XLSX.utils.json_to_sheet(profiledExportData);
    XLSX.utils.book_append_sheet(wb, profiledWs, "Profiled Barangay");

    XLSX.writeFile(wb, "Demographic_Reports.xlsx");
  };

  // Export to PDF - Capture main content
  const handleExportPDF = async () => {
    try {
      // Get the main content area (excludes sidebar and topbar)
      const mainContentElement = document.querySelector('[class*="main-content-export"]');
      if (!mainContentElement) {
        console.error("Main content element not found");
        return;
      }

      // Capture the main content as canvas
      const canvas = await html2canvas(mainContentElement, {
        backgroundColor: "#f5f7fa",
        scale: 2,
        logging: false,
        allowTaint: true,
        useCORS: true,
      });

      // Get canvas dimensions
      const imgWidth = 210; // A4 width in mm
      const pageHeight = 297; // A4 height in mm
      const imgHeight = (canvas.height * imgWidth) / canvas.width;
      let heightLeft = imgHeight;

      const doc = new jsPDF("p", "mm", "a4");
      let position = 0;

      // Add image to PDF
      const imgData = canvas.toDataURL("image/png");
      doc.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
      heightLeft -= pageHeight;

      // Add additional pages if content is longer than one page
      while (heightLeft >= 0) {
        position = heightLeft - imgHeight;
        doc.addPage();
        doc.addImage(imgData, "PNG", 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
      }

      doc.save("Demographic_Reports.pdf");
    } catch (err) {
      console.error("Error exporting PDF:", err);
    }
  };

  // Calculate age distribution dynamically from data
  const calculateAgeDistribution = () => {
    const ageCounts = {
      "10-17": 0,
      "18-24": 0,
      "25-34": 0,
      "35-44": 0,
      "45-54": 0,
      "55-64": 0,
      "65+": 0,
    };

    barangayData.forEach((barangay) => {
      Object.keys(ageCounts).forEach((bracket) => {
        ageCounts[bracket] += barangay[bracket] || 0;
      });
    });

    return [
      { name: "10-17", value: ageCounts["10-17"] },
      { name: "18-24", value: ageCounts["18-24"] },
      { name: "25-34", value: ageCounts["25-34"] },
      { name: "35-44", value: ageCounts["35-44"] },
      { name: "45-54", value: ageCounts["45-54"] },
      { name: "55-64", value: ageCounts["55-64"] },
      { name: "65+", value: ageCounts["65+"] },
    ];
  };

  const ageDistributionData = calculateAgeDistribution();

  // Helper to determine if a bracket is the largest age group
  const isLargestAgeGroup = (bracket) => {
    return bracket === stats.largestAgeGroup;
  };

  const colors = ["#3b82f6", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6", "#ec4899", "#f97316"];

  const ageBrackets = [
    { bracket: "10-17", label: "10-17" },
    { bracket: "18-24", label: "18-24" },
    { bracket: "25-34", label: "25-34" },
    { bracket: "35-44", label: "35-44" },
    { bracket: "45-54", label: "45-54" },
    { bracket: "55-64", label: "55-64" },
    { bracket: "65+", label: "65+" },
  ];

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", bgcolor: "#f5f7fa" }}>
      <Sidebar />
      <Box sx={{ flexGrow: 1, width: { xs: "100%", md: "calc(100% - 260px)" }, display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
        <Topbar />
        <Box sx={{ flexGrow: 1, p: 2, overflowX: "auto" }} className="main-content-export">

          {/* Header with title and buttons */}
          <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 2 }}>
            <Box>
              <Typography variant="h5" sx={{ color: "#1a237e", fontWeight: 700 }}>
                Demographic Reports
              </Typography>
            </Box>
            <Box sx={{ display: "flex", gap: 1 }}>
              <Button variant="outlined" size="small" sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }} onClick={handleRefreshData}>
                Refresh Data
              </Button>
              <Button startIcon={<FileDownload />} variant="outlined" size="small" sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }} onClick={handleExportExcel}>
                Export Excel
              </Button>
              <Button startIcon={<FileDownload />} variant="outlined" size="small" sx={{ borderRadius: 1, textTransform: "none", fontWeight: 600, fontSize: 13 }} onClick={handleExportPDF}>
                Export PDF
              </Button>
            </Box>
          </Box>

          {/* Stats Cards */}
          <Grid container spacing={2} sx={{ mb: 3 }}>
            <Grid item xs={12} sm={6} md={4}>
              <Card sx={{ bgcolor: "#f0f9ff", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#10b981", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <People sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Total Voters
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.totalVoters.toLocaleString()}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={4}>
              <Card sx={{ bgcolor: "#fef2f2", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#ef4444", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <Cake sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Largest Age Group
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.largestAgeGroup}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={4}>
              <Card sx={{ bgcolor: "#fff7ed", border: "none", boxShadow: "0 1px 3px rgba(0,0,0,0.06)" }}>
                <CardContent sx={{ display: "flex", alignItems: "center", gap: 2, p: 2, "&:last-child": { pb: 2 } }}>
                  <Box sx={{ bgcolor: "#f97316", p: 1.5, borderRadius: 2, display: "flex", alignItems: "center", justifyContent: "center" }}>
                    <PendingActions sx={{ color: "#fff", fontSize: 28 }} />
                  </Box>
                  <Box sx={{ flex: 1 }}>
                    <Typography sx={{ fontSize: 12, fontWeight: 600, color: "#666", mb: 0.5 }}>
                      Pending Updates
                    </Typography>
                    <Typography variant="h6" sx={{ color: "#1a237e", fontWeight: 700 }}>
                      {stats.pendingUpdates.toLocaleString()}
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Tabs and Table */}
          <Card sx={{ bgcolor: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.06)", mb: 3 }}>
            <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
              <Tabs value={tabValue} onChange={handleTabChange} sx={{ minHeight: 40 }}>
                <Tab label="Voters Barangay" sx={{ fontSize: 13, textTransform: "none", fontWeight: 600 }} />
                <Tab label="Profiled Barangay" sx={{ fontSize: 13, textTransform: "none", fontWeight: 600 }} />
              </Tabs>
            </Box>

            {loading ? (
              <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", py: 4 }}>
                <CircularProgress />
              </Box>
            ) : (
              <TableContainer>
                <Table size="small">
                <TableHead>
                  <TableRow sx={{ bgcolor: "#1a237e" }}>
                    <TableCell sx={{ color: "#fff", fontWeight: 700, fontSize: 12 }}>ID</TableCell>
                    <TableCell sx={{ color: "#fff", fontWeight: 700, fontSize: 12 }}>BARANGAY</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("10-17") ? "#fbbf24" : "#3b82f6", p: 1 }}>10-17</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("18-24") ? "#fbbf24" : "#10b981", p: 1 }}>18-24</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("25-34") ? "#fbbf24" : "#f59e0b", p: 1 }}>25-34</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("35-44") ? "#fbbf24" : "#ef4444", p: 1 }}>35-44</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("45-54") ? "#fbbf24" : "#8b5cf6", p: 1 }}>45-54</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("55-64") ? "#fbbf24" : "#ec4899", p: 1 }}>55-64</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, bgcolor: isLargestAgeGroup("65+") ? "#fbbf24" : "#f97316", p: 1 }}>65+</TableCell>
                    <TableCell align="center" sx={{ color: "#fff", fontWeight: 700, fontSize: 12, p: 1 }}>TOTAL</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {barangayData.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={10} align="center" sx={{ py: 4 }}>
                        <Typography variant="body2" sx={{ color: "#999" }}>
                          No data available
                        </Typography>
                      </TableCell>
                    </TableRow>
                  ) : (
                    <>
                      {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").map((row, idx) => (
                        <TableRow 
                          key={idx} 
                          hover 
                          sx={{ 
                            "&:hover": { bgcolor: "#f5f7fa" },
                          }}
                        >
                          <TableCell sx={{ fontWeight: 600, color: "#666", fontSize: 12, p: 1 }}>{idx + 1}</TableCell>
                          <TableCell sx={{ 
                            fontWeight: 600, 
                            color: "#1a237e", 
                            fontSize: 12, 
                            p: 1 
                          }}>
                            {row.barangay}
                          </TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("10-17") ? "#fef3c7" : "transparent" }}>{row["10-17"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("18-24") ? "#fef3c7" : "transparent" }}>{row["18-24"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("25-34") ? "#fef3c7" : "transparent" }}>{row["25-34"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("35-44") ? "#fef3c7" : "transparent" }}>{row["35-44"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("45-54") ? "#fef3c7" : "transparent" }}>{row["45-54"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("55-64") ? "#fef3c7" : "transparent" }}>{row["55-64"]}</TableCell>
                          <TableCell align="center" sx={{ color: "#333", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("65+") ? "#fef3c7" : "transparent" }}>{row["65+"]}</TableCell>
                          <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>{row.total}</TableCell>
                        </TableRow>
                      ))}
                      <TableRow sx={{ bgcolor: "#f5f7fa", fontWeight: 700 }}>
                        <TableCell colSpan={2} sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>OVERALL TOTAL</TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("10-17") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["10-17"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("18-24") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["18-24"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("25-34") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["25-34"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("35-44") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["35-44"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("45-54") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["45-54"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("55-64") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["55-64"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1, bgcolor: isLargestAgeGroup("65+") ? "#fef3c7" : "transparent" }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row["65+"] || 0), 0)}
                        </TableCell>
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12, p: 1 }}>
                          {barangayData.filter(row => row.barangay !== "[NO BARANGAY]").reduce((sum, row) => sum + (row.total || 0), 0)}
                        </TableCell>
                      </TableRow>
                    </>
                  )}
                </TableBody>
              </Table>
              </TableContainer>
            )}
          </Card>

          {/* Charts Section */}
          <Grid container spacing={2} sx={{ width: "100%", maxWidth: "100%" }}>
            <Grid item xs={12} sx={{ width: "100%" }}>
              <Card sx={{ bgcolor: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.06)", height: "100%" }}>
                <CardContent sx={{ p: 2 }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: 700, color: "#1a237e", mb: 1.5, fontSize: 13 }}>
                    Standard Age Brackets
                  </Typography>
                  <Box sx={{ display: "flex", flexDirection: "column", gap: 0.75 }}>
                    {ageBrackets.map((item, idx) => (
                      <Box key={idx} sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <Box sx={{ width: 12, height: 12, bgcolor: colors[idx], borderRadius: 1.5, flexShrink: 0 }} />
                        <Box sx={{ flex: 1 }}>
                          <Typography sx={{ fontWeight: 600, color: "#666", fontSize: 12 }}>
                            {item.label}
                          </Typography>
                          <Typography sx={{ fontWeight: 700, color: "#1a237e", fontSize: 12 }}>
                            {(barangayData.reduce((sum, row) => sum + (row[item.bracket] || 0), 0)).toLocaleString()}
                          </Typography>
                        </Box>
                      </Box>
                    ))}
                  </Box>
                </CardContent>
              </Card>
            </Grid>

            {/* Distribution Overview Chart */}
            <Grid item xs={12} sx={{ width: "100%" }}>
              <Card sx={{ bgcolor: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.06)", width: "100%", height: "100%" }}>
                <CardContent sx={{ p: 1.5, width: "100%" }}>
                  <Typography variant="subtitle2" sx={{ fontWeight: 700, color: "#1a237e", mb: 1.5, fontSize: 13 }}>
                    Distribution Overview
                  </Typography>
                  <ResponsiveContainer width="100%" height={400}>
                    <BarChart data={ageDistributionData} margin={{ top: 20, right: 30, left: 0, bottom: 20 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                      <XAxis dataKey="name" tick={{ fontSize: 12 }} />
                      <YAxis tick={{ fontSize: 12 }} />
                      <Tooltip contentStyle={{ fontSize: 12 }} />
                      <Bar dataKey="value" fill="#3b82f6" radius={[6, 6, 0, 0]}>
                        {ageDistributionData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={colors[index]} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

        </Box>
      </Box>
    </Box>
  );
};

export default ReportsOverview;
