import React, { useState, useEffect } from "react";
import {
  Card,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Skeleton,
} from "@mui/material";

const FamilyProfileAddressTable = ({ 
  selectedColumns = {}, 
  allTableData = [],
  loading = false,
  loadingProgress = 0,
  isSpecificBarangaySelected = false
}) => {
  const [loadedRows, setLoadedRows] = useState(0);

  useEffect(() => {
    if (allTableData.length === 0) {
      setLoadedRows(0);
      return;
    }

    // Gradually load rows for smooth rendering
    let currentRow = 0;
    const interval = setInterval(() => {
      if (currentRow < allTableData.length + 1) {
        setLoadedRows(currentRow);
        currentRow++;
      } else {
        clearInterval(interval);
      }
    }, 20); // Load one row every 20ms for smooth effect

    return () => clearInterval(interval);
  }, [allTableData]);

  const tableHeaders = [
    { key: "barangay", label: "BARANGAY", bgColor: "#1a237e", textColor: "#fff" },
    { key: "purok", label: "PUROK", bgColor: "#1a237e", textColor: "#fff" },
    { key: "FAMILY HEAD", label: "FAMILY HEAD", bgColor: "#6366f1", textColor: "#fff", show: selectedColumns["FAMILY HEAD"] !== false },
    { key: "FAMILY MEMBER", label: "FAMILY MEMBER", bgColor: "#10b981", textColor: "#fff", show: selectedColumns["FAMILY MEMBER"] !== false },
    { key: "TOTAL", label: "TOTAL", bgColor: "#f97316", textColor: "#fff", show: selectedColumns.TOTAL !== false },
    { key: "NON-VOTER FAMILY HEAD", label: "NON-VOTER FAMILY HEAD", bgColor: "#3b82f6", textColor: "#fff", show: selectedColumns["NON-VOTER FAMILY HEAD"] !== false },
    { key: "NON-VOTER FAMILY MEMBER", label: "NON-VOTER FAMILY MEMBER", bgColor: "#ef4444", textColor: "#fff", show: selectedColumns["NON-VOTER FAMILY MEMBER"] !== false },
    { key: "GRAND TOTAL", label: "GRAND TOTAL", bgColor: "#8b5cf6", textColor: "#fff", show: selectedColumns["GRAND TOTAL"] !== false },
  ];

  // Use the data as provided (already filtered by parent component)
  const filteredData = allTableData;

  // Calculate totals from filtered data
  const totals = filteredData.reduce(
    (sum, row) => ({
      familyHead: sum.familyHead + (row["FAMILY HEAD"] || 0),
      familyMember: sum.familyMember + (row["FAMILY MEMBER"] || 0),
      total: sum.total + (row.TOTAL || 0),
      nonVoterFamilyHead: sum.nonVoterFamilyHead + (row["NON-VOTER FAMILY HEAD"] || 0),
      nonVoterFamilyMember: sum.nonVoterFamilyMember + (row["NON-VOTER FAMILY MEMBER"] || 0),
      grandTotal: sum.grandTotal + (row["GRAND TOTAL"] || 0),
    }),
    { familyHead: 0, familyMember: 0, total: 0, nonVoterFamilyHead: 0, nonVoterFamilyMember: 0, grandTotal: 0 }
  );

  return (
    <Card sx={{ bgcolor: "#fff", boxShadow: "0 2px 8px rgba(0,0,0,0.08)", borderRadius: 1.5 }}>
      <TableContainer>
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: "#1a237e" }}>
                {tableHeaders.map((header) => {
                  if (isSpecificBarangaySelected && header.key === "purok") return null;
                  return (!header.show && header.key !== "barangay" && header.key !== "purok") ? null : (
                    <TableCell
                      key={header.key}
                      align={header.key === "barangay" || header.key === "purok" ? "left" : "center"}
                      sx={{
                        color: header.textColor,
                        fontWeight: 700,
                        fontSize: 13,
                        py: 2.5,
                        px: 2,
                        bgcolor: header.bgColor,
                        borderRight: "1px solid rgba(255, 255, 255, 0.1)",
                        "&:last-child": {
                          borderRight: "none",
                        },
                      }}
                    >
                      {header.label}
                    </TableCell>
                  );
                })}
              </TableRow>
            </TableHead>

            <TableBody>
              {filteredData.length === 0 && !loading ? (
                <TableRow>
                  <TableCell colSpan={tableHeaders.length} align="center" sx={{ py: 4 }}>
                    <Typography variant="body2" sx={{ color: "#999" }}>
                      No family profile records found.
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : filteredData.length === 0 && loading ? (
                // Show skeleton rows while loading
                Array.from({ length: 10 }).map((_, idx) => (
                  <TableRow key={`skeleton-${idx}`}>
                    {tableHeaders.map((header) => {
                      if (isSpecificBarangaySelected && header.key === "purok") return null;
                      return (!header.show && header.key !== "barangay" && header.key !== "purok") ? null : (
                        <TableCell key={header.key} sx={{ py: 2, px: 2 }}>
                          <Skeleton variant="text" />
                        </TableCell>
                      );
                    })}
                  </TableRow>
                ))
              ) : (
                <>
                  {filteredData.map((row, idx) => {
                    const isLoaded = idx < loadedRows;
                    return (
                    <TableRow 
                      key={idx} 
                      hover 
                      sx={{ 
                        "&:nth-of-type(odd)": { bgcolor: "#f5f5f5" },
                        "&:hover": { bgcolor: "#fafafa" }
                      }}
                    >
                      <TableCell sx={{ fontSize: 12, fontWeight: 500 }}>
                        {isLoaded ? row.barangay : <Skeleton variant="text" />}
                      </TableCell>
                      {!isSpecificBarangaySelected && (
                        <TableCell sx={{ fontSize: 12 }}>
                          {isLoaded ? row.purok : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                      {selectedColumns["FAMILY HEAD"] !== false && (
                        <TableCell align="center" sx={{ fontSize: 12 }}>
                          {isLoaded ? row["FAMILY HEAD"]?.toLocaleString() || 0 : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                      {selectedColumns["FAMILY MEMBER"] !== false && (
                        <TableCell align="center" sx={{ fontSize: 12 }}>
                          {isLoaded ? row["FAMILY MEMBER"]?.toLocaleString() || 0 : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                      {selectedColumns.TOTAL !== false && (
                        <TableCell align="center" sx={{ fontSize: 12 }}>
                          {isLoaded ? row.TOTAL?.toLocaleString() || 0 : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                      {selectedColumns["NON-VOTER FAMILY HEAD"] !== false && (
                        <TableCell align="center" sx={{ fontSize: 12 }}>
                          {isLoaded ? row["NON-VOTER FAMILY HEAD"]?.toLocaleString() || 0 : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                      {selectedColumns["NON-VOTER FAMILY MEMBER"] !== false && (
                        <TableCell align="center" sx={{ fontSize: 12 }}>
                          {isLoaded ? row["NON-VOTER FAMILY MEMBER"]?.toLocaleString() || 0 : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                      {selectedColumns["GRAND TOTAL"] !== false && (
                        <TableCell align="center" sx={{ fontSize: 12 }}>
                          {isLoaded ? row["GRAND TOTAL"]?.toLocaleString() || 0 : <Skeleton variant="text" />}
                        </TableCell>
                      )}
                    </TableRow>
                    );
                  })}
                  {/* Totals Row */}
                  {filteredData.length > 0 && (
                    <TableRow 
                      sx={{ 
                        bgcolor: "#e8eaf6",
                      }}
                    >
                      <TableCell sx={{ fontWeight: 700, color: "#1a237e" }}>TOTAL</TableCell>
                      {!isSpecificBarangaySelected && (
                        <TableCell sx={{ fontWeight: 700, color: "#1a237e" }}></TableCell>
                      )}
                      {selectedColumns["FAMILY HEAD"] !== false && (
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.familyHead.toLocaleString()}</TableCell>
                      )}
                      {selectedColumns["FAMILY MEMBER"] !== false && (
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.familyMember.toLocaleString()}</TableCell>
                      )}
                      {selectedColumns.TOTAL !== false && (
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.total.toLocaleString()}</TableCell>
                      )}
                      {selectedColumns["NON-VOTER FAMILY HEAD"] !== false && (
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.nonVoterFamilyHead.toLocaleString()}</TableCell>
                      )}
                      {selectedColumns["NON-VOTER FAMILY MEMBER"] !== false && (
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.nonVoterFamilyMember.toLocaleString()}</TableCell>
                      )}
                      {selectedColumns["GRAND TOTAL"] !== false && (
                        <TableCell align="center" sx={{ fontWeight: 700, color: "#1a237e" }}>{totals.grandTotal.toLocaleString()}</TableCell>
                      )}
                    </TableRow>
                  )}
                </>
              )}
            </TableBody>
          </Table>
        </TableContainer>
    </Card>
  );
};

export default FamilyProfileAddressTable;
