import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Card,
  CardContent,
  CircularProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import { db } from "../../firebase";
import { collection, query, where, getDocs, limit, getCountFromServer } from "firebase/firestore";

const MissingBarangayAnalysis = () => {

  const [loading, setLoading] = useState(true);
  const [totalMissing, setTotalMissing] = useState(0);
  const [sampleRecords, setSampleRecords] = useState([]);
  const [stats, setStats] = useState({
    voters: 0,
    nonVoters: 0,
  });

  useEffect(() => {
    const analyze = async () => {
      try {
        const votersCol = collection(db, "voters");

        // Count total missing
        const emptyCount = await getCountFromServer(
          query(votersCol, where("ProfiledBarangay", "==", ""))
        );
        setTotalMissing(emptyCount.data().count);

        // Get sample records
        const q = query(votersCol, where("ProfiledBarangay", "==", ""), limit(10));
        const snapshot = await getDocs(q);
        
        const records = snapshot.docs.map((doc) => ({
          id: doc.id,
          name: doc.data().FullName || "N/A",
          votingStatus: doc.data().VotingStatus || "N/A",
          politicalStatus: doc.data().PoliticalStatus || "N/A",
          familyType: doc.data().FamilyType || "N/A",
          purok: doc.data().ProfiledPurok || "N/A",
          address: doc.data().Address || "N/A",
          hasBirthDate: doc.data().BirthDate ? "Yes" : "No",
        }));
        setSampleRecords(records);

        // Get voting status stats
        try {
          const voterCount = await getCountFromServer(
            query(
              votersCol,
              where("ProfiledBarangay", "==", ""),
              where("VotingStatus", "==", "VOTER")
            )
          );
          setStats((prev) => ({
            ...prev,
            voters: voterCount.data().count,
          }));
        } catch (err) {
          console.log("Voter count query not supported");
        }

      } catch (err) {
        console.error("Error:", err);
      } finally {
        setLoading(false);
      }
    };

    analyze();
  }, []);

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" sx={{ mb: 3, fontWeight: 700, color: "#1a237e" }}>
        Missing Barangay Data Analysis
      </Typography>

      {loading ? (
        <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <>
          <Card sx={{ mb: 3, bgcolor: "#fef3c7", border: "1px solid #fbbf24" }}>
            <CardContent>
              <Typography variant="h6" sx={{ color: "#92400e", fontWeight: 700 }}>
                Total Records with Missing ProfiledBarangay: {totalMissing.toLocaleString()}
              </Typography>
              <Typography sx={{ color: "#92400e", mt: 1 }}>
                Voting Status Breakdown:
              </Typography>
              <Typography sx={{ color: "#92400e", ml: 2 }}>
                • VOTER: {stats.voters.toLocaleString()}
              </Typography>
              <Typography sx={{ color: "#92400e", ml: 2 }}>
                • Non-Voter/Unknown: {(totalMissing - stats.voters).toLocaleString()}
              </Typography>
            </CardContent>
          </Card>

          <Typography variant="h6" sx={{ mb: 2, fontWeight: 700, color: "#1a237e" }}>
            Sample Records (First 10):
          </Typography>

          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow sx={{ bgcolor: "#1a237e" }}>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Name</TableCell>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Voting Status</TableCell>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Political Status</TableCell>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Family Type</TableCell>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Purok</TableCell>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Address</TableCell>
                  <TableCell sx={{ color: "#fff", fontWeight: 700 }}>Has BirthDate</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {sampleRecords.map((record, idx) => (
                  <TableRow key={idx} hover>
                    <TableCell sx={{ fontSize: 12 }}>{record.name}</TableCell>
                    <TableCell sx={{ fontSize: 12 }}>{record.votingStatus}</TableCell>
                    <TableCell sx={{ fontSize: 12 }}>{record.politicalStatus}</TableCell>
                    <TableCell sx={{ fontSize: 12 }}>{record.familyType}</TableCell>
                    <TableCell sx={{ fontSize: 12 }}>{record.purok}</TableCell>
                    <TableCell sx={{ fontSize: 12 }}>{record.address}</TableCell>
                    <TableCell sx={{ fontSize: 12 }}>{record.hasBirthDate}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>

          <Box sx={{ mt: 3, p: 2, bgcolor: "#f0f4ff", borderRadius: 1 }}>
            <Typography variant="body2" sx={{ color: "#1a237e", fontWeight: 600, mb: 1 }}>
              💡 Insights:
            </Typography>
            <Typography variant="body2" sx={{ color: "#1a237e", lineHeight: 1.8 }}>
              • These records have FullName, VotingStatus, and other demographic data<br/>
              • They may have been imported without barangay assignment<br/>
              • Check if they have ProfiledPurok or Address field instead<br/>
              • Consider merging these records with valid barangay data or marking them for manual review
            </Typography>
          </Box>
        </>
      )}
    </Box>
  );
};

export default MissingBarangayAnalysis;
