import React, { useEffect, useState } from "react";
import { Box, Typography, Grid, Card, Avatar } from "@mui/material";
import { People, Security, CheckCircle } from "@mui/icons-material";
import {
  PieChart,
  Pie,
  Cell,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Legend,
} from "recharts";
import EncodingSidebar from "../../components/EncodingSidebar";
import LoadingScreen from "../../components/LoadingScreen";
import { getAllUsers } from "../../db/usersDB";

const COLORS = ["#007aff", "#f44336", "#4caf50", "#ff9800"];

const Dashboard = () => {
  const [metrics, setMetricsState] = useState([]);
  const [activityData, setActivityData] = useState([]);
  const [monthlyActivity, setMonthlyActivity] = useState([]);
  const [encoderProductivity, setEncoderProductivity] = useState([]);
  const [userName, setUserName] = useState("");

  const fetchMetrics = async () => {
    const users = await getAllUsers();

    const admins = users.filter((u) => u.role === "admin").length;
    const encoders = users.filter((u) => u.role === "encoder").length;

    setMetricsState([
      {
        title: "Total Users",
        value: users.length,
        icon: <People sx={{ fontSize: 40, color: "#007aff" }} />,
      },
      {
        title: "Admins",
        value: admins,
        icon: <Security sx={{ fontSize: 40, color: "#f44336" }} />,
      },
      {
        title: "Encoders",
        value: encoders,
        icon: <CheckCircle sx={{ fontSize: 40, color: "#4caf50" }} />,
      },
    ]);

    // Pie Chart Data
    setActivityData([
      { name: "Admins", value: admins },
      { name: "Encoders", value: encoders },
    ]);

    // Monthly Activity Chart (Users created per month)
    const monthMap = {};
    users.forEach((u) => {
      if (!u.dateCreated) return; // if missing, ignore
      const month = new Date(u.dateCreated).toLocaleString("default", {
        month: "short",
      });
      monthMap[month] = (monthMap[month] || 0) + 1;
    });

    setMonthlyActivity(
      Object.keys(monthMap).map((m) => ({
        month: m,
        created: monthMap[m],
      }))
    );

    // Encoder Productivity (how many users each encoder created)
    const encoderMap = {};
    users.forEach((u) => {
      if (!u.createdBy) return;
      encoderMap[u.createdBy] = (encoderMap[u.createdBy] || 0) + 1;
    });

    setEncoderProductivity(
      Object.keys(encoderMap).map((enc) => ({
        encoder: enc,
        total: encoderMap[enc],
      }))
    );
  };

  useEffect(() => {
    fetchMetrics();
    const name =
      localStorage.getItem("name") || localStorage.getItem("username");
    setUserName(name);
  }, []);

  return (
    <Box sx={{ display: "flex", height: "100vh", background: "#f7f8fa" }}>
      <EncodingSidebar />

      <Box sx={{ flex: 1, p: 4, overflowY: "auto" }}>
        {/* Header */}
        <Box sx={{ mb: 4 }}>
          <Typography variant="h4" sx={{ fontWeight: 700, color: "#1c1c1e" }}>
            Welcome, {userName}!
          </Typography>
          <Typography variant="subtitle1" sx={{ color: "#555" }}>
            Here's a quick overview of the system status.
          </Typography>
        </Box>

        {/* Metrics */}
        <Grid container spacing={3}>
          {metrics.map((metric, idx) => (
            <Grid item xs={12} sm={6} md={3} key={idx}>
              <Card
                sx={{
                  display: "flex",
                  alignItems: "center",
                  p: 2,
                  borderRadius: 3,
                  boxShadow: "0 4px 16px rgba(0,0,0,0.05)",
                  transition: "transform 0.2s",
                  "&:hover": { transform: "translateY(-4px)" },
                }}
              >
                <Avatar
                  sx={{ bgcolor: "transparent", width: 56, height: 56, mr: 2 }}
                >
                  {metric.icon}
                </Avatar>
                <Box>
                  <Typography sx={{ fontWeight: 700, fontSize: "1.2rem" }}>
                    {metric.value}
                  </Typography>
                  <Typography sx={{ color: "#555" }}>{metric.title}</Typography>
                </Box>
              </Card>
            </Grid>
          ))}
        </Grid>

        {/* Pie Chart */}
        <Box
          sx={{
            mt: 5,
            p: 3,
            background: "#fff",
            borderRadius: 3,
            boxShadow: "0 4px 16px rgba(0,0,0,0.05)",
          }}
        >
          <Typography variant="h6" sx={{ mb: 2 }}>
            User Role Distribution
          </Typography>
          <ResponsiveContainer width="100%" height={250}>
            <PieChart>
              <Pie
                data={activityData}
                dataKey="value"
                nameKey="name"
                cx="50%"
                cy="50%"
                outerRadius={80}
                label
              >
                {activityData.map((entry, index) => (
                  <Cell
                    key={`cell-${index}`}
                    fill={COLORS[index % COLORS.length]}
                  />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </Box>

        {/* User Activity (Monthly) */}
        <Box
          sx={{
            mt: 4,
            p: 3,
            background: "#fff",
            borderRadius: 3,
            boxShadow: "0 4px 16px rgba(0,0,0,0.05)",
          }}
        >
          <Typography variant="h6">User Activity (By Month)</Typography>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={monthlyActivity}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="month" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="created" fill="#007aff" />
            </BarChart>
          </ResponsiveContainer>
        </Box>

        {/* Encoder Productivity */}
        <Box
          sx={{
            mt: 4,
            p: 3,
            background: "#fff",
            borderRadius: 3,
            boxShadow: "0 4px 16px rgba(0,0,0,0.05)",
          }}
        >
          <Typography variant="h6">Encoder Productivity</Typography>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={encoderProductivity}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="encoder" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="total" fill="#4caf50" />
            </BarChart>
          </ResponsiveContainer>
        </Box>
      </Box>
    </Box>
  );
};

export default Dashboard;
