import React, { useState, useCallback } from "react";
import {
  Box,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  CircularProgress,
  Grid,
  Pagination,
  TextField,
} from "@mui/material";
import { FileDownload as FileDownloadIcon } from "@mui/icons-material";
import { db } from "../../../firebase";
import { collection, getDocs, query, where } from "firebase/firestore";
import * as XLSX from "xlsx";

const VotersViewDialog = ({ open, onClose, barangay, purok }) => {
  const [votersList, setVotersList] = useState([]);
  const [loadingVoters, setLoadingVoters] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  const handleOpenDialog = useCallback(async () => {
    setLoadingVoters(true);
    try {
      const votersRef = collection(db, "voters");
      let q;

      if (purok && purok !== "") {
        q = query(
          votersRef,
          where("ProfiledBarangay", "==", barangay),
          where("ProfiledPurok", "==", purok)
        );
      } else {
        q = query(votersRef, where("ProfiledBarangay", "==", barangay));
      }

      const snapshot = await getDocs(q);
      const voters = snapshot.docs.map(doc => doc.data());
      setVotersList(voters);
    } catch (err) {
      console.error("Error fetching voters:", err);
      setVotersList([]);
    } finally {
      setLoadingVoters(false);
    }
  }, [barangay, purok]);

  const handleClose = () => {
    setVotersList([]);
    setLoadingVoters(false);
    setCurrentPage(1);
    onClose();
  };

  const handleExportToExcel = () => {
    if (votersList.length === 0) {
      alert("No data to export");
      return;
    }

    try {
      // Prepare data for export
      const exportData = votersList.map((voter) => ({
        "Name": voter.VotersName || "",
        "Voting Status": voter.VotingStatus || "",
        "Political Status": voter.PoliticalStatus || "",
        "Sex": voter.Sex || "",
        "Birth Date": voter.BirthDate || "",
        "Family Type": voter.FamilyType || "",
        "Precinct": voter.Precinct || "",
        "Profiled Barangay": voter.ProfiledBarangay || "",
        "Profiled Purok": voter.ProfiledPurok || "",
        "Voters Barangay": voter.VotersBarangay || "",
        "Voters Address": voter.VotersAddress || "",
      }));

      // Create workbook and worksheet
      const worksheet = XLSX.utils.json_to_sheet(exportData);
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, worksheet, "Voters");

      // Set column widths
      worksheet["!cols"] = [
        { wch: 25 }, // Name
        { wch: 15 }, // Voting Status
        { wch: 18 }, // Political Status
        { wch: 8 },  // Sex
        { wch: 15 }, // Birth Date
        { wch: 15 }, // Family Type
        { wch: 12 }, // Precinct
        { wch: 20 }, // Profiled Barangay
        { wch: 18 }, // Profiled Purok
        { wch: 20 }, // Voters Barangay
        { wch: 30 }, // Voters Address
      ];

      // Generate filename with barangay and purok
      const filename = `Voters_${barangay}${purok ? `_${purok}` : ""}_${new Date().toISOString().split("T")[0]}.xlsx`;

      // Write file
      XLSX.writeFile(workbook, filename);
    } catch (error) {
      console.error("Error exporting to Excel:", error);
      alert("Error exporting data");
    }
  };

  React.useEffect(() => {
    if (open && barangay) {
      handleOpenDialog();
      setCurrentPage(1);
    }
  }, [open, barangay, purok, handleOpenDialog]);

  // Calculate pagination
  const totalPages = Math.ceil(votersList.length / rowsPerPage);
  const startIndex = (currentPage - 1) * rowsPerPage;
  const endIndex = startIndex + rowsPerPage;
  const paginatedVoters = votersList.slice(startIndex, endIndex);

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: { borderRadius: "8px", boxShadow: "0 10px 40px rgba(0,0,0,0.15)" }
      }}
    >
      <DialogTitle sx={{ bgcolor: "#1a237e", color: "#fff", fontWeight: 700, fontSize: 18 }}>
        {barangay && `Voters in ${barangay}${purok ? ` - ${purok}` : ''}`}
      </DialogTitle>
      <DialogContent sx={{ py: 3 }}>
        {loadingVoters ? (
          <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", py: 4 }}>
            <CircularProgress />
          </Box>
        ) : votersList.length === 0 ? (
          <Box sx={{ textAlign: "center", py: 4, color: "#999" }}>
            <Typography>No voters found</Typography>
          </Box>
        ) : (
          <>
            {/* Rows Per Page Control */}
            <Box sx={{ mb: 2, display: "flex", gap: 2, alignItems: "center" }}>
              <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>
                Rows per page:
              </Typography>
              <TextField
                type="number"
                size="small"
                value={rowsPerPage}
                onChange={(e) => {
                  const value = Math.max(1, parseInt(e.target.value) || 10);
                  setRowsPerPage(value);
                  setCurrentPage(1);
                }}
                inputProps={{ min: 1, max: 100 }}
                sx={{ width: 80 }}
              />
              <Typography variant="caption" sx={{ color: "#999" }}>
                Total: {votersList.length} voters
              </Typography>
            </Box>

            {/* Voters List */}
            <Box sx={{ maxHeight: "400px", overflowY: "auto", mb: 2 }}>
              {paginatedVoters.map((voter, idx) => (
                <Box
                  key={`${startIndex + idx}-${voter.VotersName}`}
                  sx={{
                    mb: 3,
                    p: 2,
                    border: "1px solid #e5e7eb",
                    borderRadius: "6px",
                    bgcolor: "#f9fafb",
                    "&:hover": { bgcolor: "#f0f4ff", borderColor: "#135bec" }
                  }}
                >
                  <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Name</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.VotersName || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Voting Status</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.VotingStatus || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Political Status</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.PoliticalStatus || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Sex</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.Sex || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Birth Date</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.BirthDate || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Family Type</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.FamilyType || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Precinct</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.Precinct || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Profiled Barangay</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.ProfiledBarangay || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Profiled Purok</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.ProfiledPurok || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Voters Barangay</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.VotersBarangay || "N/A"}</Typography>
                    </Grid>
                    <Grid item xs={12}>
                      <Typography variant="caption" sx={{ color: "#666", fontWeight: 600 }}>Voters Address</Typography>
                      <Typography sx={{ color: "#1a237e", fontWeight: 500 }}>{voter.VotersAddress || "N/A"}</Typography>
                    </Grid>
                  </Grid>
                </Box>
              ))}
            </Box>

            {/* Pagination Controls */}
            {totalPages > 1 && (
              <Box sx={{ display: "flex", justifyContent: "center", pt: 2, borderTop: "1px solid #e5e7eb" }}>
                <Pagination
                  count={totalPages}
                  page={currentPage}
                  onChange={(e, page) => setCurrentPage(page)}
                  color="primary"
                  size="small"
                />
              </Box>
            )}

            {/* Page Info */}
            <Box sx={{ textAlign: "center", mt: 1.5 }}>
              <Typography variant="caption" sx={{ color: "#999" }}>
                Showing {startIndex + 1} to {Math.min(endIndex, votersList.length)} of {votersList.length}
              </Typography>
            </Box>
          </>
        )}
      </DialogContent>
      <DialogActions sx={{ p: 2, borderTop: "1px solid #e5e7eb", display: "flex", justifyContent: "space-between" }}>
        <Button
          onClick={handleExportToExcel}
          disabled={votersList.length === 0}
          variant="outlined"
          startIcon={<FileDownloadIcon />}
          sx={{ color: "#10b981", borderColor: "#10b981", fontWeight: 600, "&:hover": { bgcolor: "#f0fdf4" } }}
        >
          Export Excel
        </Button>
        <Button onClick={handleClose} sx={{ color: "#135bec", fontWeight: 600 }}>
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default VotersViewDialog;
