import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { auth, db } from '../../../firebase';
import { signOut } from 'firebase/auth';
import { collection, query, orderBy, onSnapshot } from 'firebase/firestore';
import LoadingScreen from '../../../components/LoadingScreen';
import './TransactionsPage.css';

// Service definitions with colors
const SERVICE_COLORS = {
  'MEDICINE ASSISTANT': { color: '#f43f5e', name: 'Medicine Assistant' },
  'BURIAL ASSISTANCE': { color: '#f59e0b', name: 'Burial Assistance' },
  'EDUCATION SUPPORT': { color: '#3b82f6', name: 'Education Support' },
  'FINANCIAL AID': { color: '#10b981', name: 'Financial Aid' },
  'LIVELIHOOD PROGRAMS': { color: '#a855f7', name: 'Livelihood Programs' },
  'HEALTH CHECKUP': { color: '#06b6d4', name: 'Health Checkup' }
};

const STATUS_STYLES = {
  'PENDING': { bg: '#fef3c7', text: '#92400e', border: '#fde68a' },
  'COMPLETED': { bg: '#dcfce7', text: '#166534', border: '#bbf7d0' },
  'REJECTED': { bg: '#fee2e2', text: '#991b1b', border: '#fecaca' },
  'IN PROGRESS': { bg: '#dbeafe', text: '#1e40af', border: '#bfdbfe' }
};

const TransactionsPage = () => {
  const navigate = useNavigate();
  const [transactions, setTransactions] = useState([]);
  const [filteredTransactions, setFilteredTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isCheckingAuth, setIsCheckingAuth] = useState(true);
  const [username, setUsername] = useState('User');
  const [darkMode, setDarkMode] = useState(false);
  const [userInitials, setUserInitials] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [menuOpen, setMenuOpen] = useState(false);
  const menuRef = useRef(null);

  // Filter states
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedService, setSelectedService] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // Check authentication
  useEffect(() => {
    const checkAuthentication = () => {
      try {
        const currentUser = auth.currentUser;
        const storedUsername = sessionStorage.getItem('servicesUsername') || localStorage.getItem('servicesUsername');
        const storedUid = sessionStorage.getItem('servicesUid') || localStorage.getItem('servicesUid');
        const storedEmail = sessionStorage.getItem('servicesEmail') || localStorage.getItem('servicesEmail');
        
        if ((currentUser || storedUid) && storedUsername) {
          setUsername(storedUsername);
          setUserInitials(storedUsername.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2));
          setUserEmail(currentUser?.email || storedEmail || '');
          setIsAuthenticated(true);
        } else {
          navigate('/services');
        }
      } catch (err) {
        console.error('Auth check error:', err);
        navigate('/services');
      } finally {
        setIsCheckingAuth(false);
      }
    };

    checkAuthentication();
  }, [navigate]);

  // Fetch transactions from Firebase
  useEffect(() => {
    if (!isAuthenticated || isCheckingAuth) return;

    setLoading(true);
    const q = query(
      collection(db, 'applications'),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const transactionsList = snapshot.docs.map(doc => {
        const data = doc.data();
        const createdAt = data.createdAt?.toDate ? data.createdAt.toDate() : 
                         (data.createdAt?.seconds ? new Date(data.createdAt.seconds * 1000) : new Date());
        
        return {
          id: doc.id,
          transactionId: data.transactionId || `#TXN-${Math.random().toString(36).substr(2, 5).toUpperCase()}`,
          fullName: data.fullName || (data.formData && data.formData.fullName) || 'N/A',
          serviceName: data.serviceName || data.serviceId || 'Unknown',
          status: data.status || 'PENDING',
          createdAt: createdAt,
          userId: data.userId || 'N/A',
          formData: data.formData || {}
        };
      });
      setTransactions(transactionsList);
      setLoading(false);
    }, (err) => {
      console.error('Error loading transactions:', err);
      setTransactions([]);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [isAuthenticated, isCheckingAuth]);

  // Filter transactions based on search and filters
  useEffect(() => {
    let filtered = [...transactions];

    // Search filter
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(t =>
        t.transactionId.toLowerCase().includes(term) ||
        t.fullName.toLowerCase().includes(term) ||
        t.userId.toLowerCase().includes(term)
      );
    }

    // Service filter
    if (selectedService) {
      filtered = filtered.filter(t => t.serviceName === selectedService);
    }

    // Date range filter
    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(t => t.createdAt >= start);
    }

    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filtered = filtered.filter(t => t.createdAt <= end);
    }

    setFilteredTransactions(filtered);
    setCurrentPage(1);
  }, [searchTerm, selectedService, startDate, endDate, transactions]);

  // Quick filter handlers
  const handleQuickFilter = (filterType) => {
    const today = new Date();
    const start = new Date();

    switch (filterType) {
      case 'today':
        setStartDate(today.toISOString().split('T')[0]);
        setEndDate(today.toISOString().split('T')[0]);
        break;
      case 'week':
        start.setDate(today.getDate() - 7);
        setStartDate(start.toISOString().split('T')[0]);
        setEndDate(today.toISOString().split('T')[0]);
        break;
      case 'month':
        start.setMonth(today.getMonth() - 1);
        setStartDate(start.toISOString().split('T')[0]);
        setEndDate(today.toISOString().split('T')[0]);
        break;
      case 'all':
        setStartDate('');
        setEndDate('');
        break;
      default:
        break;
    }
  };

  // Pagination
  const totalPages = Math.ceil(filteredTransactions.length / itemsPerPage);
  const paginatedTransactions = filteredTransactions.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (err) {
      console.error('Logout failed:', err);
    }
    sessionStorage.clear();
    localStorage.removeItem('servicesUsername');
    localStorage.removeItem('servicesUid');
    localStorage.removeItem('serviceAccess');
    localStorage.removeItem('role');
    navigate('/services');
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleExportReport = () => {
    const csvContent = [
      ['Transaction ID', 'Date/Time', 'Patient Name', 'Service', 'Status'].join(','),
      ...filteredTransactions.map(t =>
        [
          t.transactionId,
          t.createdAt.toLocaleString(),
          t.fullName,
          t.serviceName,
          t.status
        ].join(',')
      )
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transactions-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  if (isCheckingAuth) {
    return <LoadingScreen message="Verifying access..." />;
  }

  return (
    <div className={`transactions-container ${darkMode ? 'dark' : ''}`}>
      {/* Header */}
      <header className="transactions-header">
        <div className="header-left">
          <div className="logo-container">
            <span className="logo-text">
              <span className="logo-green">AKSYON</span>
              <span className="logo-red">AGAD</span>
            </span>
          </div>
        </div>
        <div className="header-nav">
          <a href="/services/dashboard" className="nav-link">Dashboard</a>
          <a href="/services/transactions" className="nav-link active">Transactions</a>
        </div>
        <div className="header-right">
          <button 
            className="dark-mode-toggle"
            onClick={() => setDarkMode(!darkMode)}
            title="Toggle dark mode"
          >
            {darkMode ? '☀️' : '🌙'}
          </button>
          <div className="user-menu" ref={menuRef}>
            <button className="user-avatar" onClick={() => setMenuOpen(!menuOpen)}>
              {userInitials}
            </button>
            {menuOpen && (
              <div className="user-menu-dropdown">
                <div className="user-menu-header">
                  <div className="user-menu-name">{username}</div>
                  <div className="user-menu-email">{userEmail || 'No email'}</div>
                </div>
                <button className="user-menu-item">My Profile</button>
                <button className="user-menu-item">Settings</button>
                <button className="user-menu-item logout" onClick={handleLogout}>Logout</button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="transactions-main">
        {/* Page Header */}
        <div className="page-header">
          <div className="breadcrumb">
            <a href="/services/dashboard">PORTAL</a>
            <span> {'>'}  </span>
            <span>TRANSACTION HISTORY</span>
          </div>
          <div className="page-title-section">
            <div>
              <h1 className="page-title">All Transactions</h1>
              <p className="page-subtitle">Review and manage all service requests recorded in the system.</p>
            </div>
            <button className="export-btn" onClick={handleExportReport}>
              📥 Export Report
            </button>
          </div>
        </div>

        {/* Filters Section */}
        <section className="filters-section">
          <div className="filters-grid">
            {/* Search */}
            <div className="filter-group">
              <label className="filter-label">Search Patient</label>
              <div className="filter-input-wrapper">
                <span className="search-icon">🔍</span>
                <input 
                  className="filter-input"
                  placeholder="ID, Name, or Phone..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  type="text"
                />
              </div>
            </div>

            {/* Service Category */}
            <div className="filter-group">
              <label className="filter-label">Service Category</label>
              <select 
                className="filter-select"
                value={selectedService}
                onChange={(e) => setSelectedService(e.target.value)}
              >
                <option value="">All Services</option>
                <option value="MEDICINE ASSISTANT">Medicine Assistant</option>
                <option value="BURIAL ASSISTANCE">Burial Assistance</option>
                <option value="EDUCATION SUPPORT">Education Support</option>
                <option value="FINANCIAL AID">Financial Aid</option>
                <option value="LIVELIHOOD PROGRAMS">Livelihood Programs</option>
                <option value="HEALTH CHECKUP">Health Checkup</option>
              </select>
            </div>

            {/* Date Range */}
            <div className="filter-group date-range">
              <label className="filter-label">Date Range</label>
              <div className="date-inputs">
                <input 
                  className="filter-input"
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
                <input 
                  className="filter-input"
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
              </div>
            </div>
          </div>

          {/* Quick Filters */}
          <div className="quick-filters">
            <span className="quick-filters-label">Quick Filters:</span>
            <button 
              className={`filter-btn ${!startDate && !endDate ? 'active' : ''}`}
              onClick={() => handleQuickFilter('all')}
            >
              All Time
            </button>
            <button 
              className="filter-btn"
              onClick={() => handleQuickFilter('today')}
            >
              Today
            </button>
            <button 
              className="filter-btn"
              onClick={() => handleQuickFilter('week')}
            >
              This Week
            </button>
            <button 
              className="filter-btn"
              onClick={() => handleQuickFilter('month')}
            >
              This Month
            </button>
          </div>
        </section>

        {/* Transactions Table */}
        <section className="table-section">
          <div className="table-wrapper">
            <table className="transactions-table">
              <thead>
                <tr>
                  <th>TRANSACTION ID</th>
                  <th>DATE/TIME</th>
                  <th>PATIENT / CITIZEN NAME</th>
                  <th>SERVICE CATEGORY</th>
                  <th>STATUS</th>
                  <th>ACTIONS</th>
                </tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr>
                    <td colSpan="6" className="table-loading">Loading transactions...</td>
                  </tr>
                ) : paginatedTransactions.length === 0 ? (
                  <tr>
                    <td colSpan="6" className="table-empty">No transactions found</td>
                  </tr>
                ) : (
                  paginatedTransactions.map(transaction => {
                    const serviceInfo = SERVICE_COLORS[transaction.serviceName] || { color: '#999', name: transaction.serviceName };
                    const statusStyle = STATUS_STYLES[transaction.status] || STATUS_STYLES['PENDING'];
                    return (
                      <tr key={transaction.id}>
                        <td className="txn-id">{transaction.transactionId}</td>
                        <td className="txn-date">
                          <div className="date">{transaction.createdAt.toLocaleDateString()}</div>
                          <div className="time">{transaction.createdAt.toLocaleTimeString()}</div>
                        </td>
                        <td className="txn-name">
                          <div className="name">{transaction.fullName}</div>
                          <div className="id">ID: {transaction.userId}</div>
                        </td>
                        <td className="txn-service">
                          <div className="service-dot" style={{ backgroundColor: serviceInfo.color }}></div>
                          <span>{serviceInfo.name}</span>
                        </td>
                        <td className="txn-status">
                          <span 
                            className="status-badge"
                            style={{ 
                              backgroundColor: statusStyle.bg, 
                              color: statusStyle.text,
                              borderColor: statusStyle.border
                            }}
                          >
                            {transaction.status}
                          </span>
                        </td>
                        <td className="txn-actions">
                          <button 
                            className="action-btn" 
                            title="View Details"
                            onClick={() => navigate(`/services/transaction/${transaction.id}`)}
                          >
                            👁️
                          </button>
                          <button className="action-btn" title="Edit">✏️</button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          <div className="pagination-section">
            <div className="pagination-info">
              <p className="pagination-text">
                Showing <strong>{(currentPage - 1) * itemsPerPage + 1}</strong> of <strong>{Math.min(currentPage * itemsPerPage, filteredTransactions.length)}</strong> of <strong>{filteredTransactions.length}</strong> transactions
              </p>
              <div className="rows-selector">
                <label>Rows:</label>
                <select 
                  value={itemsPerPage}
                  onChange={(e) => {
                    setItemsPerPage(parseInt(e.target.value));
                    setCurrentPage(1);
                  }}
                >
                  <option>10</option>
                  <option>25</option>
                  <option>50</option>
                </select>
              </div>
            </div>
            <div className="pagination-controls">
              <button 
                className="pagination-btn"
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(1)}
                title="First page"
              >
                ⏮️
              </button>
              <button 
                className="pagination-btn"
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(currentPage - 1)}
                title="Previous page"
              >
                ⬅️
              </button>
              <div className="page-numbers">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => (
                  <button
                    key={i + 1}
                    className={`page-btn ${currentPage === i + 1 ? 'active' : ''}`}
                    onClick={() => setCurrentPage(i + 1)}
                  >
                    {i + 1}
                  </button>
                ))}
                {totalPages > 5 && (
                  <>
                    <span className="page-dots">...</span>
                    <button
                      className={`page-btn ${currentPage === totalPages ? 'active' : ''}`}
                      onClick={() => setCurrentPage(totalPages)}
                    >
                      {totalPages}
                    </button>
                  </>
                )}
              </div>
              <button 
                className="pagination-btn"
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage(currentPage + 1)}
                title="Next page"
              >
                ➡️
              </button>
              <button 
                className="pagination-btn"
                disabled={currentPage === totalPages}
                onClick={() => setCurrentPage(totalPages)}
                title="Last page"
              >
                ⏭️
              </button>
            </div>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer className="transactions-footer">
        <p>© 2026 AKSYON AGAD Community Services Portal. All Rights Reserved.</p>
      </footer>
    </div>
  );
};

export default TransactionsPage;
