import React, { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../../../firebase';
import { addDoc, collection, query, where, getDocs } from 'firebase/firestore';
import Topbar from '../../components/Mainpage_Topbar';
import LoadingScreen from '../../../components/LoadingScreen';
import { getServiceTemplate } from './serviceFormTemplates';
import './ServiceDetail.css';

// Service definitions
const ALL_SERVICES = [
  {
    id: 'medicine-assistant',
    name: 'MEDICINE ASSISTANT',
    icon: '💊',
    color: '#f43f5e',
    description: 'Ensuring safe, timely, and accurate medication use by providing guidance, reminders, and patient support.',
    type: 'medicine'
  },
  {
    id: 'burial-assistance',
    name: 'BURIAL ASSISTANCE',
    icon: '🤝',
    color: '#f59e0b',
    description: 'Supporting families in their time of loss with financial aid and logistical arrangements for funeral services.',
    type: 'burial'
  },
  {
    id: 'education-support',
    name: 'EDUCATION SUPPORT',
    icon: '🎓',
    color: '#3b82f6',
    description: 'Educational scholarships, supply kits, and tutoring programs for students from low-income households.',
    type: 'education'
  },
  {
    id: 'financial-aid',
    name: 'FINANCIAL AID',
    icon: '💼',
    color: '#10b981',
    description: 'Immediate monetary assistance for emergency situations and essential living expenses.',
    type: 'financial'
  },
  {
    id: 'livelihood-programs',
    name: 'LIVELIHOOD PROGRAMS',
    icon: '💼',
    color: '#a855f7',
    description: 'Skills training, job placement assistance, and seed funding for community enterprise initiatives.',
    type: 'livelihood'
  },
  {
    id: 'health-checkup',
    name: 'HEALTH CHECKUP',
    icon: '⚕️',
    color: '#06b6d4',
    description: 'Schedule appointments for regular health screenings, vaccinations, and basic medical consultations.',
    type: 'health'
  }
];

const ServiceDetail = ({ username = 'User' }) => {
  const { serviceId } = useParams();
  const navigate = useNavigate();
  const [service, setService] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [currentStep, setCurrentStep] = useState(1);
  const [submitting, setSubmitting] = useState(false);
  const [formData, setFormData] = useState({});
  const [voterSearchResults, setVoterSearchResults] = useState([]);
  const [showVoterResults, setShowVoterResults] = useState(false);
  const [selectedVoter, setSelectedVoter] = useState(null);
  const [isAddingNewBeneficiary, setIsAddingNewBeneficiary] = useState(false);
  const [isEditingVoterDetails, setIsEditingVoterDetails] = useState(false);
  const [showStartModal, setShowStartModal] = useState(true);
  const [showApplicationTypeModal, setShowApplicationTypeModal] = useState(false);
  const [applicationType, setApplicationType] = useState(null);
  const [medicineSearchResults, setMedicineSearchResults] = useState([]);
  const [showMedicineResults, setShowMedicineResults] = useState(false);
  const [activeMedicinePrescriptionIdx, setActiveMedicinePrescriptionIdx] = useState(null);
  const [submitButtonClicked, setSubmitButtonClicked] = useState(false);

  const fetchService = useCallback(async () => {
    try {
      setLoading(true);
      // Find service from the hardcoded ALL_SERVICES array
      const foundService = ALL_SERVICES.find(s => s.id === serviceId);
      
      if (foundService) {
        const serviceData = { ...foundService };
        setService(serviceData);
        
        // Initialize form data based on service type
        const template = getServiceTemplate(serviceData.type || 'medical');
        const initialData = { username };
        Object.values(template.fields).forEach(stepFields => {
          stepFields.forEach(field => {
            if (field.name === 'fullName') {
              initialData[field.name] = username;
            } else {
              initialData[field.name] = '';
            }
          });
        });
        setFormData(initialData);
        setError('');
      } else {
        setError('Service not found');
        setService(null);
      }
    } catch (err) {
      console.error('Error fetching service:', err);
      setError('Failed to load service details');
      setService(null);
    } finally {
      setLoading(false);
    }
  }, [serviceId, username]);

  useEffect(() => {
    fetchService();
  }, [fetchService]);

  const searchVoters = async (searchTerm) => {
    if (!searchTerm.trim() || searchTerm.length < 1) {
      setVoterSearchResults([]);
      setShowVoterResults(false);
      return;
    }

    try {
      const votersCollection = collection(db, 'voters');
      // Convert to uppercase for case-insensitive search
      const searchUpper = searchTerm.toUpperCase();
      const q = query(
        votersCollection, 
        where('VotersName', '>=', searchUpper), 
        where('VotersName', '<=', searchUpper + '\uf8ff')
      );
      const querySnapshot = await getDocs(q);
      
      const results = [];
      querySnapshot.forEach((doc) => {
        results.push({
          id: doc.id,
          ...doc.data()
        });
      });
      
      setVoterSearchResults(results);
      setShowVoterResults(true);
    } catch (err) {
      console.error('Error searching voters:', err);
      setVoterSearchResults([]);
    }
  };

  const handleSelectVoter = (voter) => {
    setSelectedVoter(voter);
    setFormData(prev => ({
      ...prev,
      fullName: voter.VotersName || '',
      birthDate: voter.BirthDate || '',
      sex: voter.Sex || '',
      politicalStatus: voter.PoliticalStatus || '',
      profiledBarangay: voter.ProfiledBarangay || '',
      profiledPurok: voter.ProfiledPurok || '',
      votingStatus: voter.VotingStatus || '',
    }));
    setShowVoterResults(false);
    setVoterSearchResults([]);
    setIsAddingNewBeneficiary(false);
  };

  const searchMedicines = async (searchTerm) => {
    if (!searchTerm.trim() || searchTerm.length < 1) {
      setMedicineSearchResults([]);
      setShowMedicineResults(false);
      return;
    }

    try {
      const medicinesCollection = collection(db, 'medicines');
      // Convert to lowercase for case-insensitive search
      const searchLower = searchTerm.toLowerCase();
      
      // Try to find medicines with lowercase medicineName
      const q1 = query(
        medicinesCollection, 
        where('medicineName', '>=', searchLower), 
        where('medicineName', '<=', searchLower + '\uf8ff')
      );
      
      const results = [];
      let querySnapshot = await getDocs(q1);
      
      querySnapshot.forEach((doc) => {
        const data = doc.data();
        // Filter on client side for case-insensitive matching
        if (data.medicineName && data.medicineName.toLowerCase().includes(searchLower)) {
          results.push({
            id: doc.id,
            ...data
          });
        }
      });
      
      // If no results found with lowercase, get all and filter client-side
      if (results.length === 0) {
        const allMedicinesQuery = query(medicinesCollection);
        querySnapshot = await getDocs(allMedicinesQuery);
        
        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (data.medicineName && data.medicineName.toLowerCase().includes(searchLower)) {
            results.push({
              id: doc.id,
              ...data
            });
          }
        });
      }
      
      console.log('Search term:', searchLower, 'Results found:', results.length, results);
      setMedicineSearchResults(results);
      setShowMedicineResults(results.length > 0);
    } catch (err) {
      console.error('Error searching medicines:', err);
      setMedicineSearchResults([]);
      setShowMedicineResults(false);
    }
  };

  const handleSelectMedicine = (medicine, prescriptionIdx) => {
    const newPrescriptions = [...(formData.prescriptions || [])];
    // Store full name + dosage for display, but keep individual fields for data
    const displayName = `${medicine.medicineName} + ${medicine.dosage}`;
    newPrescriptions[prescriptionIdx] = {
      ...newPrescriptions[prescriptionIdx],
      name: displayName,
      medicineName: medicine.medicineName || '',
      dosage: medicine.dosage || '',
      description: medicine.description || ''
    };
    setFormData(prev => ({ ...prev, prescriptions: newPrescriptions }));
    setShowMedicineResults(false);
    setMedicineSearchResults([]);
    setActiveMedicinePrescriptionIdx(null);
  };

  const handleFieldChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFullNameKeyPress = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (service?.type === 'medicine' && formData.fullName?.trim()) {
        searchVoters(formData.fullName);
      }
    }
  };

  const validateCurrentStep = () => {
    if (!service) return false;
    
    const template = getServiceTemplate(service.type || 'medical');
    const stepKey = `step${currentStep}`;
    const fieldsToValidate = template.fields[stepKey] || [];

    for (let field of fieldsToValidate) {
      // Special validation for prescription table
      if (field.type === 'prescriptionTable' && field.required) {
        const prescriptions = formData.prescriptions || [];
        // Check if there's at least one prescription with medicine name
        const hasValidPrescription = prescriptions.some(p => p.name && p.name.trim());
        if (!hasValidPrescription) {
          setError(`${field.label} is required`);
          return false;
        }
      } else if (field.required && !formData[field.name]?.toString().trim()) {
        setError(`${field.label} is required`);
        return false;
      }
      
      if (field.type === 'email' && formData[field.name]) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(formData[field.name])) {
          setError('Please enter a valid email address');
          return false;
        }
      }
    }
    
    setError('');
    return true;
  };

  const handleNext = () => {
    if (validateCurrentStep()) {
      if (!service) return;
      const template = getServiceTemplate(service.type || 'medical');
      if (currentStep < template.steps.length) {
        setCurrentStep(currentStep + 1);
        setSubmitButtonClicked(false); // Reset flag when moving to next step
      }
    }
  };

  const handlePrevious = () => {
    setError('');
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
      setSubmitButtonClicked(false); // Reset flag when going to previous step
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Only allow submission if submit button was explicitly clicked
    if (!submitButtonClicked) {
      console.log('Submit button not clicked - ignoring form submission');
      return;
    }
    
    // Only allow submission on the last step (Review step)
    if (!service) {
      console.log('Cannot submit: service not loaded');
      return;
    }
    
    const template = getServiceTemplate(service.type || 'medical');
    console.log('Current step:', currentStep, 'Total steps:', template.steps.length);
    
    // Exit early if not on the last step
    if (currentStep !== template.steps.length) {
      console.log('Cannot submit: not on review step');
      return;
    }
    
    if (!validateCurrentStep()) {
      console.log('Cannot submit: validation failed');
      return;
    }

    console.log('Starting submission...');
    setSubmitting(true);
    try {
      // Organize Step 1 (Personal Information) data
      const step1Data = {
        fullName: formData.fullName || '',
        birthDate: formData.birthDate || '',
        sex: formData.sex || '',
        politicalStatus: formData.politicalStatus || '',
        profiledBarangay: formData.profiledBarangay || '',
        profiledPurok: formData.profiledPurok || '',
        votingStatus: formData.votingStatus || ''
      };

      // Organize Step 2 (Medicine Details) data
      const step2Data = {
        prescriptions: formData.prescriptions || []
      };

      // Save application to Firestore with organized structure
      await addDoc(collection(db, 'applications'), {
        serviceId: service.id,
        serviceName: service.name,
        serviceType: service.type || 'medical',
        applicationType: applicationType,
        userName: username,
        
        // Step 1: Personal Information
        step1: step1Data,
        
        // Step 2: Medicine/Service Details
        step2: step2Data,
        
        // Complete form data (backup)
        formData: formData,
        
        status: 'pending',
        createdAt: new Date(),
        updatedAt: new Date()
      });

      setSubmitted(true);
      setError('');
    } catch (err) {
      console.error('Error submitting application:', err);
      setError('Failed to submit application. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleBack = () => {
    setShowApplicationTypeModal(true);
    setApplicationType(null);
    setCurrentStep(1);
    navigate('/services/dashboard');
  };

  const handleStartApplication = () => {
    setShowStartModal(false);
    setShowApplicationTypeModal(true);
  };

  const handleApplicationTypeSelect = (type) => {
    setApplicationType(type);
    setFormData(prev => ({ ...prev, applicationType: type }));
    setShowApplicationTypeModal(false);
  };

  if (loading) {
    return <LoadingScreen message="Loading service details..." />;
  }

  if (error && !service) {
    return (
      <>
        <Topbar activePage="services" username={username} hideNavLinks={true} />
        <div className="service-detail-container">
          <div className="error-state">
            <p className="error-message">❌ {error}</p>
            <button className="back-button" onClick={handleBack}>← Back to Services</button>
          </div>
        </div>
      </>
    );
  }

  if (!service) {
    return (
      <>
        <Topbar activePage="services" username={username} hideNavLinks={true} />
        <div className="service-detail-container">
          <div className="loading-state">
            <p>Service not found</p>
          </div>
        </div>
      </>
    );
  }

  const template = getServiceTemplate(service.type || 'medical');
  const stepKey = `step${currentStep}`;
  const currentFields = template.fields[stepKey] || [];
  const isLastStep = currentStep === template.steps.length;
  const isFirstStep = currentStep === 1;

  return (
    <>
      <Topbar activePage="services" username={username} hideNavLinks={true} />
      <div className="service-detail-container">
        <div className="detail-header">
          <button className="back-button" onClick={handleBack}>← Back to Services</button>
        </div>

        {/* Start Application Modal */}
        {showStartModal && (
          <div className="modal-overlay">
            <div className="modal-content">
              <button 
                className="modal-close" 
                onClick={() => navigate('/services/dashboard')}
                title="Close and go back to services"
              >
                ✕
              </button>
              <div className="service-modal-header">
                <div className="modal-service-icon" style={{ color: service.color }}>
                  {service.icon}
                </div>
                <h2>{service.name}</h2>
              </div>
              <p className="modal-service-description">{service.description}</p>
              <button
                className="start-application-btn"
                style={{ backgroundColor: service.color }}
                onClick={handleStartApplication}
              >
                Start Application →
              </button>
            </div>
          </div>
        )}

        {/* Application Type Modal */}
        {showApplicationTypeModal && (
          <div className="modal-overlay">
            <div className="modal-content">
              <button 
                className="modal-close" 
                onClick={() => navigate('/services/dashboard')}
                title="Close and go back to services"
              >
                ✕
              </button>
              <h2>Select Application Type</h2>
              <p>Is this application for yourself or for someone else?</p>
              <div className="modal-buttons">
                <button
                  className="modal-btn own-btn"
                  onClick={() => handleApplicationTypeSelect('OWN')}
                >
                  👤 OWN
                </button>
                <button
                  className="modal-btn authorization-btn"
                  onClick={() => handleApplicationTypeSelect('AUTHORIZATION')}
                >
                  📝 AUTHORIZATION
                </button>
              </div>
            </div>
          </div>
        )}

        <div className="detail-content">
          <div className="service-info">
            <div className="info-icon" style={{ color: service.color }}>
              {service.icon}
            </div>
            <h1>{service.name}</h1>
            <p className="info-description">{service.description}</p>
          </div>

          {submitted ? (
            <div className="success-container">
              <div className="success-message">
                <div className="success-icon">✓</div>
                <h2>Application Submitted!</h2>
                <p>Thank you for applying for {service.name}</p>
                <p className="success-note">We will review your application and get back to you soon.</p>
                <button 
                  type="button"
                  className="success-btn"
                  style={{ background: service.color }}
                  onClick={() => navigate('/services/dashboard')}
                >
                  Back to Services
                </button>
              </div>
            </div>
          ) : (
            <div className="application-form-container">
              {/* Step Indicator */}
              <div className="step-indicator">
                {template.steps.map((step, index) => (
                  <div key={index} className={`step ${index + 1 === currentStep ? 'active' : index + 1 < currentStep ? 'completed' : ''}`}>
                    <div className="step-number">{index + 1 < currentStep ? '✓' : index + 1}</div>
                    <div className="step-label">{step}</div>
                  </div>
                ))}
              </div>

              <h2>Step {currentStep} of {template.steps.length}: {template.steps[currentStep - 1]}</h2>
              
              {error && <div className="error-alert">{error}</div>}

              <form onSubmit={handleSubmit} className="application-form">
                {currentStep === template.steps.length ? (
                  // REVIEW STEP
                  <div className="review-container">
                    <div className="review-section">
                      <h3>📋 Review Your Information</h3>
                      
                      {/* STEP 1: Personal Information */}
                      <div className="review-step">
                        <div className="review-step-header">
                          <span className="step-badge">Step 1</span>
                          <h4>Your Information</h4>
                        </div>
                        <div className="review-details">
                          {service?.type === 'medicine' ? (
                            // For Medicine Assistant
                            <>
                              <div className="review-item">
                                <label>Full Name:</label>
                                <span>{formData.fullName || 'N/A'}</span>
                              </div>
                              {selectedVoter && (
                                <>
                                  <div className="review-item">
                                    <label>Birth Date:</label>
                                    <span>{formData.birthDate || 'N/A'}</span>
                                  </div>
                                  <div className="review-item">
                                    <label>Sex:</label>
                                    <span>{formData.sex || 'N/A'}</span>
                                  </div>
                                  <div className="review-item">
                                    <label>Political Status:</label>
                                    <span>{formData.politicalStatus || 'N/A'}</span>
                                  </div>
                                  <div className="review-item">
                                    <label>Barangay:</label>
                                    <span>{formData.profiledBarangay || 'N/A'}</span>
                                  </div>
                                  <div className="review-item">
                                    <label>Purok:</label>
                                    <span>{formData.profiledPurok || 'N/A'}</span>
                                  </div>
                                  <div className="review-item">
                                    <label>Voting Status:</label>
                                    <span>{formData.votingStatus || 'N/A'}</span>
                                  </div>
                                </>
                              )}
                            </>
                          ) : (
                            // For other service types
                            template.fields.step1?.map((field) => (
                              <div key={field.name} className="review-item">
                                <label>{field.label}:</label>
                                <span>{formData[field.name] || 'N/A'}</span>
                              </div>
                            ))
                          )}
                        </div>
                      </div>

                      {/* STEP 2: Details */}
                      <div className="review-step">
                        <div className="review-step-header">
                          <span className="step-badge">Step 2</span>
                          <h4>{service?.type === 'medicine' ? 'Medicine Details' : 'Service Details'}</h4>
                        </div>
                        <div className="review-details">
                          {service?.type === 'medicine' ? (
                            // For Medicine Assistant - show prescription table
                            <>
                              {(formData.prescriptions || []).length > 0 ? (
                                <>
                                  <table className="review-prescription-table">
                                    <thead>
                                      <tr>
                                        <th>QTY</th>
                                        <th>Medicine</th>
                                        <th>Price</th>
                                        <th>Total</th>
                                      </tr>
                                    </thead>
                                    <tbody>
                                      {(formData.prescriptions || []).map((prescription, idx) => (
                                        <tr key={idx}>
                                          <td>{prescription.qty || 0}</td>
                                          <td>{prescription.name || 'N/A'}</td>
                                          <td>₱{(prescription.price || 0).toFixed(2)}</td>
                                          <td>₱{((prescription.qty || 0) * (prescription.price || 0)).toFixed(2)}</td>
                                        </tr>
                                      ))}
                                    </tbody>
                                  </table>
                                  <div className="review-grand-total">
                                    <strong>GRAND TOTAL: ₱{(formData.prescriptions || []).reduce((sum, p) => sum + ((p.qty || 0) * (p.price || 0)), 0).toFixed(2)}</strong>
                                  </div>
                                </>
                              ) : (
                                <p className="no-data">No medicines added</p>
                              )}
                            </>
                          ) : (
                            // For other service types
                            template.fields.step2?.map((field) => (
                              <div key={field.name} className="review-item">
                                <label>{field.label}:</label>
                                <span>{formData[field.name] || 'N/A'}</span>
                              </div>
                            ))
                          )}
                        </div>
                      </div>

                      <div className="review-notice">
                        <p>📌 Please review all information above before submitting your application.</p>
                      </div>
                    </div>
                  </div>
                ) : (
                  // FORM FIELDS FOR STEPS 1 & 2
                  <div className="form-fields">
                  {currentFields.map((field) => (
                    <div key={field.name} className="form-group">
                      <label>
                        {field.label}
                        {field.required && <span className="required">*</span>}
                      </label>
                      
                      {field.type === 'prescriptionTable' ? (
                        <div className="prescription-table-container">
                          <table className="prescription-table">
                            <thead>
                              <tr>
                                <th>QTY</th>
                                <th>PRESCRIPTION</th>
                                <th>PRICE</th>
                                <th>TOTAL</th>
                                <th>ACTION</th>
                              </tr>
                            </thead>
                            <tbody>
                              {(formData.prescriptions || []).map((prescription, idx) => (
                                <tr key={idx}>
                                  <td>
                                    <input
                                      type="number"
                                      value={prescription.qty || ''}
                                      onChange={(e) => {
                                        const newPrescriptions = [...(formData.prescriptions || [])];
                                        newPrescriptions[idx].qty = parseInt(e.target.value) || 0;
                                        newPrescriptions[idx].total = (newPrescriptions[idx].qty || 0) * (newPrescriptions[idx].price || 0);
                                        setFormData(prev => ({ ...prev, prescriptions: newPrescriptions }));
                                      }}
                                      className="input-small"
                                      min="0"
                                      disabled={submitting}
                                    />
                                  </td>
                                  <td>
                                    <div className="medicine-input-wrapper">
                                      <input
                                        type="text"
                                        value={prescription.name || ''}
                                        onChange={(e) => {
                                          const newPrescriptions = [...(formData.prescriptions || [])];
                                          newPrescriptions[idx].name = e.target.value;
                                          setFormData(prev => ({ ...prev, prescriptions: newPrescriptions }));
                                        }}
                                        onKeyPress={(e) => {
                                          if (e.key === 'Enter') {
                                            e.preventDefault();
                                            setActiveMedicinePrescriptionIdx(idx);
                                            searchMedicines(prescription.name);
                                          }
                                        }}
                                        onFocus={() => setActiveMedicinePrescriptionIdx(idx)}
                                        placeholder="Medicine name (Enter to search)"
                                        className="input-medium"
                                        disabled={submitting}
                                      />
                                      {showMedicineResults && activeMedicinePrescriptionIdx === idx && medicineSearchResults.length > 0 && (
                                        <div className="medicine-results-dropdown">
                                          {medicineSearchResults.map((medicine) => (
                                            <div
                                              key={medicine.id}
                                              className="medicine-result-item"
                                              onClick={() => handleSelectMedicine(medicine, idx)}
                                            >
                                              <strong>{medicine.medicineName}</strong>
                                              <small>{medicine.dosage}</small>
                                            </div>
                                          ))}
                                        </div>
                                      )}
                                    </div>
                                  </td>
                                  <td>
                                    <input
                                      type="number"
                                      value={prescription.price || ''}
                                      onChange={(e) => {
                                        const newPrescriptions = [...(formData.prescriptions || [])];
                                        newPrescriptions[idx].price = parseFloat(e.target.value) || 0;
                                        newPrescriptions[idx].total = (newPrescriptions[idx].qty || 0) * (newPrescriptions[idx].price || 0);
                                        setFormData(prev => ({ ...prev, prescriptions: newPrescriptions }));
                                      }}
                                      className="input-small"
                                      min="0"
                                      step="0.01"
                                      disabled={submitting}
                                    />
                                  </td>
                                  <td className="total-cell">
                                    {((prescription.qty || 0) * (prescription.price || 0)).toFixed(2)}
                                  </td>
                                  <td>
                                    <button
                                      type="button"
                                      onClick={() => {
                                        const newPrescriptions = formData.prescriptions.filter((_, i) => i !== idx);
                                        setFormData(prev => ({ ...prev, prescriptions: newPrescriptions }));
                                      }}
                                      className="delete-btn"
                                      disabled={submitting}
                                    >
                                      🗑️
                                    </button>
                                  </td>
                                </tr>
                              ))}
                              <tr className="add-row">
                                <td colSpan="5">
                                  <button
                                    type="button"
                                    onClick={() => {
                                      setFormData(prev => ({
                                        ...prev,
                                        prescriptions: [...(prev.prescriptions || []), { qty: 0, name: '', price: 0, total: 0 }]
                                      }));
                                    }}
                                    className="add-medicine-btn"
                                    disabled={submitting}
                                  >
                                    ➕ Add Medicine
                                  </button>
                                </td>
                              </tr>
                            </tbody>
                          </table>
                          <div className="grand-total-section">
                            <p className="grand-total">
                              <strong>GRAND TOTAL = ₱{(formData.prescriptions || []).reduce((sum, p) => sum + (p.total || 0), 0).toFixed(2)}</strong>
                            </p>
                          </div>
                        </div>
                      ) : field.type === 'textarea' ? (
                        <textarea
                          name={field.name}
                          value={formData[field.name] || ''}
                          onChange={handleFieldChange}
                          placeholder={field.placeholder || `Enter ${field.label.toLowerCase()}`}
                          className="form-input"
                          rows="4"
                          disabled={submitting}
                        />
                      ) : field.type === 'select' ? (
                        <select
                          name={field.name}
                          value={formData[field.name] || ''}
                          onChange={handleFieldChange}
                          className="form-input"
                          disabled={submitting}
                        >
                          <option value="">Select {field.label}</option>
                          {field.options?.map(option => (
                            <option key={option} value={option}>{option}</option>
                          ))}
                        </select>
                      ) : (
                        <>
                          <input
                            type={field.type}
                            name={field.name}
                            value={formData[field.name] || ''}
                            onChange={handleFieldChange}
                            onKeyPress={field.name === 'fullName' && service?.type === 'medicine' ? handleFullNameKeyPress : null}
                            placeholder={field.placeholder || `Enter ${field.label.toLowerCase()}`}
                            className="form-input"
                            disabled={submitting}
                          />
                          
                          {/* Show hint to press Enter for MEDICINE ASSISTANT fullName field */}
                          {field.name === 'fullName' && service?.type === 'medicine' && !selectedVoter && formData.fullName && !showVoterResults && (
                            <div className="search-hint">
                              Press <strong>Enter</strong> to search for voter
                            </div>
                          )}
                          
                          {/* Voter Search Results for MEDICINE ASSISTANT fullName field */}
                          {field.name === 'fullName' && service?.type === 'medicine' && !selectedVoter && (
                            <>
                              {showVoterResults && voterSearchResults.length > 0 ? (
                                <div className="voter-search-results">
                                  <p className="search-label">Found {voterSearchResults.length} voter(s):</p>
                                  {voterSearchResults.map((voter) => (
                                    <div
                                      key={voter.id}
                                      className="voter-result-item"
                                      onClick={() => handleSelectVoter(voter)}
                                    >
                                      <div className="voter-name">{voter.VotersName}</div>
                                      <div className="voter-details">
                                        <span>📅 {voter.BirthDate || 'N/A'}</span>
                                        <span>🏘️ {voter.ProfiledBarangay || 'N/A'}</span>
                                        <span>👤 {voter.VotingStatus || 'N/A'}</span>
                                      </div>
                                    </div>
                                  ))}
                                </div>
                              ) : showVoterResults && formData.fullName && voterSearchResults.length === 0 && (
                                <div className="voter-search-results">
                                  <div className="no-results">
                                    <p>No voters found matching "{formData.fullName}"</p>
                                    <button 
                                      type="button"
                                      className="add-beneficiary-btn"
                                      onClick={() => setIsAddingNewBeneficiary(true)}
                                    >
                                      ➕ Add New Beneficiary
                                    </button>
                                  </div>
                                </div>
                              )}
                            </>
                          )}
                        </>
                      )}
                    </div>
                  ))}
                  
                  {/* Show additional fields when voter is selected - RIGHT AFTER FULLNAME */}
                  {service?.type === 'medicine' && selectedVoter && currentStep === 1 && (
                    <>
                      <div className="voter-selected-info">
                        <div className="info-header">
                          <h4>✓ Voter Information</h4>
                          <div className="header-buttons">
                            <button
                              type="button"
                              className="search-again-btn"
                              onClick={() => {
                                setSelectedVoter(null);
                                setFormData(prev => ({ ...prev, fullName: '' }));
                                setIsEditingVoterDetails(false);
                              }}
                            >
                              🔍 Search Again
                            </button>
                            <button
                              type="button"
                              className={`edit-btn ${isEditingVoterDetails ? 'editing' : ''}`}
                              onClick={() => setIsEditingVoterDetails(!isEditingVoterDetails)}
                            >
                              {isEditingVoterDetails ? '✓ Done' : '✏️ Edit'}
                            </button>
                          </div>
                        </div>
                      </div>
                      <div className="form-group">
                        <label>Birth Date</label>
                        <input
                          type="text"
                          name="birthDate"
                          value={formData.birthDate || ''}
                          onChange={handleFieldChange}
                          placeholder="Birth date"
                          className="form-input"
                          disabled={!isEditingVoterDetails}
                        />
                      </div>
                      <div className="form-group">
                        <label>Sex</label>
                        <input
                          type="text"
                          name="sex"
                          value={formData.sex || ''}
                          onChange={handleFieldChange}
                          placeholder="Sex"
                          className="form-input"
                          disabled={!isEditingVoterDetails}
                        />
                      </div>
                      <div className="form-group">
                        <label>Political Status</label>
                        <input
                          type="text"
                          name="politicalStatus"
                          value={formData.politicalStatus || ''}
                          onChange={handleFieldChange}
                          placeholder="Political status"
                          className="form-input"
                          disabled={!isEditingVoterDetails}
                        />
                      </div>
                      <div className="form-group">
                        <label>Barangay</label>
                        <input
                          type="text"
                          name="profiledBarangay"
                          value={formData.profiledBarangay || ''}
                          onChange={handleFieldChange}
                          placeholder="Barangay"
                          className="form-input"
                          disabled={!isEditingVoterDetails}
                        />
                      </div>
                      <div className="form-group">
                        <label>Purok</label>
                        <input
                          type="text"
                          name="profiledPurok"
                          value={formData.profiledPurok || ''}
                          onChange={handleFieldChange}
                          placeholder="Purok"
                          className="form-input"
                          disabled={!isEditingVoterDetails}
                        />
                      </div>
                      <div className="form-group">
                        <label>Voting Status</label>
                        <input
                          type="text"
                          name="votingStatus"
                          value={formData.votingStatus || ''}
                          onChange={handleFieldChange}
                          placeholder="Voting status"
                          className="form-input"
                          disabled={!isEditingVoterDetails}
                        />
                      </div>
                    </>
                  )}
                  {service?.type === 'medicine' && isAddingNewBeneficiary && currentStep === 1 && (
                    <>
                      <div className="add-beneficiary-header">
                        <h3>➕ Add New Beneficiary</h3>
                        <button 
                          type="button"
                          className="close-btn"
                          onClick={() => {
                            setIsAddingNewBeneficiary(false);
                            setFormData(prev => ({ ...prev, fullName: '' }));
                          }}
                        >
                          ✕
                        </button>
                      </div>
                      <div className="form-group">
                        <label>Full Name <span className="required">*</span></label>
                        <input
                          type="text"
                          name="fullName"
                          value={formData.fullName || ''}
                          onChange={handleFieldChange}
                          placeholder="Enter full name"
                          className="form-input"
                          disabled={submitting}
                        />
                      </div>
                      <div className="form-group">
                        <label>Birth Date</label>
                        <input
                          type="date"
                          name="birthDate"
                          value={formData.birthDate || ''}
                          onChange={handleFieldChange}
                          className="form-input"
                          disabled={submitting}
                        />
                      </div>
                      <div className="form-group">
                        <label>Barangay</label>
                        <input
                          type="text"
                          name="barangay"
                          value={formData.barangay || ''}
                          onChange={handleFieldChange}
                          placeholder="Enter barangay"
                          className="form-input"
                          disabled={submitting}
                        />
                      </div>
                      <div className="form-group">
                        <label>Purok</label>
                        <input
                          type="text"
                          name="purok"
                          value={formData.purok || ''}
                          onChange={handleFieldChange}
                          placeholder="Enter purok"
                          className="form-input"
                          disabled={submitting}
                        />
                      </div>
                      <div className="form-group">
                        <label>City</label>
                        <input
                          type="text"
                          name="city"
                          value={formData.city || ''}
                          onChange={handleFieldChange}
                          placeholder="Enter city"
                          className="form-input"
                          disabled={submitting}
                        />
                      </div>
                      <div className="form-group">
                        <label>Province</label>
                        <input
                          type="text"
                          name="province"
                          value={formData.province || ''}
                          onChange={handleFieldChange}
                          placeholder="Enter province"
                          className="form-input"
                          disabled={submitting}
                        />
                      </div>
                    </>
                  )}
                </div>
                )}

                <div className="form-actions">
                  {!isFirstStep && (
                    <button 
                      type="button" 
                      className="cancel-btn"
                      onClick={handlePrevious}
                      disabled={submitting}
                    >
                      ← Previous
                    </button>
                  )}
                  
                  {isLastStep ? (
                    <button 
                      type="submit" 
                      className="submit-btn" 
                      style={{ background: service.color }}
                      disabled={submitting}
                      onClick={() => setSubmitButtonClicked(true)}
                    >
                      {submitting ? '⏳ Submitting...' : '✓ Submit Application'}
                    </button>
                  ) : (
                    <button 
                      type="button" 
                      className="submit-btn" 
                      style={{ background: service.color }}
                      onClick={handleNext}
                      disabled={submitting}
                    >
                      Next Step →
                    </button>
                  )}
                </div>
              </form>
            </div>
          )}
        </div>
      </div>
    </>
  );
};

export default ServiceDetail;
